window.TL={"eras":[{"i":"primeval","n":"الخليقة وبدايات البشرية","b":"من خلق العالم إلى الطوفان وتشتيت الناس عند بابل: الأحداث التأسيسية في التكوين ١–١١. تواريخ هذا العصر تقليدية وتقريبية جدًا.","a":-4100,"z":-2100,"c":"#7e6bc4"},{"i":"patriarchs","n":"زمن الآباء","b":"الله يدعو إبراهيم من بين النهرين ويقطع معه عهدًا يمتد في إسحاق ويعقوب ويوسف، وينتهي العصر ببيت إسرائيل ساكنًا في مصر.","a":-2100,"z":-1805,"c":"#c08a3e"},{"i":"egypt-exodus","n":"مصر والخروج","b":"إسرائيل يكثر في مصر ثم يُستعبد، والله يخلّصه بيد قوية على يد موسى: الخروج وسيناء وأربعون سنة في البرية.","a":-1805,"z":-1406,"c":"#c75b46"},{"i":"conquest-judges","n":"دخول الأرض والقضاة","b":"يشوع يقود إسرائيل إلى أرض الموعد، وعلى مدى قرون تدور الأسباط في دائرة من الارتداد والضيق والخلاص على يد القضاة. تواريخ القضاة تقديرية.","a":-1406,"z":-1050,"c":"#4a9b6e"},{"i":"united-kingdom","n":"المملكة الموحدة","b":"إسرائيل يصير مملكة في أيام شاول وداود وسليمان: قرن واحد فيه العهد مع داود وأخذ أورشليم وبناء الهيكل الأول.","a":-1050,"z":-930,"c":"#c4a23a"},{"i":"divided-kingdom","n":"المملكة المنقسمة","b":"المملكة تنقسم إلى إسرائيل في الشمال ويهوذا في الجنوب. الأنبياء ينادون ضد عبادة الأوثان، وأشور تسقط إسرائيل، ثم بابل تخرّب أورشليم والهيكل.","a":-930,"z":-586,"c":"#b05566"},{"i":"exile-return","n":"السبي والرجوع","b":"يهوذا يبكي على أنهار بابل، ثم يرجع بأمر ملوك فارس ليبني الهيكل وسور أورشليم: زمن دانيال وأستير وعزرا ونحميا.","a":-586,"z":-430,"c":"#4a86b8"},{"i":"intertestamental","n":"ما بين العهدين","b":"أربعة قرون بلا نبي، لكنها لم تكن هادئة: فتوحات اليونان، والترجمة السبعينية، وثورة المكابيين، ومجيء الرومان، فتهيأ المسرح لميلاد المسيح. معظم أحداث هذه الفترة من خارج أسفار الكتاب المقدس.","a":-430,"z":-6,"c":"#7d9b4a"},{"i":"life-of-christ","n":"حياة المسيح","b":"محور التاريخ: ميلاد يسوع الناصري وخدمته وموته وقيامته. الميلاد نحو ٥–٤ ق.م (لأن بداية التقويم الميلادي حُسبت بخطأ بسيط بعد قرون)، والصلب نحو ٣٠ أو ٣٣ م.","a":-6,"z":33,"c":"#e3c66b"},{"i":"early-church","n":"الكنيسة الأولى","b":"من يوم الخمسين إلى بطمس: الإنجيل ينتشر من أورشليم إلى رومية في جيل واحد، وتُكتب أسفار العهد الجديد، وينتهي عصر الرسل برؤيا يوحنا.","a":33,"z":100,"c":"#5bb8a8"}],"ev":[{"i":"creation","k":"b","e":"primeval","y":-4004,"t":"خلق العالم","j":-4003,"r":[["Gen",1,null,2,null]],"d":1,"l":"عدن","x":"الله يخلق السماوات والأرض في ستة أيام ويستريح في اليوم السابع، ويضع آدم وحواء في جنة عدن ليعيشا معه ويرعيا خليقته. التاريخ التقليدي ٤٠٠٤ ق.م من حساب أشر (Ussher)، والنص نفسه لا يذكر تاريخًا.","s":-4003,"pp":[["الله","god_1324"],["يسوع","jesus_905"],["الروح القدس","holy_spirit_7400"],["آدم","adam_78"],["حواء","eve_1231"]],"ll":["عدن"],"kx":"تبدأ الأسفار بكلمة «في البدء» (بالعبرية «بِريشيت»)، والفعل «خلق» (بارا) يُستخدم في العهد القديم لعمل الله وحده: أن يأتي بالشيء إلى الوجود. يتكلم الله فيكون كل شيء بكلمته، في ستة أيام متتابعة ثم يوم راحة صار نموذجًا للسبت. وتبلغ الخليقة قمتها في الإنسان المخلوق «على صورة الله»، ليكون وكيلًا لله على خليقته. وقول «نعمل الإنسان على صورتنا» (التكوين ١: ٢٦) يراه كثير من المفسرين المسيحيين إشارة مبكرة إلى سر الثالوث، وأن «الكلمة» الذي به كان كل شيء هو نفسه الذي صار جسدًا (يوحنا ١: ١–٣)."},{"i":"the-fall","k":"b","e":"primeval","y":-4000,"t":"سقوط الإنسان","j":-4003,"r":[["Gen",3,null,3,null]],"d":1,"l":"عدن","x":"آدم وحواء يأكلان من الشجرة المنهي عنها بإغواء الحية ويُطردان من الجنة. تدخل الخطية والموت إلى العالم، لكن الله يعد بأن نسل المرأة يسحق رأس الحية: أول وعد بالخلاص.","s":-4003,"pp":[["آدم","adam_78"],["حواء","eve_1231"],["الله","god_1324"]],"ll":["عدن"],"kx":"الحية التي يسميها سفر الرؤيا «الحية القديمة المدعو إبليس» (الرؤيا ١٢: ٩) تخدع حواء، ويخالف آدم وصية الله عن قصد، فتدخل الخطية والموت إلى الخليقة. تنكسر علاقة الإنسان بالله، ويُطرد من الجنة، وتُلعن الأرض بسببه. لكن الله يعلن في الحال وعدًا يسميه المفسرون «الإنجيل الأول»: نسل المرأة يسحق رأس الحية (التكوين ٣: ١٥)، وهو أول إشارة إلى انتصار المسيح على الشيطان. ومن هذا الأصحاح تنطلق في الكتاب كله قضايا الخطية الشاملة وحاجة الإنسان إلى فداء من الله."},{"i":"cain-and-abel","k":"b","e":"primeval","y":-3970,"t":"قايين يقتل هابيل","j":-3874,"r":[["Gen",4,null,4,null]],"d":2,"x":"قايين يغار لأن الرب نظر إلى قربان أخيه ولم ينظر إلى قربانه، فيقتل هابيل في الحقل: أول جريمة قتل. يُطرد قايين تائهًا شرقي عدن، وهناك يبني أول مدينة.","s":-3874,"pp":[["قايين","cain_533"],["هابيل","abel_13"]],"ll":["عدن"],"kx":"أول جريمة قتل تُظهر سرعة تصاعد الخطية: من التمرد على الله إلى العنف ضد الإنسان. قدّم هابيل من أبكار غنمه بالإيمان، فشهد له الله (عبرانيين ١١: ٤)، بينما قدّم قايين من أثمار الأرض بقلب غير مستقيم. وفي وضع الله علامة لقايين دينونة ورحمة معًا: يعاقبه لكنه يمنع الانتقام الكامل منه. ودم هابيل الذي يصرخ من الأرض يقابله في العهد الجديد «دم رش يتكلم أفضل من هابيل» (عبرانيين ١٢: ٢٤)، أي دم المسيح."},{"i":"t6","k":"b","e":"primeval","y":-3970,"j":-3874,"est":1,"t":"الرب يلعن قايين","r":[["Gen",4,11,4,16]],"s":-3873.99,"d":2,"pp":[["قايين","cain_533"],["الله","god_1324"]],"ll":["عدن","نود"],"x":"بعد قتل هابيل يسأل الرب قايين: «أين هابيل أخوك؟»، ويعلن أن صوت دم أخيه صارخ إليه من الأرض. يُلعن قايين ليكون تائهًا وهاربًا في الأرض، لكن الرب يجعل له علامة لكي لا يقتله كل من وجده، فيسكن في أرض نود شرقي عدن.","xs":1},{"i":"sumerian-writing","k":"w","e":"primeval","y":-3200,"t":"ظهور الكتابة المسمارية في سومر","l":"أوروك، بلاد ما بين النهرين","x":"كتبة مدينة أوروك السومرية يضغطون علامات مسمارية الشكل على ألواح الطين: أقدم نظام كتابة معروف، استُخدم أولًا للحسابات ثم للأدب والقانون والتاريخ.","s":-3200},{"i":"egypt-unified","k":"w","e":"primeval","y":-3100,"t":"توحيد مصر في عهد أوائل الفراعنة","l":"مصر","x":"توحيد الوجهين القبلي والبحري تحت تاج واحد، وينسبه التقليد إلى نارمر (مينا)، فتبدأ ثلاثة آلاف سنة من حضارة الفراعنة على ضفاف النيل.","s":-3100},{"i":"t23","k":"b","e":"primeval","y":-3074,"j":-3073,"est":1,"t":"موت آدم","r":[["Gen",5,5,5,5]],"s":-3072.9899,"d":2,"pp":[["آدم","adam_78"]],"ll":["عدن"],"x":"يموت آدم بعد أن عاش تسع مئة وثلاثين سنة، وتتحقق فيه كلمة الله: «لأنك تراب وإلى تراب تعود». ويتكرر في أصحاح المواليد بعده القول «ومات»، علامة على أن الموت صار نصيب كل البشر.","xs":1},{"i":"enoch","k":"b","e":"primeval","y":-3017,"t":"أخنوخ يسير مع الله","j":-3016,"r":[["Gen",5,21,5,24]],"d":2,"x":"أخنوخ، السابع من آدم، يسير مع الله ثلاث مئة سنة، «ولم يوجد لأن الله أخذه». هو واحد من اثنين فقط في الكتاب أُخذا دون أن يريا الموت.","s":-3016,"pp":[["أخنوخ","enoch_1192"],["متوشالح","methuselah_2042"],["الله","god_1324"]]},{"i":"t24","k":"b","e":"primeval","y":-3017,"j":-3016,"est":1,"t":"أخنوخ يؤخذ إلى السماء","r":[["Gen",5,24,5,24],["Heb",11,5,11,5]],"s":-3015.9899,"d":2,"pp":[["أخنوخ","enoch_1192"]],"x":"يسير أخنوخ مع الله ثم «لم يوجد لأن الله أخذه». ويشرح كاتب العبرانيين أنه بالإيمان نُقل لكي لا يرى الموت، لأنه قبل نقله شُهد له بأنه قد أرضى الله.","xs":1},{"i":"indus-valley","k":"w","e":"primeval","y":-2600,"t":"ازدهار حضارة وادي السند","l":"وادي نهر السند","x":"مدن هارابا وموهنجو دارو تزدهر بشوارع مخططة ومبانٍ من الطوب وصرف صحي متقن: واحدة من أقدم ثلاث حضارات مدنية مع بلاد الرافدين ومصر.","s":-2600},{"i":"great-pyramid","k":"w","e":"primeval","y":-2560,"t":"بناء الهرم الأكبر بالجيزة","l":"الجيزة، مصر","x":"هرم الملك خوفو يرتفع ١٤٦ مترًا فوق الصحراء: أعلى بناء صنعه الإنسان على الأرض نحو أربعة آلاف سنة، والوحيد الباقي من عجائب الدنيا السبع.","s":-2560},{"i":"stonehenge","k":"w","e":"primeval","y":-2500,"t":"إقامة ستونهنج","l":"سهل سالزبوري، بريطانيا","x":"بُناة العصر الحجري الحديث في بريطانيا يقيمون أحجار ستونهنج الضخمة موجهة نحو الانقلابين الشمسيين: إنجاز هندسي ضخم لا يزال الغرض منه غامضًا.","s":-2500},{"i":"t32","k":"b","e":"primeval","y":-2416,"j":-2467,"est":1,"t":"الرب يقرر أن يمحو الإنسان عن وجه الأرض","r":[["Gen",6,1,6,7]],"s":-2466.9899,"d":2,"pp":[["الله","god_1324"]],"x":"يكثر الناس على الأرض ويكثر شرهم، فيحزن الرب أنه عمل الإنسان ويقرر أن يمحوه عن وجه الأرض، ويحدد أيامه بمئة وعشرين سنة. لكن وسط هذا الحكم «وأما نوح فوجد نعمة في عيني الرب».","xs":1},{"i":"the-flood","k":"b","e":"primeval","y":-2348,"t":"الطوفان","j":-2399,"r":[["Gen",6,null,8,null]],"d":2,"l":"جبال أراراط","x":"الرب يحزن على شر الإنسان فيرسل الطوفان على الأرض، ويحفظ نوحًا البار وعائلته والحيوانات في الفلك. وبعد أن تنحسر المياه يستقر الفلك على جبال أراراط.","s":-2399,"pp":[["نوح","noah_2210"],["الله","god_1324"]],"kx":"حين بلغ شر الإنسان أن «كل تصور أفكار قلبه إنما هو شرير كل يوم» (التكوين ٦: ٥)، أجرى الله دينونة شاملة بالطوفان، ولم ينجُ إلا نوح وعائلته في الفلك. يُظهر الطوفان قداسة الله التي لا تحتمل الشر، ونعمته التي تحفظ بقية. ويربط بطرس الطوفان بالمعمودية (بطرس الأولى ٣: ٢٠–٢١)، وبالدينونة الأخيرة (بطرس الثانية ٣: ٥–٧)، ويرى المفسرون في الفلك صورة للخلاص في المسيح وحده. وعهد قوس السحاب وعد بألا يهلك الله الأرض بطوفان مرة أخرى."},{"i":"t37","k":"b","e":"primeval","y":-2348,"j":-2347,"est":1,"t":"موت متوشالح","r":[["Gen",5,27,5,27]],"s":-2346.9899,"d":2,"pp":[["متوشالح","methuselah_2042"]],"x":"يموت متوشالح بعد تسع مئة وتسع وستين سنة، أطول عمر مذكور في الكتاب. وبحسب حساب أعمار الآباء في التكوين ٥ جاءت سنة موته هي سنة الطوفان نفسها.","xs":1},{"i":"t38","k":"b","e":"primeval","y":-2348,"j":-2347,"est":1,"t":"بداية الطوفان","r":[["Gen",7,6,7,17]],"s":-2346.9899,"d":3,"pp":[["نوح","noah_2210"],["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"]],"x":"في السنة الست مئة من حياة نوح تنفجر ينابيع الغمر العظيم وتنفتح طاقات السماء، ويكون المطر على الأرض أربعين يومًا وأربعين ليلة. ويدخل نوح وعائلته والحيوانات الفلك «وأغلق الرب عليه».","xs":1},{"i":"t40","k":"b","e":"primeval","y":-2348,"j":-2347,"est":1,"t":"المياه تغطي الأرض","r":[["Gen",7,18,7,24]],"s":-2346.9899,"d":3,"pp":[["نوح","noah_2210"],["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"]],"x":"تتعاظم المياه جدًا على الأرض حتى تغطي الجبال الشامخة، ويموت كل ما على اليابسة، ويتبقى نوح والذين معه في الفلك فقط. وتظل المياه متعاظمة مئة وخمسين يومًا.","xs":1},{"i":"noahic-covenant","k":"b","e":"primeval","y":-2347,"t":"العهد مع نوح","j":-2346,"r":[["Gen",9,null,9,null]],"d":3,"x":"الله يبارك نوحًا وبنيه ويقطع عهدًا مع كل ذي جسد: لن يكون طوفان بعد ليخرب الأرض. وقوس السحاب علامة هذا العهد الأبدي.","s":-2346,"pp":[["نوح","noah_2210"]]},{"i":"t41","k":"b","e":"primeval","y":-2347,"j":-2346,"est":1,"t":"المياه تنحسر","r":[["Gen",8,1,8,14]],"s":-2345.9899,"d":3,"pp":[["نوح","noah_2210"],["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"]],"ll":["أراراط"],"x":"«ثم ذكر الله نوحًا»، فيُجيز ريحًا على الأرض فتهدأ المياه، ويستقر الفلك على جبال أراراط. ويرسل نوح الغراب ثم الحمامة، فترجع إليه في المرة الثانية وفي فمها ورقة زيتون، فيعلم أن المياه قد قلّت.","xs":1},{"i":"t42","k":"b","e":"primeval","y":-2347,"j":-2346,"est":1,"t":"الخروج من الفلك","r":[["Gen",8,15,8,19]],"s":-2345.9899,"d":3,"pp":[["نوح","noah_2210"],["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"]],"ll":["أراراط"],"x":"بعد أن تجف الأرض يقول الله لنوح أن يخرج هو وعائلته وكل الحيوانات من الفلك، لتتوالد وتكثر على الأرض. فيخرج الجميع إلى أرض جديدة بعد سنة كاملة تقريبًا في الفلك.","xs":1},{"i":"t43","k":"b","e":"primeval","y":-2347,"j":-2346,"est":1,"t":"نوح يبني مذبحًا والرب يقطع عهدًا","r":[["Gen",8,20,9,17]],"s":-2345.9899,"d":3,"pp":[["الله","god_1324"],["نوح","noah_2210"]],"x":"أول ما يعمله نوح بعد الخروج أن يبني مذبحًا للرب ويقدم محرقات، فيتنسم الرب رائحة الرضا. ويبارك الله نوحًا وبنيه، ويقطع عهدًا مع كل ذي جسد ألا يكون طوفان بعد، ويجعل قوس السحاب علامة لهذا العهد.","xs":1},{"i":"t44","k":"b","e":"primeval","y":-2346,"j":-2345,"est":1,"t":"سُكر نوح ولعنة كنعان","r":[["Gen",9,20,9,27]],"s":-2344.9899,"d":3,"pp":[["نوح","noah_2210"],["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"],["كنعان","canaan_914"]],"x":"يغرس نوح كرمًا ويشرب من الخمر فيسكر ويتعرّى في خبائه. يبصر حام عورة أبيه ويخبر أخويه، بينما يأخذ سام ويافث رداء ويستران أباهما دون أن ينظرا. وعندما يفيق نوح يلعن كنعان بن حام ويبارك سامًا ويافث.","xs":1},{"i":"sargon-akkad","k":"w","e":"primeval","y":-2334,"t":"سرجون الأكادي يؤسس أول إمبراطورية","l":"بلاد ما بين النهرين","x":"سرجون الأكبر يُخضع دويلات سومر ويوحّد بلاد الرافدين تحت حكم أكاد: أول إمبراطورية تضم شعوبًا متعددة، من الخليج العربي نحو البحر المتوسط.","s":-2334},{"i":"table-of-nations","k":"b","e":"primeval","y":-2300,"t":"الأمم من نسل بني نوح","j":-2303,"r":[["Gen",10,null,10,null]],"d":3,"x":"نسل سام وحام ويافث ينتشر ويصير شعوب العالم القديم: «جدول الأمم» الذي يرسم الشعوب المحيطة بقصة إسرائيل فيما بعد.","s":-2303,"pp":[["سام","shem_2613"],["حام","ham_1359"],["يافث","japheth_726"],["كوش","cush_962"],["عابر","eber_1030"],["يقطان","joktan_1686"]],"ll":["كالح","نينوى"]},{"i":"tower-of-babel","k":"b","e":"primeval","y":-2200,"t":"برج بابل","j":-2245,"r":[["Gen",11,1,11,9]],"d":4,"l":"أرض شنعار (بابل)","x":"البشر، ولهم لسان واحد، يبنون برجًا ليصنعوا لأنفسهم اسمًا. الرب يبلبل لسانهم ويبددهم على وجه كل الأرض، فتنشأ اللغات والأمم.","s":-2245,"ll":["بابل"],"kx":"بدل أن ينتشر البشر ليملأوا الأرض كما أُمروا (التكوين ٩: ١)، تجمعوا ليبنوا برجًا رأسه بالسماء، لا للعبادة بل «لنصنع لأنفسنا اسمًا» (التكوين ١١: ٤). فبلبل الله لسانهم وبددهم، ومن هنا جاء تنوع اللغات والشعوب. ويرى كثير من المفسرين أن يوم الخمسين هو عكس بابل: الروح القدس يجعل الإنجيل يُسمع بكل اللغات، ويجمع من كل الأمم شعبًا واحدًا، فالمسيح «نقض حائط السياج المتوسط» (أفسس ٢: ١٤)."},{"i":"t65","k":"b","e":"patriarchs","y":-2167,"j":-1995,"est":1,"t":"ميلاد أبرام","r":[["Gen",11,26,11,27]],"s":-1994.9899,"d":4,"pp":[["إبراهيم","abraham_58"],["تارح","terah_2841"]],"ll":["أور الكلدانيين"],"x":"يعيش تارح سبعين سنة ويلد أبرام وناحور وهاران في أور الكلدانيين. ومن هنا يبدأ تاريخ العائلة التي سيختارها الله ليكون منها شعب العهد.","xs":1},{"i":"ziggurat-of-ur","k":"w","e":"patriarchs","y":-2100,"t":"بناء زقورة أور العظيمة","l":"أور، بلاد ما بين النهرين","x":"الملك أور-نمو يبني الزقورة الكبيرة لإله القمر «نانا» في أور، المدينة التي يذكرها الكتاب موطنًا لإبراهيم (أور الكلدانيين). ولا يزال قلبها الضخم من الطوب اللبن قائمًا.","s":-2100},{"i":"t73","k":"b","e":"patriarchs","y":-2092,"j":-1920,"est":1,"t":"أبرام ينزل إلى مصر","r":[["Gen",12,10,12,20]],"s":-1919.9899,"d":17,"pp":[["إبراهيم","abraham_58"],["سارة","sarah_2473"],["فرعون","pharaoh_2328"]],"ll":["مصر"],"x":"يحدث جوع في أرض كنعان فينزل أبرام إلى مصر، ويطلب من ساراي أن تقول إنها أخته خوفًا على حياته. فتؤخذ إلى بيت فرعون، لكن الرب يضرب فرعون وبيته بضربات عظيمة، فيرد فرعون ساراي ويصرف أبرام بكل ما له.","xs":1},{"i":"call-of-abram","k":"b","e":"patriarchs","y":-2091,"t":"الله يدعو أبرام","j":-1919,"r":[["Gen",12,1,12,9]],"d":17,"l":"حاران ← كنعان","x":"الرب يدعو أبرام أن يترك أرضه وعشيرته إلى الأرض التي يريه، ويعده أن يجعله أمة عظيمة وأن تتبارك فيه جميع قبائل الأرض. يطيع أبرام وهو ابن خمس وسبعين سنة ويدخل كنعان.","s":-1919,"pp":[["إبراهيم","abraham_58"],["الله","god_1324"],["لوط","lot_1830"]],"ll":["حاران"],"kx":"يدعو الرب أبرام (ومعناه «أب رفيع») من أور الكلدانيين إلى كنعان، ثم يغيّر اسمه إلى إبراهيم «أب جمهور». وعهد الله معه هو أساس كل تاريخ الفداء بعده، وفيه ثلاثة وعود: الأرض، والنسل الكثير، والبركة لجميع الأمم في نسله. ثُبّت العهد بطقس الذبائح (التكوين ١٥) وبعلامة الختان. وقول الكتاب «فآمن بالرب فحسبه له برًّا» (التكوين ١٥: ٦) يقتبسه بولس أساسًا للتبرير بالإيمان (رومية ٤: ٣؛ غلاطية ٣: ٦)، ويقول إن «النسل» الموعود هو المسيح (غلاطية ٣: ١٦)."},{"i":"t75","k":"b","e":"patriarchs","y":-2091,"j":-1919,"est":1,"t":"أبرام ولوط يفترقان","r":[["Gen",13,1,13,18]],"s":-1918.9899,"d":17,"pp":[["إبراهيم","abraham_58"],["لوط","lot_1830"]],"ll":["سدوم","دائرة الأردن","كنعان","حبرون"],"x":"تكثر مواشي أبرام ولوط حتى لا تحتملهما الأرض، ويقع خصام بين رعاتهما. فيعطي أبرام لوطًا حق الاختيار، فيختار دائرة الأردن المسقية ويسكن قرب سدوم. ثم يجدد الرب وعده لأبرام بالأرض والنسل، فيسكن عند بلوطات ممرا في حبرون ويبني مذبحًا.","xs":1},{"i":"abrahamic-covenant","k":"b","e":"patriarchs","y":-2081,"t":"العهد مع إبراهيم","j":-1910,"r":[["Gen",15,null,15,null],["Gen",17,null,17,null]],"d":18,"l":"كنعان","x":"الله يقطع عهدًا مع أبرام: نسل كنجوم السماء وأرض كنعان ميراثًا لهم. يؤمن أبرام بالرب فيُحسب له برًّا، ويتغير اسمه إلى إبراهيم «أب لجمهور من الأمم».","s":-1910,"pp":[["إبراهيم","abraham_58"],["الله","god_1324"]]},{"i":"t76","k":"b","e":"patriarchs","y":-2080,"j":-1909,"est":1,"t":"ميلاد إسماعيل","r":[["Gen",16,11,16,16]],"s":-1908.9898,"d":18,"pp":[["إسماعيل","ishmael_630"],["إبراهيم","abraham_58"],["هاجر","hagar_1348"]],"x":"تحمل هاجر من أبرام، وحين تهرب من وجه ساراي يجدها ملاك الرب في البرية ويسمّي ابنها إسماعيل، أي «الله يسمع»، لأن الرب سمع لمذلتها. ويولد إسماعيل وأبرام ابن ست وثمانين سنة.","xs":1},{"i":"sodom-gomorrah","k":"b","e":"patriarchs","y":-2067,"t":"خراب سدوم وعمورة","j":-1896,"r":[["Gen",18,null,19,null]],"d":18,"l":"مدن الدائرة","x":"بعد أن يتشفع إبراهيم من أجل الأبرار، يمطر الرب كبريتًا ونارًا على مدن الدائرة الشريرة وينجّي لوطًا وابنتيه. امرأة لوط تنظر إلى الوراء فتصير عمود ملح.","s":-1896,"pp":[["الله","god_1324"],["إبراهيم","abraham_58"],["لوط","lot_1830"],["سارة","sarah_2473"],["ابنة لوط الصغرى","daughter_of_lot_younger_984"],["ابنة لوط الكبرى","daughter_of_lot_older_985"]],"ll":["سدوم","عمورة","صوغر"]},{"i":"birth-of-isaac","k":"b","e":"patriarchs","y":-2066,"t":"ميلاد إسحاق","j":-1885,"r":[["Gen",21,1,21,7]],"d":19,"l":"كنعان","x":"الله يتمم وعده: سارة تلد لإبراهيم ابنًا في شيخوختهما، إسحاق ومعناه «يضحك». وبهذا الطفل المعجزي يستمر خط العهد.","s":-1885,"pp":[["سارة","sarah_2473"],["إبراهيم","abraham_58"],["الله","god_1324"],["إسحاق","isaac_616"]],"kx":"يتمم الله وعده ويعطي إبراهيم وسارة ابنًا في شيخوختهما، هي ابنة تسعين وهو ابن مئة، ليظهر أن مقاصد الله تقوم على قدرته لا على قدرة الإنسان. واسم إسحاق معناه «يضحك». وفي قصة تقديمه على جبل المريا (التكوين ٢٢) يدبّر الله كبشًا عوضًا عنه، ويسمي إبراهيم المكان «يهوه يرأه» أي «الرب يدبّر». ويرى المسيحيون في ذلك صورة واضحة للآب الذي «لم يشفق على ابنه» بل قدّمه عوضًا عن الخطاة (رومية ٨: ٣٢)."},{"i":"binding-of-isaac","k":"b","e":"patriarchs","y":-2050,"t":"تقديم إسحاق","j":-1871,"r":[["Gen",22,null,22,null]],"d":20,"l":"جبل المريا","x":"الله يمتحن إبراهيم ويأمره أن يقدم إسحاق محرقة. وفي آخر لحظة يمنعه ملاك الرب، ويُدبَّر كبش عوضًا عن إسحاق: «في جبل الرب يُرى».","s":-1871,"pp":[["إبراهيم","abraham_58"],["الله","god_1324"],["إسحاق","isaac_616"],["ملكة","milcah_2082"],["ناحور","nahor_2143"],["بتوئيل","bethuel_487"]]},{"i":"middle-kingdom-egypt","k":"w","e":"patriarchs","y":-2040,"t":"بداية الدولة الوسطى في مصر","l":"مصر","x":"منتوحتب الثاني يعيد توحيد مصر بعد قرن من التفكك، فتبدأ الدولة الوسطى: عصر ذهبي للأدب والصناعة والتجارة، وهو خلفية قصص الآباء.","s":-2040},{"i":"t83","k":"b","e":"patriarchs","y":-2034,"j":-1855,"est":1,"t":"إسحاق يتزوج رفقة","r":[["Gen",25,20,25,20]],"s":-1854.9897,"d":22,"pp":[["إسحاق","isaac_616"],["رفقة","rebekah_2401"]],"x":"يتزوج إسحاق برفقة ابنة بتوئيل الأرامي من فدان أرام وهو ابن أربعين سنة. كانت رفقة قد جاءت مع عبد إبراهيم بعد أن أرشده الرب إليها عند البئر.","xs":1},{"i":"jacob-esau-born","k":"b","e":"patriarchs","y":-2006,"t":"ميلاد يعقوب وعيسو","j":-1895,"r":[["Gen",25,19,25,26]],"d":22,"x":"رفقة تحمل توأمين يتزاحمان في بطنها، والرب يقول: «كبير يُستعبد لصغير». العهد سيمضي في يعقوب لا في عيسو.","s":-1895,"pp":[["إسحاق","isaac_616"],["الله","god_1324"],["رفقة","rebekah_2401"],["عيسو","esau_1216"]],"kx":"يقول الرب لرفقة قبل ولادة التوأمين: «كبير يُستعبد لصغير» (التكوين ٢٥: ٢٣)، ويستشهد بولس بهذا ليبيّن أن اختيار الله قائم على رحمته لا على أعمال الإنسان (رومية ٩: ١٠–١٣). واسم يعقوب مرتبط بكلمة «العقب» أي الممسك بالعقب أو المتعقِّب، وكان فعلًا كثير الحيلة، ومع ذلك نال البركة: نعمة لغير المستحق. وبعد مصارعته في فنيئيل صار اسمه إسرائيل، وهو الاسم الذي صار لشعب الله كله، وأبناؤه الاثنا عشر صاروا رؤساء الأسباط."},{"i":"minoan-civilization","k":"w","e":"patriarchs","y":-2000,"t":"حضارة القصور المينوية في كريت","l":"كريت","x":"أول حضارة متقدمة في أوروبا تبني قصورًا ضخمة في كنوسوس وفايستوس، بجداريات زاهية وكتابة وشبكة تجارة بحرية في شرق المتوسط.","s":-2000},{"i":"t87","k":"b","e":"patriarchs","y":-2000,"j":-1821,"est":1,"t":"بداية مملكة نمرود","r":[["Gen",10,8,10,12]],"s":-1820.9899,"d":3,"pp":[["نمرود","nimrod_2206"]],"ll":["شنعار","أشور","أكد","بابل","كالح","كلنة","أرك","نينوى","رحوبوت عير","رسن"],"x":"نمرود بن كوش «ابتدأ يكون جبارًا في الأرض» وكان «جبار صيد أمام الرب». وكان ابتداء مملكته بابل وأرك وأكد وكلنة في أرض شنعار، ومن هناك خرج إلى أشور وبنى نينوى ورحوبوت عير وكالح ورسن.","xs":1},{"i":"t88","k":"b","e":"patriarchs","y":-1999,"j":-1820,"est":1,"t":"موت إبراهيم","r":[["Gen",25,7,25,7]],"s":-1819.9897,"d":22,"pp":[["إبراهيم","abraham_58"]],"ll":["المكفيلة"],"x":"يموت إبراهيم «بشيبة صالحة، شيخًا وشبعان أيامًا» بعد مئة وخمس وسبعين سنة. ويدفنه ابناه إسحاق وإسماعيل معًا في مغارة المكفيلة التي اشتراها لدفن سارة.","xs":1},{"i":"jacobs-ladder","k":"b","e":"patriarchs","y":-1930,"t":"سلم يعقوب في بيت إيل","j":-1759,"r":[["Gen",28,10,28,22]],"d":23,"l":"بيت إيل","x":"يعقوب هارب من عيسو فيرى في حلم سلمًا منصوبة على الأرض ورأسها يمس السماء، وملائكة الله صاعدة ونازلة عليها. الله يجدد له وعد إبراهيم، فيدعو اسم المكان بيت إيل «بيت الله».","s":-1759,"pp":[["الله","god_1324"],["يعقوب","israel_682"]]},{"i":"t102","k":"b","e":"patriarchs","y":-1912,"j":-1744,"est":1,"t":"ميلاد يوسف","r":[["Gen",30,23,30,24]],"s":-1743.9897,"d":24,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["راحيل","rachel_2386"]],"ll":["مصر"],"x":"بعد سنين من العقم يذكر الله راحيل ويسمع لها ويفتح رحمها، فتلد ابنًا وتقول: «قد نزع الله عاري». وتدعو اسمه يوسف، قائلة: «يزيدني الرب ابنًا آخر».","xs":1},{"i":"jacob-wrestles","k":"b","e":"patriarchs","y":-1906,"t":"يعقوب يصارع الله","j":-1738,"r":[["Gen",32,22,32,32]],"d":25,"l":"فنيئيل، عند مخاضة يبوق","x":"في الليلة السابقة لملاقاة عيسو يصارع يعقوب إنسانًا حتى طلوع الفجر، ولا يطلقه حتى يباركه. يتغير اسمه إلى إسرائيل، ويمضي وهو يخمع على فخذه إنسانًا جديدًا.","s":-1738,"pp":[["يعقوب","israel_682"],["الله","god_1324"]]},{"i":"t104","k":"b","e":"patriarchs","y":-1906,"j":-1738,"est":1,"t":"موت راحيل عند ولادة بنيامين","r":[["Gen",35,16,35,27]],"s":-1737.9896,"d":26,"pp":[["يعقوب","israel_682"],["راحيل","rachel_2386"],["بنيامين","benjamin_463"]],"ll":["أفراتة"],"x":"في الطريق قرب أفراتة، التي هي بيت لحم، تتعسر ولادة راحيل وتموت وهي تلد. تسمّي ابنها «بن أوني» أي ابن حزني، ويسميه أبوه «بنيامين». ويقيم يعقوب عمودًا على قبرها، ثم يأتي إلى أبيه إسحاق في ممرا.","xs":1},{"i":"gilgamesh-epic","k":"w","e":"patriarchs","y":-1900,"t":"تدوين ملحمة جلجامش","l":"بابل","x":"أقدم عمل أدبي كبير في العالم يُدوَّن: رحلة الملك السومري جلجامش بحثًا عن الخلود، وفيها قصة طوفان تتشابه مع التكوين في أمور وتختلف عنه في أمور.","s":-1900},{"i":"joseph-sold","k":"b","e":"patriarchs","y":-1898,"t":"بيع يوسف عبدًا","j":-1727,"r":[["Gen",37,null,37,null]],"d":27,"l":"دوثان ← مصر","x":"إخوة يوسف يحسدونه لمحبة أبيه له ولأحلامه، فيبيعونه وهو ابن سبع عشرة سنة لتجار مديانيين نازلين إلى مصر. ما قصدوه شرًّا قصد الله به خيرًا ليحيي شعبًا كثيرًا.","s":-1727,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["رأوبين","reuben_2429"],["زبولون","zebulun_3002"],["شمعون","simeon_2741"],["نفتالي","naphtali_2149"],["لاوي","levi_1820"],["يهوذا","judah_1751"],["جاد","gad_1262"],["دان","dan_973"],["يساكر","issachar_645"],["أشير","asher_337"]],"ll":["مصر"]},{"i":"t109","k":"b","e":"patriarchs","y":-1888,"j":-1717,"est":1,"t":"يوسف في السجن","r":[["Gen",39,20,41,14]],"s":-1716.9896,"d":28,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["رأوبين","reuben_2429"],["فرعون","pharaoh_2329"]],"ll":["مصر"],"x":"تتهم امرأة فوطيفار يوسف زورًا فيُلقى في السجن، لكن الرب كان معه فجعل رئيس السجن يأتمنه على كل شيء. يفسر حلمي ساقي فرعون وخبازه فيتحقق كلامه، لكن الساقي ينساه سنتين كاملتين حتى يحلم فرعون.","xs":1},{"i":"t110","k":"b","e":"patriarchs","y":-1886,"j":-1715,"est":1,"t":"موت إسحاق","r":[["Gen",35,28,35,29]],"s":-1714.9896,"d":26,"pp":[["إسحاق","isaac_616"]],"ll":["ممرا"],"x":"يموت إسحاق بعد مئة وثمانين سنة، «وانضم إلى قومه شيخًا وشبعان أيامًا». ويدفنه ابناه عيسو ويعقوب معًا، بعد أن تصالحا.","xs":1},{"i":"joseph-rules-egypt","k":"b","e":"patriarchs","y":-1885,"t":"يوسف يرتفع في مصر","j":-1714,"r":[["Gen",41,null,41,null]],"d":29,"l":"مصر","x":"بعد أن يفسر حلمي فرعون عن السبع السنين السمان والسبع العجاف، ينتقل يوسف من السجن إلى أن يصير على كل أرض مصر وهو ابن ثلاثين سنة، ويخزن القمح للمجاعة الآتية.","s":-1714,"pp":[["فرعون","pharaoh_2329"],["يوسف","joseph_1710"],["الله","god_1324"],["أسنات","asenath_335"],["فوطي فارع","poti-pherah_2369"]],"ll":["مصر","النيل","أون"],"kx":"حياة يوسف مثال واضح لعناية الله التي تعمل حتى من خلال خطايا البشر. بيع عبدًا ثم ارتفع إلى أن صار الثاني بعد فرعون، فرأى فيه المفسرون صورة لاتضاع المسيح ثم تمجيده. وكلمته لإخوته تلخص الفكرة: «أنتم قصدتم لي شرًّا، أما الله فقصد به خيرًا، لكي يفعل كما اليوم، ليحيي شعبًا كثيرًا» (التكوين ٥٠: ٢٠). وبسببه حُفظ بيت يعقوب من المجاعة ونزل إلى مصر حيث صار أمة، فتهيأ المسرح لقصة الخروج."},{"i":"t112","k":"b","e":"patriarchs","y":-1885,"j":-1714,"est":1,"t":"سبع سنين الشبع","r":[["Gen",41,47,41,53]],"s":-1713.9896,"d":29,"pp":[["يوسف","joseph_1710"],["فرعون","pharaoh_2329"]],"ll":["مصر"],"x":"في سبع سني الشبع تُخرج الأرض بوفرة، ويجمع يوسف القمح في المدن «كرمل البحر كثيرًا جدًا» حتى توقف عن العدّ. وفي هذه الفترة يولد له ابنان من أسنات: منسى وأفرايم.","xs":1},{"i":"t113","k":"b","e":"patriarchs","y":-1878,"j":-1707,"est":1,"t":"سبع سنين الجوع","r":[["Gen",41,54,43,34]],"s":-1706.9896,"d":29,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["رأوبين","reuben_2429"],["زبولون","zebulun_3002"],["شمعون","simeon_2741"],["نفتالي","naphtali_2149"],["لاوي","levi_1820"],["يهوذا","judah_1751"],["جاد","gad_1262"],["دان","dan_973"],["يساكر","issachar_645"],["أشير","asher_337"]],"x":"تبدأ سبع سني الجوع كما قال يوسف، ويكون الجوع على كل الأرض. فيفتح يوسف المخازن ويبيع للمصريين، وتأتي كل الأرض إلى مصر لتشتري قمحًا، ومنها بيت يعقوب في كنعان.","xs":1},{"i":"t114","k":"b","e":"patriarchs","y":-1877,"j":-1706,"est":1,"t":"إخوة يوسف ينزلون إلى مصر","r":[["Gen",42,1,42,38]],"s":-1705.9896,"d":29,"x":"يرسل يعقوب عشرة من بنيه إلى مصر ليشتروا قمحًا، ويبقي بنيامين عنده. يعرفهم يوسف وهم لا يعرفونه، فيتكلم معهم بجفاء ويتهمهم بأنهم جواسيس، ويحبس شمعون حتى يأتوا بأخيهم الأصغر. ويرجعون فيجدون فضتهم في أفواه عدالهم فترتعد قلوبهم.","xs":1},{"i":"israel-to-egypt","k":"b","e":"patriarchs","y":-1876,"t":"بيت يعقوب يسكن في مصر","j":-1705,"r":[["Gen",46,null,47,null]],"d":31,"l":"أرض جاسان، مصر","x":"بسبب المجاعة ينزل يعقوب وكل بيته، سبعون نفسًا، إلى مصر بدعوة يوسف، ويسكنون أرض جاسان الخصبة حيث ينمو إسرائيل ويصير أمة.","s":-1705,"pp":[["يعقوب","israel_682"],["يوسف","joseph_1710"],["فرعون","pharaoh_2329"],["كنعان","canaan_914"],["الله","god_1324"]],"ll":["مصر","كنعان","جاسان","بئر سبع"]},{"i":"t115","k":"b","e":"patriarchs","y":-1876,"j":-1705,"est":1,"t":"إخوة يوسف يرجعون إلى مصر ويوسف يعرّفهم بنفسه","r":[["Gen",43,1,45,28]],"s":-1704.9895,"d":30,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["رأوبين","reuben_2429"],["زبولون","zebulun_3002"],["شمعون","simeon_2741"],["نفتالي","naphtali_2149"],["لاوي","levi_1820"],["يهوذا","judah_1751"],["جاد","gad_1262"],["دان","dan_973"],["يساكر","issachar_645"],["أشير","asher_337"]],"ll":["مصر"],"x":"يشتد الجوع فيرجع الإخوة إلى مصر ومعهم بنيامين. يدبّر يوسف أن يوجد طاسه في عدل بنيامين، فيتقدم يهوذا ويقدم نفسه عبدًا عوضًا عن أخيه. فلا يستطيع يوسف أن يضبط نفسه ويقول: «أنا يوسف»، ويطمئنهم بأن الله أرسله قدامهم لاستبقاء حياة، ويدعو أباه ليسكن في مصر.","xs":1},{"i":"t116","k":"b","e":"patriarchs","y":-1859,"j":-1688,"est":1,"t":"موت يعقوب","r":[["Gen",47,28,49,31]],"s":-1687.9895,"d":31,"pp":[["يعقوب","israel_682"]],"ll":["مصر"],"x":"يعيش يعقوب في مصر سبع عشرة سنة، ويبارك ابني يوسف ثم يجمع بنيه ويخبرهم بما يصيبهم في آخر الأيام، ويقول عن يهوذا: «لا يزول قضيب من يهوذا... حتى يأتي شيلون». ثم يوصي أن يُدفن مع آبائه في مغارة المكفيلة، ويموت ابن مئة وسبع وأربعين سنة.","xs":1},{"i":"death-of-joseph","k":"b","e":"patriarchs","y":-1805,"t":"موت يوسف","j":-1634,"r":[["Gen",50,22,50,26]],"d":32,"l":"مصر","x":"يموت يوسف ابن مئة وعشر سنين، ويؤكد لإخوته أن الله سيفتقدهم ويصعدهم من مصر، ويستحلفهم أن يصعدوا عظامه معهم: تابوت في مصر ينتظر تحقيق الوعد.","s":-1634,"pp":[["يوسف","joseph_1710"],["يعقوب","israel_682"],["الله","god_1324"],["أفرايم","ephraim_1206"],["ماكير","machir_1877"],["منسى","manasseh_1928"]],"ll":["مصر"]},{"i":"code-of-hammurabi","k":"w","e":"egypt-exodus","y":-1754,"t":"شريعة حمورابي","l":"بابل","x":"حمورابي ملك بابل ينقش ٢٨٢ قانونًا على مسلة من البازلت: من أقدم مجموعات القوانين وأكملها، وكثيرًا ما تُقارن بشريعة موسى لمبدأ «العين بالعين» فيها.","s":-1754},{"i":"israel-enslaved","k":"b","e":"egypt-exodus","y":-1700,"t":"استعباد إسرائيل في مصر","j":-1634,"r":[["Exo",1,null,1,null]],"d":32,"l":"مصر","x":"يقوم ملك جديد على مصر لم يكن يعرف يوسف. يخاف من كثرة بني إسرائيل فيستعبدهم بعنف ويبنون له مدينتي المخازن فيثوم ورعمسيس، ولكن بحسبما أذلوهم كذلك نموا وامتدوا.","s":-1634,"pp":[["يعقوب","israel_682"],["يوسف","joseph_1710"],["فرعون","pharaoh_2330"],["الله","god_1324"]],"ll":["مصر"],"kx":"بعد موت يوسف قام ملك جديد «لم يكن يعرف يوسف» (الخروج ١: ٨)، فخاف من كثرة بني إسرائيل واستعبدهم بعنف، ثم أمر بقتل أطفالهم الذكور. ومع ذلك «بحسبما أذلوهم هكذا نموا وامتدوا» (الخروج ١: ١٢). صارت العبودية في مصر في الكتاب كله الصورة الأساسية للخلاص: إنسان مستعبد لا يقدر أن يحرر نفسه، يحتاج إلى تدخل الله، ويُفدى بالدم. ولذلك يتكرر في الأسفار القول: «أنا الرب إلهك الذي أخرجك من أرض مصر»."},{"i":"hyksos-egypt","k":"w","e":"egypt-exodus","y":-1650,"t":"الهكسوس يحكمون شمال مصر","l":"دلتا النيل، مصر","x":"أجانب ساميون يُعرفون بالهكسوس يستولون على الحكم في الدلتا ويحكمون نحو قرن، ويُدخلون المركبة التي تجرها الخيل، ثم تطردهم أسرة مصرية قوية.","s":-1650},{"i":"thera-eruption","k":"w","e":"egypt-exodus","y":-1600,"t":"ثوران بركان ثيرا (سانتوريني)","l":"بحر إيجة","x":"من أعظم الانفجارات البركانية في تاريخ البشر يمزق جزيرة ثيرا، ويغمر كريت المينوية بالرماد وأمواج التسونامي، ويغيّر عالم بحر إيجة في العصر البرونزي.","s":-1600},{"i":"shang-dynasty","k":"w","e":"egypt-exodus","y":-1600,"t":"قيام أسرة شانغ في الصين","l":"وادي النهر الأصفر، الصين","x":"أول أسرة صينية ثابتة تاريخيًا تظهر على النهر الأصفر، وتصنع أواني طقسية بديعة من البرونز، وتدوّن أقدم كتابة صينية على عظام العرافة.","s":-1600},{"i":"t119","k":"b","e":"egypt-exodus","y":-1534,"j":-1579,"est":1,"t":"موت أيوب","r":[["Job",42,16,42,17]],"s":-1578.8196,"d":16,"pp":[["أيوب","job_1639"]],"x":"بعد محنته يعيش أيوب مئة وأربعين سنة، ويرى بنيه وبني بنيه إلى أربعة أجيال. ثم يموت «شيخًا وشبعان الأيام»، وقد ردّ الرب سبيه وأعطاه ضعف ما كان له.","xs":1},{"i":"birth-of-moses","k":"b","e":"egypt-exodus","y":-1526,"t":"ميلاد موسى","j":-1571,"r":[["Exo",2,1,2,10]],"d":33,"l":"مصر","x":"فرعون يأمر بطرح كل ابن عبراني في النهر، فتخبئ أم موسى ابنها في سفط على حافة النيل. ابنة فرعون نفسها تنتشله وتربيه في القصر: مخلّص إسرائيل يتهذب بكل حكمة المصريين.","s":-1571,"pp":[["ابنة فرعون","daughter_of_pharaoh_988"],["فرعون","pharaoh_2331"]]},{"i":"moses-flees","k":"b","e":"egypt-exodus","y":-1486,"t":"موسى يهرب إلى مديان","j":-1530,"r":[["Exo",2,11,2,25]],"d":33,"l":"مديان","x":"بعد أن يقتل موسى مصريًا كان يضرب عبرانيًا، يهرب إلى أرض مديان ويقضي هناك أربعين سنة راعيًا: أمير مصر يتعلم الاتضاع في البرية.","s":-1530,"pp":[["موسى","moses_2108"],["يعقوب","israel_682"],["الله","god_1324"],["مديان","midian_2075"]],"ll":["مديان"]},{"i":"hatshepsut","k":"w","e":"egypt-exodus","y":-1479,"t":"حتشبسوت تحكم مصر فرعونًا","l":"مصر","x":"من أنجح الحاكمات في العالم القديم تجلس على عرش مصر، وتطلق مشاريع بناء كبيرة والرحلة التجارية الشهيرة إلى بلاد بونت.","s":-1479},{"i":"mycenaean-greece","k":"w","e":"egypt-exodus","y":-1450,"t":"ذروة حضارة اليونان الميسينية","l":"اليونان","x":"ممالك ميسيناي وتيرنس وبيلوس المحاربة تسيطر على بحر إيجة بقلاع ضخمة وكتابة «الخطي ب»: يونان الأساطير التي خلّدتها ملاحم هوميروس.","s":-1450},{"i":"burning-bush","k":"b","e":"egypt-exodus","y":-1447,"t":"العليقة المشتعلة","j":-1490,"r":[["Exo",3,null,4,null]],"d":33,"l":"جبل حوريب (سيناء)","x":"الله يكلم موسى من عليقة تتوقد بالنار ولا تحترق، ويعلن اسمه «أهيه الذي أهيه»، ويرسل الراعي المتردد ليخرج إسرائيل من مصر.","s":-1490,"pp":[["الله","god_1324"],["موسى","moses_2108"],["يعقوب","israel_682"],["هارون","aaron_1"],["إبراهيم","abraham_58"],["إسحاق","isaac_616"]],"ll":["مصر","مديان"],"kx":"يقيم الله موسى (واسمه مرتبط بمعنى «انتشلته من الماء») مخلّصًا لشعبه: وُلد تحت أمر الموت، وحُفظ في سفط من البردي، وتربى في قصر فرعون، لكنه انحاز لشعبه المظلوم. وبعد أربعين سنة في مديان يظهر له الله في العليقة ويعلن اسمه «أهيه الذي أهيه» (الخروج ٣: ١٤)، ويرسله ليطلب إطلاق الشعب. وتردد موسى وصبر الله وإعطاؤه هارون متكلمًا عنه، كل ذلك يُظهر أن الله يستخدم أدوات ضعيفة. وموسى هو النبي الذي قال عنه: «يقيم لك الرب إلهك نبيًا مثلي» (التثنية ١٨: ١٥)، وطبّقه العهد الجديد على المسيح."},{"i":"ten-plagues","k":"b","e":"egypt-exodus","y":-1446,"t":"الضربات العشر وأول فصح","j":-1490,"r":[["Exo",7,null,12,null]],"d":34,"l":"مصر","x":"الله يضرب مصر بعشر ضربات، كل منها دينونة على آلهة مصر. وفي الليلة الأخيرة يعبر الرب عن كل بيت عليه دم الخروف: الفصح الذي يحفظه إسرائيل فريضة أبدية.","s":-1490,"pp":[["موسى","moses_2108"],["هارون","aaron_1"]],"ll":["مصر"],"kx":"بعشر ضربات متصاعدة يُظهر الرب أنه فوق آلهة مصر كلها، كما قال: «أصنع أحكامًا بكل آلهة المصريين» (الخروج ١٢: ١٢). وتقسية قلب فرعون، التي يُقال مرة إن فرعون قسّاها ومرة إن الرب قسّاها، تجمع بين تمرد الإنسان وسلطان الله في الدينونة. ثم تأتي الضربة العاشرة ومعها الفصح: كل بيت يرش دم خروف صحيح على قائمتي الباب وعتبته، فيعبر الرب عنه. هنا تظهر فكرة البديل بأوضح صورة: الخروف يموت عوضًا عن البكر. ويقول بولس: «فصحنا أيضًا المسيح قد ذُبح لأجلنا» (كورنثوس الأولى ٥: ٧)."},{"i":"the-exodus","k":"b","e":"egypt-exodus","y":-1446,"t":"الخروج وعبور البحر الأحمر","j":-1490,"r":[["Exo",12,null,14,null]],"d":36,"l":"مصر ← البحر الأحمر","x":"إسرائيل يخرج من مصر بعد ٤٣٠ سنة. وحين تحاصره مركبات فرعون عند البحر، يشق الرب المياه فيعبر الشعب على اليابسة، ويغرق جيش مصر وراءهم.","s":-1490,"pp":[["الله","god_1324"],["يعقوب","israel_682"],["موسى","moses_2108"],["فرعون","pharaoh_2331"],["هارون","aaron_1"]],"ll":["مصر","سكوت","بعل صفون","فم الحيروث"],"kx":"يطارد فرعون الشعب حتى يحاصره عند بحر سوف: البحر أمامهم والجيش وراءهم. فيشق الله المياه ويعبر إسرائيل على اليابسة، ثم ترجع المياه على جيش فرعون. بهذا تكتمل دينونة مصر وخلاص إسرائيل، ويظهر أن الله يصنع طريقًا حيث لا طريق. ويرى بولس في العبور صورة للمعمودية: «جميعهم اعتمدوا لموسى في السحابة وفي البحر» (كورنثوس الأولى ١٠: ١–٢). كان العبور قطعًا نهائيًا مع مصر، وبداية الرحلة إلى سيناء."},{"i":"ten-commandments","k":"b","e":"egypt-exodus","y":-1446,"t":"إعطاء الشريعة في سيناء","j":-1490,"r":[["Exo",19,null,20,null]],"d":38,"l":"جبل سيناء","x":"في الشهر الثالث بعد الخروج ينزل إسرائيل أمام جبل سيناء. وبين رعود وبروق ودخان، يتكلم الله بالوصايا العشر ويقطع عهدًا مع إسرائيل ليكون له خاصة ومملكة كهنة.","s":-1490,"pp":[["موسى","moses_2108"],["الله","god_1324"]],"ll":["جبل سيناء"],"kx":"بعد ثلاثة أشهر من الخروج يصل إسرائيل إلى سيناء، وهناك يقطع الله معه العهد. والشريعة (التوراة) بوصاياها الأخلاقية والمدنية والطقسية لم تُعطَ لكي يخلص الإنسان بها، بل لتعلن قداسة الله وتكشف الخطية وتنظم حياة شعب العهد. وظهور الله بالرعود والبروق وصوت البوق والنار والزلزلة ملأ الشعب خوفًا، وصعد موسى وسيطًا وأخذ لوحي الحجر المكتوبين بإصبع الله. ويقول بولس إن الناموس كان «مؤدبنا إلى المسيح» (غلاطية ٣: ٢٤)."},{"i":"golden-calf","k":"b","e":"egypt-exodus","y":-1446,"t":"العجل الذهبي","j":-1490,"r":[["Exo",32,null,32,null]],"d":43,"l":"جبل سيناء","x":"بينما موسى على الجبل، يصنع الشعب عجلًا من ذهب ويسجدون له. موسى يكسر اللوحين ويتشفع في الشعب، والرب الرحيم الرؤوف يجدد العهد.","s":-1490,"pp":[["موسى","moses_2108"],["الله","god_1324"],["هارون","aaron_1"],["يعقوب","israel_682"],["لاوي","levi_1820"]],"ll":["مصر"],"kx":"بينما موسى على الجبل يستلم الشريعة، يطلب الشعب من هارون أن يصنع لهم إلهًا، فيصنع عجلًا من ذهب ويسجدون له، كاسرين الوصية الثانية بعد أيام من قولهم «كل ما تكلم به الرب نفعل». وتشفع موسى منع هلاك الشعب، وفيه صورة لشفاعة المسيح. وبنو لاوي الذين وقفوا مع الرب صاروا سبط الخدمة. ورحمة الله في تجديد العهد بعد هذا التمرد هي النعمة التي حملت الشعب طوال الرحلة، والحادثة تبقى تحذيرًا دائمًا من عبادة الأوثان (كورنثوس الأولى ١٠: ٧)."},{"i":"wilderness-wandering","k":"b","e":"egypt-exodus","y":-1446,"t":"أربعون سنة في البرية","ye":-1406,"j":-1489,"r":[["Num",1,null,1,null],["Deu",1,null,1,null]],"d":57,"l":"برية سيناء والنقب","x":"أربعين سنة يتيه إسرائيل في البرية، يأكل المن ويشرب من الصخرة، وثيابه لا تبلى، والرب يحمله ويؤدبه كما يؤدب الإنسان ابنه، حتى يقف جيل جديد في عربات موآب.","s":-1489,"pp":[["موسى","moses_2108"],["يعقوب","israel_682"],["الله","god_1324"],["هارون","aaron_1"],["رأوبين","reuben_2429"],["شمعون","simeon_2741"]],"ll":["سيناء"],"kx":"رفض الشعب دخول كنعان في قادش برنيع رغم وعد الله، فتاهوا أربعين سنة حتى مات ذلك الجيل. وفي هذه الفترة تظهر عاقبة عدم الإيمان (عبرانيين ٣–٤)، وتأديب الله الصبور، وأمانته رغم التذمر المتكرر. وفيها الماء من الصخرة («والصخرة كانت المسيح»، كورنثوس الأولى ١٠: ٤)، والمن النازل من السماء، والحية النحاسية (يوحنا ٣: ١٤)، وعمود السحاب والنار. ويقول بولس إن هذه الأمور «حدثت مثالًا لنا وكُتبت لإنذارنا» (كورنثوس الأولى ١٠: ١١)."},{"i":"tabernacle","k":"b","e":"egypt-exodus","y":-1445,"t":"اكتمال خيمة الاجتماع","j":-1490,"r":[["Exo",40,null,40,null]],"d":46,"l":"برية سيناء","x":"إسرائيل يكمل خيمة الاجتماع كما أمر الرب تمامًا، فيملأ بهاء الرب المسكن: الله ساكن في وسط شعبه، يقودهم بالسحابة نهارًا والنار ليلًا.","s":-1490,"pp":[["موسى","moses_2108"],["الله","god_1324"],["هارون","aaron_1"],["يعقوب","israel_682"]],"kx":"يأمر الله ببناء خيمة الاجتماع (بالعبرية «مِشكان» أي المسكن)، مقدسًا متنقلًا يسكن فيه وسط شعبه. وكل تفصيل فيه، من التابوت وغطائه إلى المذبح والمرحضة والمنارة ومائدة خبز الوجوه والحجاب، يقرأه سفر العبرانيين ظلًّا لعمل المسيح: فقدس الأقداس الذي لا يدخله إلا رئيس الكهنة مرة في السنة بدم، يقابله دخول المسيح «إلى السماء عينها» (عبرانيين ٩: ٢٤). ومجد الرب الذي ملأ المسكن يقابله قول يوحنا: «والكلمة صار جسدًا وحلّ بيننا» (يوحنا ١: ١٤)، والكلمة اليونانية تعني «نصب خيمته»."},{"i":"twelve-spies","k":"b","e":"egypt-exodus","y":-1444,"t":"الجواسيس الاثنا عشر والتمرد في قادش","j":-1489,"r":[["Num",13,null,14,null]],"d":62,"l":"قادش برنيع","x":"اثنا عشر رجلًا يتجسسون أرض كنعان؛ عشرة يشيعون الخوف بينما يدعو يشوع وكالب إلى الإيمان. الشعب يرفض دخول الأرض، فيُحكم على ذلك الجيل أن يموت في البرية خلال أربعين سنة.","s":-1489,"pp":[["الله","god_1324"],["موسى","moses_2108"],["يعقوب","israel_682"],["كالب","caleb_537"],["يشوع","joshua_1727"],["نون","nun_2214"]],"ll":["مصر","النقب","كنعان","فاران"]},{"i":"bronze-serpent","k":"b","e":"egypt-exodus","y":-1407,"t":"الحية النحاسية","j":-1452,"r":[["Num",21,4,21,9]],"d":66,"l":"برية أدوم","x":"حين تلدغ الحيات المحرقة الشعب المتذمر، يأمر الرب موسى أن يرفع حية من نحاس على راية: كل من ينظر إليها يحيا. وهي صورة طبّقها يسوع على صلبه (يوحنا ٣: ١٤).","s":-1452,"pp":[["موسى","moses_2108"],["الله","god_1324"]]},{"i":"death-of-moses","k":"b","e":"egypt-exodus","y":-1406,"t":"موت موسى على جبل نبو","j":-1450,"r":[["Deu",34,null,34,null]],"d":84,"l":"جبل نبو، موآب","x":"بعد أن يرى موسى أرض الموعد من رأس الفسجة، يموت ابن مئة وعشرين سنة ولم تكلّ عينه. الرب نفسه يدفنه، ولم يقم بعد نبي في إسرائيل مثل موسى.","s":-1450,"pp":[["موسى","moses_2108"],["الله","god_1324"],["موآب","moab_2103"],["يعقوب","israel_682"]],"ll":["موآب"],"kx":"مُنع موسى من دخول كنعان بسبب ما حدث عند ماء مريبة، فرأى الأرض من رأس الفسجة ثم مات، ودفنه الرب في موضع لم يعرفه أحد. ويخلفه يشوع، واسمه بالعبرية «يهوشوع» أي «الرب يخلّص»، وهو الاسم نفسه الذي صار في اليونانية «يسوع». ويرى المفسرون في ذلك صورة: موسى، أي الشريعة، يوصل الشعب إلى حدود الأرض لكنه لا يُدخلهم، أما يشوع فيُدخلهم إلى الميراث. ويشير سفر العبرانيين إلى أن الراحة الحقيقية ما زالت باقية لشعب الله (عبرانيين ٤: ٨–٩)."},{"i":"jordan-crossing","k":"b","e":"conquest-judges","y":-1406,"t":"إسرائيل يعبر الأردن","j":-1450,"r":[["Jos",3,null,4,null]],"d":84,"l":"نهر الأردن","x":"حين تمس أقدام الكهنة حاملي التابوت مياه الأردن الممتلئ، تقف المياه ويعبر إسرائيل إلى كنعان على اليابسة: بحر أحمر جديد لجيل جديد. وتُقام اثنا عشر حجرًا للتذكار في الجلجال.","s":-1450,"pp":[["الله","god_1324"],["يشوع","joshua_1727"],["يعقوب","israel_682"],["موسى","moses_2108"]],"ll":["الأردن","أريحا","الجلجال"],"kx":"يعبر إسرائيل الأردن وهو ممتلئ في زمن الحصاد، وحين تمس أقدام الكهنة المياه تقف. يذكّر هذا بعبور البحر الأحمر، لكن الفرق أن العبور هنا دخول إلى الميراث لا هروب من العبودية. وتُقام اثنا عشر حجرًا من وسط النهر تذكارًا يعلّم الأجيال أمانة الله. وبهذه المعجزة ثبّت الله قيادة يشوع أمام الشعب، وأعلن أن الإله الذي أخرجهم من مصر هو نفسه الذي سيعطيهم النصرة في كنعان."},{"i":"fall-of-jericho","k":"b","e":"conquest-judges","y":-1406,"t":"سقوط أريحا","j":-1450,"r":[["Jos",6,null,6,null]],"d":85,"l":"أريحا","x":"ستة أيام يدور إسرائيل حول المدينة الحصينة صامتًا، وفي اليوم السابع يُضرب بالأبواق ويهتف الشعب فيسقط السور. وتُستحيا راحاب التي خبأت الجاسوسين، وتنضم إلى إسرائيل وإلى نسب المسيح.","s":-1450,"pp":[["الله","god_1324"],["يشوع","joshua_1727"],["راحاب","rahab_2388"]],"ll":["أريحا"],"kx":"دخول كنعان تحقيق لوعد الله لإبراهيم، ودينونة على شر سكان الأرض الذي «كمل» بعد صبر طويل (التكوين ١٥: ١٦). وسقوط أريحا حين ضُرب بالأبواق وهتف الشعب يعلن أن النصر بالإيمان والطاعة لا بقوة السلاح (عبرانيين ١١: ٣٠). وقصة التحريم الكامل لبعض المدن من أصعب نصوص الكتاب، ويفهمها المفسرون حكمًا من الله على خطية متراكمة لا نموذجًا يُقتدى به. ولم تُمتلك الأرض كلها في الحال، فبقي ما قاد إلى دائرة القضاة."},{"i":"t131","k":"b","e":"conquest-judges","y":-1406,"j":-1450,"est":1,"t":"الحرب مع ملوك كنعان","r":[["Jos",4,1,12,24]],"s":-1449.9399,"d":84,"pp":[["يشوع","joshua_1727"],["كنعان","canaan_914"]],"x":"بعد عبور الأردن يُختتن الجيل الجديد في الجلجال ويعمل الفصح، ويظهر ليشوع رئيس جند الرب. ثم تبدأ الحرب: أريحا وعاي، ثم الحملة الجنوبية بعد معاهدة جبعون، ثم الحملة الشمالية ضد يابين ملك حاصور وحلفائه. وينتهي القسم بقائمة واحد وثلاثين ملكًا ضربهم يشوع وبنو إسرائيل.","xs":1},{"i":"sun-stands-still","k":"b","e":"conquest-judges","y":-1400,"t":"الشمس تقف في جبعون","j":-1450,"r":[["Jos",10,null,10,null]],"d":86,"l":"جبعون ووادي أيلون","x":"يشوع يدافع عن جبعون أمام خمسة ملوك أموريين، ويصلي فتقف الشمس حتى يتم النصر: «ولم يكن مثل ذلك اليوم قبله ولا بعده، سمع فيه الرب صوت إنسان».","s":-1450,"pp":[["يشوع","joshua_1727"],["الله","god_1324"],["يعقوب","israel_682"],["أدوني صادق","adoni-zedek_101"]],"ll":["جبعون","لخيش","عجلون","مقيدة"]},{"i":"land-divided","k":"b","e":"conquest-judges","y":-1399,"t":"تقسيم الأرض على الأسباط","j":-1443,"r":[["Jos",13,null,21,null]],"d":87,"l":"كنعان","x":"بعد سنوات الحرب تُقسم الأرض على الأسباط بالقرعة في شيلوه. «لم تسقط كلمة من جميع الكلام الصالح الذي كلم به الرب بيت إسرائيل، بل الكل صار».","s":-1443,"pp":[["الله","god_1324"],["منسى","manasseh_1928"],["موسى","moses_2108"],["يعقوب","israel_682"],["يشوع","joshua_1727"],["يهوذا","judah_1751"]],"ll":["الأردن","يهوذا","منسى","أفرايم"]},{"i":"death-of-joshua","k":"b","e":"conquest-judges","y":-1380,"t":"وداع يشوع وموته","j":-1426,"r":[["Jos",23,null,24,null]],"d":93,"l":"شكيم","x":"يشوع يجمع إسرائيل في شكيم ليجدد العهد: «اختاروا لأنفسكم اليوم من تعبدون... وأما أنا وبيتي فنعبد الرب»، ثم يموت ابن مئة وعشر سنين.","s":-1426,"pp":[["الله","god_1324"],["يشوع","joshua_1727"],["موسى","moses_2108"],["إبراهيم","abraham_58"],["إسحاق","isaac_616"],["يعقوب","israel_682"]],"ll":["مصر","الأردن","شكيم"]},{"i":"t134","k":"b","e":"conquest-judges","y":-1368,"j":-1417,"est":1,"t":"استعباد إسرائيل لكوشان رشعتايم","r":[["Jdg",3,7,3,8]],"s":-1416.93,"d":94,"pp":[["كوشان رشعتايم","chushan-rishathaim_944"]],"ll":["كنعان","ما بين النهرين"],"x":"يعمل بنو إسرائيل الشر وينسون الرب ويعبدون البعليم والسواري، فيبيعهم الرب بيد كوشان رشعتايم ملك أرام النهرين، فيُستعبدون له ثماني سنين. ثم يصرخون إلى الرب فيقيم لهم عثنيئيل بن قناز مخلّصًا.","xs":1},{"i":"judges-cycle","k":"b","e":"conquest-judges","y":-1360,"t":"بداية دائرة القضاة","j":-1409,"r":[["Jdg",2,null,2,null]],"d":94,"l":"كنعان","x":"الجيل الذي بعد يشوع لم يعرف الرب وعبد البعليم. يدخل إسرائيل في دائرة متكررة: ارتداد ثم ضيق ثم صراخ ثم خلاص على يد قضاة يقيمهم الرب، و«كل واحد عمل ما حسن في عينيه».","s":-1409,"pp":[["عثنيئيل","othniel_2259"]],"ll":["كنعان"],"kx":"بعد موت يشوع يدخل إسرائيل في دائرة مظلمة تتكرر: ارتداد وعبادة للبعليم والعشتاروث، ثم ضيق من الأعداء، ثم صراخ إلى الرب، ثم خلاص على يد قاضٍ يقيمه الله. وجملة «كل واحد عمل ما حسن في عينيه» (القضاة ٢١: ٢٥) تلخص الفوضى الروحية. ودبورة وجدعون ويفتاح وشمشون يُظهرون أن الله يستخدم أدوات ناقصة ويبقى أمينًا رغم عدم أمانة الشعب. ويكشف السفر بتدهوره المتزايد حاجة الشعب إلى ملك بار، فيمهد لمملكة داود ثم للمسيح."},{"i":"tutankhamun","k":"w","e":"conquest-judges","y":-1332,"t":"عهد توت عنخ آمون","l":"مصر","x":"الملك الصبي يعيد آلهة مصر التقليدية بعد ثورة إخناتون الدينية الفاشلة. نُسي آلاف السنين، ثم جعله اكتشاف مقبرته كاملة سنة ١٩٢٢ أشهر الفراعنة.","s":-1332},{"i":"t136","k":"b","e":"conquest-judges","y":-1328,"j":-1377,"est":1,"t":"استعباد إسرائيل لعجلون ملك موآب","r":[["Jdg",3,12,3,14]],"s":-1376.93,"d":94,"pp":[["عجلون","eglon_1037"]],"ll":["كنعان","موآب"],"x":"يعود بنو إسرائيل إلى عمل الشر، فيشدد الرب عجلون ملك موآب عليهم، فيجمع إليه بني عمون وعماليق ويأخذ مدينة النخل. ويُستعبد بنو إسرائيل لعجلون ثماني عشرة سنة.","xs":1},{"i":"t137","k":"b","e":"conquest-judges","y":-1310,"j":-1359,"est":1,"t":"أهود ينقذ إسرائيل","r":[["Jdg",3,15,3,30]],"s":-1358.93,"d":94,"pp":[["إهود","ehud_1039"],["موآب","moab_2103"]],"ll":["كنعان"],"x":"يقيم الرب أهود بن جيرا البنياميني، وكان رجلًا أعسر. يصنع لنفسه سيفًا ذا حدين ويدخل إلى عجلون ملك موآب ويقتله في علية تبريده، ثم يهرب ويجمع إسرائيل فيضربون موآب. وتستريح الأرض ثمانين سنة.","xs":1},{"i":"battle-of-kadesh","k":"w","e":"conquest-judges","y":-1274,"t":"معركة قادش","l":"قادش، سوريا","x":"رمسيس الثاني ملك مصر يصطدم بإمبراطورية الحثيين في أكبر معركة مركبات معروفة، وتنتهي بلا غالب، ثم بأقدم معاهدة سلام دولية وصلت إلينا.","s":-1274},{"i":"t138","k":"b","e":"conquest-judges","y":-1236,"j":-1297,"est":1,"t":"يابين ملك كنعان يضايق إسرائيل","r":[["Jdg",4,1,4,3]],"s":-1296.93,"d":96,"pp":[["يابين","jabin_677"]],"ll":["كنعان","حاصور"],"x":"بعد موت أهود يعود بنو إسرائيل إلى الشر، فيبيعهم الرب بيد يابين ملك كنعان الذي ملك في حاصور، ورئيس جيشه سيسرا. وكان له تسع مئة مركبة حديد، فضايق بني إسرائيل بشدة عشرين سنة حتى صرخوا إلى الرب.","xs":1},{"i":"deborah-barak","k":"b","e":"conquest-judges","y":-1216,"t":"دبورة وباراق يهزمان سيسرا","j":-1277,"r":[["Jdg",4,null,5,null]],"d":96,"l":"جبل تابور ووادي قيشون","x":"النبية دبورة تدعو باراق لمحاربة سيسرا قائد الكنعانيين ومعه تسع مئة مركبة حديد. المركبات تغوص عند نهر قيشون، ويموت سيسرا في خيمة ياعيل، ويُحتفل بالنصر في واحد من أقدم أناشيد الكتاب.","s":-1277,"pp":[["باراق","barak_401"],["دبورة","deborah_997"]],"ll":["كنعان"]},{"i":"olmec-civilization","k":"w","e":"conquest-judges","y":-1200,"t":"ظهور حضارة الأولمك","l":"ساحل الخليج، أمريكا الوسطى","x":"«الحضارة الأم» في أمريكا الوسطى تقوم في سهول المكسيك الحالية، وتنحت رؤوسًا حجرية ضخمة، وتضع أسس التقويم والطقوس والمعابد لعوالم المايا والأزتك.","s":-1200},{"i":"trojan-war","k":"w","e":"conquest-judges","y":-1184,"t":"حرب طروادة","l":"طروادة، آسيا الصغرى","x":"التاريخ التقليدي لسقوط طروادة أمام اليونانيين المحاصرين لها: حرب أخيل وهكتور والحصان الخشبي، التي خلّدتها إلياذة هوميروس بعد قرون.","s":-1184},{"i":"t140","k":"b","e":"conquest-judges","y":-1177,"j":-1257,"est":1,"t":"مديان يضايق إسرائيل","r":[["Jdg",6,1,6,10]],"s":-1256.9299,"d":96,"pp":[["مديان","midian_2075"]],"ll":["كنعان","مديان"],"x":"يدفع الرب إسرائيل ليد مديان سبع سنين. وكان المديانيون والعمالقة يصعدون مثل الجراد فيتلفون غلة الأرض ولا يتركون قوتًا، فيصنع بنو إسرائيل لأنفسهم مخابئ في الجبال والكهوف. ولما صرخوا أرسل الرب إليهم نبيًا يذكّرهم بخلاصه وبعصيانهم.","xs":1},{"i":"bronze-age-collapse","k":"w","e":"conquest-judges","y":-1177,"t":"انهيار العصر البرونزي","l":"شرق المتوسط","x":"في جيل واحد تنهار حضارات القصور في شرق المتوسط، مثل ميسيناي والحثيين وأوغاريت، وسط غزوات «شعوب البحر» والمجاعات والاضطرابات. ومن بين المهاجرين الفلسطينيون الذين استقروا على ساحل كنعان.","s":-1177},{"i":"gideon","k":"b","e":"conquest-judges","y":-1170,"t":"جدعون والثلاث مئة","j":-1250,"r":[["Jdg",6,null,7,null]],"d":96,"l":"وادي يزرعيل","x":"الله يقلل جيش جدعون من ٣٢ ألفًا إلى ثلاث مئة رجل لئلا يفتخر إسرائيل بقوته. وبالمصابيح والجرار والأبواق يهزمون جيش مديان الكبير ليلًا.","s":-1250,"pp":[["جدعون","gideon_1314"]],"ll":["كنعان"]},{"i":"t142","k":"b","e":"conquest-judges","y":-1137,"j":-1217,"est":1,"t":"أبيمالك يغتصب الملك","r":[["Jdg",8,29,9,57]],"s":-1216.9299,"d":97,"pp":[["أبيمالك","abimelech_41"]],"ll":["كنعان"],"x":"بعد موت جدعون يذهب ابنه أبيمالك إلى أهل أمه في شكيم، ويقتل إخوته السبعين على حجر واحد، ويُملَّك على شكيم. ينجو منهم يوثام فيقول مثل الأشجار التي طلبت ملكًا. وبعد ثلاث سنين تقع الفتنة بينه وبين أهل شكيم، ويموت عند تاباص حين تطرح امرأة قطعة رحى على رأسه.","xs":1},{"i":"t143","k":"b","e":"conquest-judges","y":-1134,"j":-1214,"est":1,"t":"تولع قاضيًا","r":[["Jdg",10,1,10,2]],"s":-1213.9299,"d":98,"pp":[["تولع","tola_2879"]],"ll":["كنعان"],"x":"بعد أبيمالك يقوم تولع بن فواة، من سبط يساكر، ليخلّص إسرائيل. كان ساكنًا في شامير في جبل أفرايم، وقضى لإسرائيل ثلاثًا وعشرين سنة، ثم مات ودُفن في شامير.","xs":1},{"i":"t67","k":"b","e":"conquest-judges","y":-1132,"j":-1191,"est":1,"t":"يائير قاضيًا","r":[["Jdg",10,3,10,5]],"s":-1190.9299,"d":98,"pp":[["يائير","jair_709"]],"ll":["كنعان"],"x":"يقوم بعده يائير الجلعادي ويقضي لإسرائيل اثنتين وعشرين سنة. وكان له ثلاثون ولدًا يركبون على ثلاثين جحشًا، ولهم ثلاثون مدينة تُدعى «حووث يائير» في أرض جلعاد.","xs":1},{"i":"t144","k":"b","e":"conquest-judges","y":-1110,"j":-1169,"est":1,"t":"ضيق من بني عمون والفلسطينيين","r":[["Jdg",10,6,10,18]],"s":-1168.9299,"d":98,"ll":["كنعان"],"x":"يعود بنو إسرائيل فيعبدون آلهة كثيرة ويتركون الرب، فيبيعهم بيد الفلسطينيين وبني عمون، فيُضايَقون ثماني عشرة سنة خاصة في جلعاد. يعترفون بخطيتهم وينزعون الآلهة الغريبة، فيقول الكتاب إن نفس الرب «ضاقت بسبب مشقة إسرائيل».","xs":1},{"i":"samuel-born","k":"b","e":"conquest-judges","y":-1105,"t":"ميلاد صموئيل","j":-1164,"r":[["1Sa",1,null,1,null]],"d":99,"l":"شيلوه","x":"حنة العاقر تسكب نفسها أمام الرب فيعطيها ابنًا تكرسه لخدمة الله في شيلوه. صموئيل سيصير نبيًا وقاضيًا ومن يمسح الملوك: الجسر بين زمن القضاة وزمن الملوك.","s":-1164,"pp":[["الله","god_1324"],["حنة","hannah_1400"],["عالي","eli_1072"],["ألقانة","elkanah_1168"],["فننة","peninnah_2313"]],"ll":["شيلوه"]},{"i":"t145","k":"b","e":"conquest-judges","y":-1102,"j":-1161,"est":1,"t":"عالي الكاهن قاضيًا","r":[["1Sa",4,15,4,18]],"s":-1160.91,"d":101,"pp":[["عالي","eli_1072"]],"ll":["كنعان"],"x":"عالي الكاهن يقضي لإسرائيل أربعين سنة في شيلوه. وحين يأتيه خبر هزيمة إسرائيل وموت ابنيه وأخذ تابوت الله، يسقط عن الكرسي إلى الوراء فتنكسر رقبته ويموت، وهو ابن ثمان وتسعين سنة.","xs":1},{"i":"ruth","k":"b","e":"conquest-judges","y":-1100,"t":"راعوث تلتقط في حقل بوعز","j":-1307,"r":[["Rut",1,null,4,null]],"d":94,"l":"بيت لحم","x":"في أيام القضاة المظلمة، أرملة موآبية تلتصق بإله إسرائيل وشعبه. بوعز يفتديها، فتصير راعوث جدة داود الملك: أممية دخلت في نسب المسيح.","s":-1307,"pp":[["نعمي","naomi_2147"],["بوعز","boaz_519"],["الله","god_1324"],["راعوث","ruth_2450"],["موآب","moab_2103"],["أليمالك","elimelech_1134"]],"ll":["موآب","بيت لحم"]},{"i":"t147","k":"b","e":"conquest-judges","y":-1089,"j":-1145,"est":1,"t":"إبصان قاضيًا","r":[["Jdg",12,8,12,10]],"s":-1144.9299,"d":99,"pp":[["إبصان","ibzan_1588"]],"ll":["كنعان"],"x":"بعد يفتاح يقضي لإسرائيل إبصان من بيت لحم سبع سنين. وكان له ثلاثون ابنًا وثلاثون ابنة، زوّج بناته خارج عشيرته وأتى بثلاثين ابنة من الخارج لبنيه.","xs":1},{"i":"ark-captured","k":"b","e":"conquest-judges","y":-1084,"t":"الفلسطينيون يأخذون التابوت","j":-1140,"r":[["1Sa",4,null,6,null]],"d":101,"l":"أفيق وأشدود","x":"إسرائيل يحمل التابوت إلى الحرب كأنه تميمة فيأخذه الفلسطينيون، ويموت ابنا عالي، و«زال المجد من إسرائيل». لكن داجون يسقط أمام التابوت في بيته، فيرجعه الفلسطينيون.","s":-1140,"pp":[["الله","god_1324"],["عالي","eli_1072"],["داجون","dagon_969"],["حفني","hophni_1550"],["فينحاس","phinehas_2350"],["يهوشع","joshua_1728"]],"ll":["بيت شمس","أشدود","شيلوه","عقرون"]},{"i":"t148","k":"b","e":"conquest-judges","y":-1084,"j":-1140,"est":1,"t":"تسلّط الفلسطينيين","r":[["Jdg",13,1,15,20]],"s":-1139.9299,"d":100,"pp":[["شمشون","samson_2468"]],"ll":["كنعان"],"x":"يعود بنو إسرائيل يعملون الشر، فيدفعهم الرب ليد الفلسطينيين أربعين سنة، أطول تسلط في سفر القضاة. وفي هذه الفترة يولد شمشون الذي يبتدئ أن يخلّص إسرائيل من يد الفلسطينيين.","xs":1},{"i":"t149","k":"b","e":"conquest-judges","y":-1082,"j":-1138,"est":1,"t":"إيلون قاضيًا","r":[["Jdg",12,11,12,12]],"s":-1137.9299,"d":99,"pp":[["إيلون","elon_1184"]],"ll":["كنعان"],"x":"يقضي لإسرائيل بعد إبصان إيلون الزبولوني عشر سنين، ثم يموت ويُدفن في أيلون في أرض زبولون.","xs":1},{"i":"t150","k":"b","e":"conquest-judges","y":-1078,"j":-1134,"est":1,"t":"ميلاد شاول","r":[["1Sa",9,2,9,2]],"s":-1133.9099,"d":104,"pp":[["شاول","saul_2478"]],"x":"يقدّم سفر صموئيل شاول بن قيس البنياميني بأنه «شاب وحسن، ولم يكن رجل في بني إسرائيل أحسن منه، من كتفه فما فوق كان أطول من كل الشعب». ويضع Theographic ميلاده هنا بحسب أعمار ملكه.","xs":1},{"i":"samson","k":"b","e":"conquest-judges","y":-1075,"t":"شمشون ضد الفلسطينيين","j":-1154,"r":[["Jdg",13,null,16,null]],"d":100,"l":"أرض الفلسطينيين","x":"النذير الجبار يحارب الفلسطينيين وحده، ويسقط بخيانة دليلة، وعند موته يهدم بيت داجون فيكون الموتى الذين أماتهم في موته أكثر من الذين أماتهم في حياته.","s":-1154,"pp":[["شمشون","samson_2468"],["الله","god_1324"],["منوح","manoah_1933"],["دليلة","delilah_1005"],["الروح القدس","holy_spirit_7400"],["يهوذا","judah_1751"]],"ll":["صرعة","تمنة","لحي","أشتأول"]},{"i":"t146","k":"b","e":"conquest-judges","y":-1072,"j":-1151,"est":1,"t":"يفتاح ينقذ إسرائيل","r":[["Jdg",11,1,12,7]],"s":-1150.9299,"d":98,"pp":[["يفتاح","jephthah_839"]],"ll":["كنعان"],"x":"يفتاح الجلعادي ابن امرأة زانية، طرده إخوته فسكن أرض طوب، ثم يدعوه شيوخ جلعاد ليقودهم ضد بني عمون. يحاور ملك عمون بتاريخ إسرائيل، ثم ينذر نذرًا متسرعًا قبل المعركة، وينتصر فتكون ابنته الوحيدة هي أول من يخرج لاستقباله. وبعدها يحارب الأفرايميين ويُعرفون بنطق كلمة «شبولت».","xs":1},{"i":"t151","k":"b","e":"conquest-judges","y":-1072,"j":-1128,"est":1,"t":"عبدون قاضيًا","r":[["Jdg",12,13,12,15]],"s":-1127.9299,"d":99,"pp":[["عبدون","abdon_10"]],"ll":["كنعان"],"x":"يقضي عبدون بن هليل الفرعتوني لإسرائيل ثماني سنين. وكان له أربعون ابنًا وثلاثون حفيدًا يركبون على سبعين جحشًا، ثم مات ودُفن في فرعتون في أرض أفرايم.","xs":1},{"i":"zhou-dynasty","k":"w","e":"conquest-judges","y":-1046,"t":"تأسيس أسرة تشو في الصين","l":"الصين","x":"أسرة تشو تُسقط أسرة شانغ وتعلن «تفويض السماء»، أي أن السماء تمنح حق الحكم وتنزعه، وتحكم الصين ثمانية قرون، وهي أطول أسرة حاكمة فيها.","s":-1046},{"i":"saul-anointed","k":"b","e":"united-kingdom","y":-1050,"t":"مسح شاول أول ملك على إسرائيل","j":-1111,"r":[["1Sa",8,null,10,null]],"d":103,"l":"الرامة والمصفاة","x":"إسرائيل يطلب ملكًا «كسائر الشعوب». ومع أن الطلب رفضٌ لملك الرب عليهم، يستجيب الله: صموئيل يمسح شاول البنياميني، وكان من كتفه فما فوق أطول من كل الشعب.","s":-1111,"pp":[["صموئيل","samuel_2469"],["الله","god_1324"],["شاول","saul_2478"],["بنيامين","benjamin_463"],["قيس","kish_1784"],["يعقوب","israel_682"]],"ll":["مصر"],"kx":"يطلب الشعب ملكًا «كسائر الشعوب» (صموئيل الأول ٨: ٥)، فيقول الرب لصموئيل: «لم يرفضوك أنت بل إياي رفضوا» (٨: ٧). ويحذرهم صموئيل من ثمن الملكية، ثم يمسح شاول أول ملك. سمح الله بالملكية، ومنها جاء لاحقًا بيت داود الذي يأتي منه المسيح. وصموئيل، النبي والقاضي الذي قدّم الذبائح أيضًا، آخر القضاة وأول سلسلة الأنبياء. ورغبة الشعب في ملك يُرى بدل الملك غير المنظور تشبه ميل الإنسان الدائم إلى العيان بدل الإيمان."},{"i":"david-anointed","k":"b","e":"united-kingdom","y":-1025,"t":"صموئيل يمسح داود","j":-1062,"r":[["1Sa",16,null,16,null]],"d":106,"l":"بيت لحم","x":"بعد عصيان شاول يرسل الله صموئيل إلى بيت لحم، فيعبر عن سبعة من بني يسى إلى الأصغر، الراعي. «لأن الإنسان ينظر إلى العينين، وأما الرب فإنه ينظر إلى القلب».","s":-1062,"pp":[["الله","god_1324"],["يسى","jesse_903"],["شاول","saul_2478"],["صموئيل","samuel_2469"],["داود","david_994"],["الروح القدس","holy_spirit_7400"]],"kx":"يرسل الله صموئيل ليمسح داود، واسمه معناه «المحبوب»، وهو أصغر أبناء يسى. فارق روح الرب شاول وحلّ على داود. وانتصاره على جليات يُظهر انتصار الإيمان على ما يبدو مستحيلًا، وسنوات هروبه من شاول هيأته للملك من خلال الألم، كما سبق اتضاع المسيح مجده. وعهد الله معه في صموئيل الثاني ٧، بعرش وملك ثابت إلى الأبد، صار أساس رجاء المسيا، والمسيح هو «ابن داود» و«ربه» معًا (متى ٢٢: ٤٢–٤٥)."},{"i":"david-goliath","k":"b","e":"united-kingdom","y":-1024,"t":"داود يهزم جليات","j":-1066,"r":[["1Sa",17,null,17,null]],"d":107,"l":"وادي البطم","x":"بينما جيش إسرائيل يرتعب أمام جبار الفلسطينيين، يرد الراعي الصغير على تعييره باسم رب الجنود، ويصرعه بحجر واحد من مقلاعه.","s":-1066,"pp":[["داود","david_994"],["جليات","goliath_1327"]]},{"i":"t158","k":"b","e":"united-kingdom","y":-1013,"j":-1055,"est":1,"t":"موت شاول","r":[["1Sa",31,3,31,13]],"s":-1054.9097,"d":116,"pp":[["شاول","saul_2478"]],"ll":["جبل جلبوع"],"x":"في معركة جبل جلبوع يُقتل بنو شاول، ومنهم يوناثان، ويُصاب شاول من الرماة. يطلب من حامل سلاحه أن يقتله فيرفض، فيأخذ السيف ويسقط عليه. ويعلّق الفلسطينيون جثته على سور بيت شان، فيقوم رجال يابيش جلعاد ليلًا ويأخذونها ويدفنونها ويصومون سبعة أيام.","xs":1,"kx":"بدأ ملك شاول بداية حسنة: كان متواضعًا وحلّ عليه روح الله. لكن طاعته الناقصة، حين قدّم المحرقة بنفسه وأبقى على أجاج، كشفت أن الشكل الخارجي دون طاعة القلب لا يُرضي الله. وكلمة صموئيل له صارت مبدأ نبويًا: «هوذا الاستماع أفضل من الذبيحة» (صموئيل الأول ١٥: ٢٢). رفضه الله واختار داود لأنه «ينظر إلى القلب». ثم انحدر شاول إلى الغيرة والاضطراب وطلب صاحبة الجان، وانتهت حياته على جبل جلبوع."},{"i":"david-king-judah","k":"b","e":"united-kingdom","y":-1010,"t":"داود ملكًا على يهوذا","j":-1052,"r":[["2Sa",2,null,2,null]],"d":118,"l":"حبرون","x":"بعد أن يسقط شاول في جبل جلبوع، يُمسح داود ملكًا على سبط يهوذا في حبرون، ويملك هناك سبع سنين وستة أشهر بينما يضعف بيت شاول.","s":-1052,"pp":[["أبنير","abner_57"],["داود","david_994"],["يوآب","joab_1617"],["عسائيل","asahel_320"],["يهوذا","judah_1751"],["شاول","saul_2478"]],"ll":["حبرون","جبعون","محنايم","يابيش جلعاد"]},{"i":"psalms-composed","k":"b","e":"united-kingdom","y":-1010,"t":"مزامير داود","ye":-970,"r":[["Psa",1,null,1,null]],"d":269,"l":"أورشليم","jk":-1055,"x":"على مدى ملكه المضطرب يسكب الملك الراعي مراثي وتسابيح وأناشيد ملكية صارت قلب عبادة إسرائيل، وسفر المزامير هو أكثر سفر يقتبس منه العهد الجديد.","s":-1010,"pp":[["الله","god_1324"]]},{"i":"jerusalem-capital","k":"b","e":"united-kingdom","y":-1003,"t":"داود يأخذ أورشليم","j":-1047,"r":[["2Sa",5,null,5,null]],"d":119,"l":"أورشليم","x":"بعد أن يُمسح ملكًا على كل إسرائيل، يأخذ داود حصن صهيون من اليبوسيين ويجعل أورشليم عاصمته: مدينة داود التي صارت من بعدها قلب قصة إسرائيل.","s":-1047,"pp":[["داود","david_994"],["الله","god_1324"]],"ll":["حبرون","أورشليم","وادي الرفائيين"]},{"i":"ark-to-jerusalem","k":"b","e":"united-kingdom","y":-1000,"t":"إصعاد التابوت إلى أورشليم","j":-1041,"r":[["2Sa",6,null,6,null]],"d":120,"l":"أورشليم","x":"بالذبائح والهتاف وصوت البوق، وداود يرقص بكل قوته أمام الرب، يُصعد تابوت العهد إلى أورشليم، فيجتمع العرش والعبادة في مدينة واحدة.","s":-1041,"pp":[["الله","god_1324"],["داود","david_994"],["عزة","uzzah_2916"],["ميكال","michal_2073"],["أبيناداب","abinadab_43"],["أخيو","ahio_154"]]},{"i":"phoenician-alphabet","k":"w","e":"united-kingdom","y":-1000,"t":"انتشار الأبجدية الفينيقية","l":"صور وصيدون، فينيقية","x":"تجار فينيقية يحملون أبجديتهم ذات الاثنين والعشرين حرفًا عبر المتوسط. أخذها اليونان ثم الرومان، وصارت أصل معظم أبجديات العالم، ومن فروعها البعيدة الأبجدية العربية.","s":-1000},{"i":"iron-age-levant","k":"w","e":"united-kingdom","y":-1000,"t":"الحديد يغيّر الشرق الأدنى","l":"شرق المتوسط","x":"صهر الحديد ينتشر في بلاد الشام، فتصير الأدوات والأسلحة أصلب وأرخص وفي أيدي عامة الناس. وفي البداية كان احتكار الفلسطينيين للحدادة (صموئيل الأول ١٣: ١٩–٢٢) يعطيهم تفوقًا عسكريًا على إسرائيل.","s":-1000},{"i":"vedas-compiled","k":"w","e":"united-kingdom","y":-1000,"t":"تدوين الفيدا في الهند","l":"شبه القارة الهندية","x":"ترانيم «الريج فيدا» التي تناقلتها الألسن قرونًا تُجمع في مجموعات صارت أساس الكتب الهندوسية، وهي من أقدم النصوص الدينية التي لا تزال مستخدمة.","s":-1000},{"i":"davidic-covenant","k":"b","e":"united-kingdom","y":-995,"t":"العهد مع داود","j":-1041,"r":[["2Sa",7,null,7,null]],"d":120,"l":"أورشليم","x":"داود يريد أن يبني للرب بيتًا، فيعده الرب بأن يبني هو لداود بيتًا: نسلًا وعرشًا ثابتًا إلى الأبد. ووعد ابن داود الأبدي يصير عمود رجاء المسيا.","s":-1041,"pp":[["الله","god_1324"],["داود","david_994"],["ناثان","nathan_2153"],["يعقوب","israel_682"]],"ll":["مصر"],"kx":"يأخذ داود أورشليم ويجعلها عاصمة سياسية ودينية، ويُصعد إليها التابوت بفرح عظيم. ثم يريد أن يبني لله بيتًا، فيقلب الله الخطة: هو الذي سيبني لداود «بيتًا» أي نسلًا ومُلكًا. وهذا العهد (صموئيل الثاني ٧) بعرش ثابت إلى الأبد صار محور الرجاء المسياني في الكتاب كله. ومزامير داود أعطت شعب الله لغة للعبادة والرثاء والنبوة. وخطيته مع بثشبع ثم توبته (المزمور ٥١) تبيّن أن حتى «الرجل الذي حسب قلب الله» يحتاج إلى الفداء."},{"i":"david-bathsheba","k":"b","e":"united-kingdom","y":-993,"t":"خطية داود مع بثشبع","j":-1034,"r":[["2Sa",11,null,12,null]],"d":132,"l":"أورشليم","x":"في قمة قوته يزني داود مع بثشبع ويدبر قتل زوجها. يواجهه ناثان بمثل وكلمة «أنت هو الرجل»، فيتوب، ومن توبته يأتي المزمور الحادي والخمسون.","s":-1034,"pp":[["داود","david_994"],["أوريا","uriah_2898"],["الله","god_1324"],["يوآب","joab_1617"],["ناثان","nathan_2153"],["بثشبع","bathsheba_416"]],"ll":["ربة","أورشليم"]},{"i":"solomon-king","k":"b","e":"united-kingdom","y":-970,"t":"سليمان ملكًا","j":-1014,"r":[["1Ki",1,null,3,null]],"d":143,"l":"أورشليم","x":"سليمان بن داود يجلس على العرش، وحين يقول له الله في جبعون «اسأل ماذا أعطيك»، يطلب قلبًا فهيمًا ليحكم الشعب. فيعطيه الله حكمة لم يكن مثلها، ومعها الغنى والكرامة اللذان لم يطلبهما.","s":-1014,"pp":[["سليمان","solomon_2762"],["الله","god_1324"],["داود","david_994"],["أدونيا","adonijah_97"],["بناياهو","benaiah_439"],["يهوياداع","jehoiada_792"]],"ll":["أورشليم","جيحون","جت","جبعون"],"kx":"سليمان، واسمه مرتبط بكلمة «السلام»، يخلف داود ويعطيه الله حكمة لم يكن مثلها. يبني الهيكل فيتحقق اشتياق أبيه، ويصير للتابوت وحضور الله مسكن ثابت، وفي التدشين يملأ مجد الرب البيت (الملوك الأول ٨: ١٠–١١). وجذبت حكمته الملوك ومنهم ملكة سبا، ومن كتاباته الأمثال والجامعة ونشيد الأنشاد. لكن نساءه الغريبات أملن قلبه إلى الأوثان، وضرائبه الثقيلة زرعت بذور الانقسام. ويقول يسوع عن نفسه: «هوذا أعظم من سليمان ههنا» (متى ١٢: ٤٢)."},{"i":"t160","k":"b","e":"united-kingdom","y":-970,"j":-1014,"est":1,"t":"موت داود","r":[["1Ki",2,10,2,11]],"s":-1013.89,"d":147,"pp":[["داود","david_994"]],"ll":["أورشليم"],"x":"يموت داود ويُدفن في مدينة داود بعد أن ملك على إسرائيل أربعين سنة: سبع سنين في حبرون وثلاثًا وثلاثين سنة في أورشليم. وقبل موته يوصي سليمان أن يحفظ شريعة الرب ويسلك في طرقه.","xs":1},{"i":"hiram-of-tyre","k":"w","e":"united-kingdom","y":-969,"t":"حيرام الأول يملك على صور","l":"صور، فينيقية","x":"في عهد حيرام تصير صور القوة البحرية الكبرى في المتوسط. ويذكر الكتاب صداقته لداود وسليمان، إذ أرسل خشب الأرز والصناع والبحارة للهيكل ولأسطول إسرائيل التجاري.","s":-969},{"i":"temple-begun","k":"b","e":"united-kingdom","y":-966,"t":"بدء بناء الهيكل الأول","j":-1011,"r":[["1Ki",6,null,6,null]],"d":150,"l":"جبل المريا، أورشليم","x":"في السنة الرابعة لملكه، بعد ٤٨٠ سنة من الخروج، يبدأ سليمان بناء بيت الرب على جبل المريا: أرز من لبنان وحجارة منحوتة وتلبيس بالذهب، وقد استغرق البناء سبع سنين.","s":-1011,"ll":["أورشليم"]},{"i":"temple-dedicated","k":"b","e":"united-kingdom","y":-959,"t":"تدشين هيكل سليمان","j":-1003,"r":[["1Ki",8,null,8,null]],"d":151,"l":"أورشليم","x":"يُدخل التابوت إلى قدس الأقداس، ويملأ مجد الرب البيت حتى لا يستطيع الكهنة أن يقفوا للخدمة. ويصلي سليمان أن يسمع الرب حتى للغريب الذي يصلي نحو هذا البيت.","s":-1003,"pp":[["الله","god_1324"],["داود","david_994"],["سليمان","solomon_2762"],["يعقوب","israel_682"],["موسى","moses_2108"]],"ll":["مصر","قدس الأقداس","القدس"]},{"i":"queen-of-sheba","k":"b","e":"united-kingdom","y":-950,"t":"ملكة سبا تزور سليمان","j":-1014,"r":[["1Ki",10,null,10,null]],"d":163,"l":"أورشليم","x":"ملكة سبا تسمع بخبر سليمان فتأتي من جنوب الجزيرة العربية لتمتحنه بمسائل، ومعها جمال حاملة أطيابًا وذهبًا. وحين ترى حكمته ومملكته «لم يبق فيها روح بعد».","s":-1014,"pp":[["سليمان","solomon_2762"],["الله","god_1324"],["ملكة سبا","queen_of_sheba_2379"],["حيرام","hiram_1532"]],"ll":["سبا","أورشليم","لبنان","مصر"]},{"i":"t164","k":"b","e":"united-kingdom","y":-931,"j":-974,"est":1,"t":"موت سليمان","r":[["1Ki",11,43,11,43]],"s":-973.8899,"d":164,"pp":[["سليمان","solomon_2762"]],"ll":["أورشليم"],"x":"يموت سليمان بعد أن ملك في أورشليم على كل إسرائيل أربعين سنة، ويُدفن في مدينة داود أبيه. ويملك رحبعام ابنه عوضًا عنه، وتأتي بعدها مباشرة أزمة الانقسام.","xs":1},{"i":"t165","k":"b","e":"united-kingdom","y":-931,"j":-974,"est":1,"t":"ملك رحبعام (يهوذا)","r":[["1Ki",12,17,12,24]],"s":-973.8899,"d":164,"pp":[["رحبعام","rehoboam_2412"]],"ll":["أورشليم"],"x":"بعد انفصال الأسباط العشرة يجمع رحبعام جيشًا ليحارب إسرائيل ويرد المملكة، لكن كلام الرب يأتي على يد شمعيا رجل الله: «لا تصعدوا ولا تحاربوا إخوتكم»، فيرجعون. ملك رحبعام سبع عشرة سنة في أورشليم، وفي أيامه غزا شيشق ملك مصر المدينة.","xs":1},{"i":"t167","k":"b","e":"united-kingdom","y":-931,"j":-974,"est":1,"t":"ملك يربعام الأول (إسرائيل)","r":[["1Ki",12,20,14,20]],"s":-973.8899,"d":164,"pp":[["يربعام","jeroboam_872"]],"ll":["السامرة"],"x":"يُملَّك يربعام بن نباط على الأسباط العشرة، ويصنع عجلي ذهب في بيت إيل ودان لكي لا يصعد الشعب إلى أورشليم. ويأتي رجل الله من يهوذا فيتنبأ على مذبح بيت إيل فينشق المذبح، ويتنبأ أخيا النبي بخراب بيته. ملك اثنتين وعشرين سنة، وصارت «خطية يربعام» مثلًا يتكرر عن ملوك إسرائيل بعده.","xs":1},{"i":"kingdom-divides","k":"b","e":"divided-kingdom","y":-930,"t":"انقسام المملكة","j":-973,"r":[["1Ki",12,null,12,null]],"d":164,"l":"شكيم","x":"رحبعام يتوعد بأن يحكم بقسوة أكثر من أبيه سليمان، فتنفصل الأسباط العشرة الشمالية تحت يربعام. يصير إسرائيل ويهوذا مملكتين متنافستين، وعجلا الذهب في دان وبيت إيل يرسمان طريق الشمال في عبادة الأوثان.","s":-973,"pp":[["رحبعام","rehoboam_2412"],["يربعام","jeroboam_872"],["يهوذا","judah_1751"],["سليمان","solomon_2762"],["الله","god_1324"],["داود","david_994"]],"ll":["أورشليم","بيت إيل","شكيم","مصر"],"kx":"رحبعام بن سليمان يرفض بحماقة أن يخفف النير، فتتمرد الأسباط العشرة الشمالية تحت يربعام، وتنقسم المملكة إلى إسرائيل في الشمال ويهوذا في الجنوب (ومعه بنيامين). ويقيم يربعام في الحال عجلي ذهب في دان وبيت إيل حتى لا يصعد الشعب إلى أورشليم. تم الانقسام كما سبق الرب فأنذر (الملوك الأول ١١: ١١). وتعاقبت على المملكة الشمالية أسر حاكمة كثيرة، ولا يمدح السفر أحدًا من ملوكها، بينما حفظ الله في يهوذا نسل داود. وخاطب الأنبياء المملكتين بالدعوة إلى الأمانة والإنذار بالدينونة ورجاء الرد."},{"i":"t168","k":"b","e":"divided-kingdom","y":-914,"j":-957,"est":1,"t":"ملك أبيام (يهوذا)","r":[["1Ki",15,1,15,8]],"s":-956.8898,"d":169,"pp":[["أبيا","abijah_38"]],"ll":["أورشليم"],"x":"يملك أبيام بن رحبعام على يهوذا ثلاث سنين، ويسير في خطايا أبيه، «ولم يكن قلبه كاملًا مع الرب إلهه كقلب داود أبيه». لكن الرب أبقى له سراجًا في أورشليم من أجل داود. وكانت الحرب بينه وبين يربعام.","xs":1},{"i":"t170","k":"b","e":"divided-kingdom","y":-912,"j":-955,"est":1,"t":"ملك آسا (يهوذا)","r":[["1Ki",15,9,15,24]],"s":-954.8898,"d":169,"pp":[["آسا","asa_318"]],"ll":["أورشليم"],"x":"يملك آسا على يهوذا إحدى وأربعين سنة، ويعمل المستقيم في عيني الرب كداود أبيه: يُبيد الأصنام، ويخلع جدته معكة من أن تكون ملكة. ولما حاربه بعشا ملك إسرائيل استعان بملك أرام بفضة الهيكل وذهبه. وفي شيخوخته مرض في رجليه.","xs":1},{"i":"t171","k":"b","e":"divided-kingdom","y":-910,"j":-953,"est":1,"t":"ملك ناداب (إسرائيل)","r":[["1Ki",15,25,15,26]],"s":-952.8898,"d":169,"pp":[["ناداب","nadab_2129"]],"ll":["السامرة"],"x":"يملك ناداب بن يربعام على إسرائيل سنتين، ويعمل الشر في عيني الرب ويسير في خطية أبيه. وبينما كان يحاصر جبثون يفتن عليه بعشا ويقتله، ثم يضرب كل بيت يربعام كما تكلم الرب على لسان أخيا الشيلوني.","xs":1},{"i":"t172","k":"b","e":"divided-kingdom","y":-909,"j":-952,"est":1,"t":"ملك بعشا (إسرائيل)","r":[["1Ki",15,33,16,5]],"s":-951.8898,"d":169,"pp":[["بعشا","baasha_589"]],"ll":["السامرة"],"x":"يملك بعشا بن أخيا على إسرائيل في ترصة أربعًا وعشرين سنة، ويعمل الشر ويسير في طريق يربعام. ويأتي كلام الرب على يد ياهو بن حناني بأن بيته سيُباد كبيت يربعام، لأنه أغاظ الرب بعمل يديه.","xs":1},{"i":"t173","k":"b","e":"divided-kingdom","y":-884,"j":-929,"est":1,"t":"ملك أيلة (إسرائيل)","r":[["1Ki",16,6,16,8]],"s":-928.8898,"d":170,"pp":[["أيلة","elah_1045"]],"ll":["السامرة"],"x":"يملك أيلة بن بعشا على إسرائيل سنتين في ترصة. وبينما كان يشرب ويسكر في بيت رئيس بيته، يفتن عليه زمري رئيس نصف المركبات ويقتله، ويبيد كل بيت بعشا.","xs":1},{"i":"t174","k":"b","e":"divided-kingdom","y":-883,"j":-928,"est":1,"t":"ملك زمري (إسرائيل)","r":[["1Ki",16,15,16,16]],"s":-927.8898,"d":170,"pp":[["زمري","zimri_3088"]],"ll":["السامرة"],"x":"يملك زمري سبعة أيام فقط في ترصة. ولما سمع الشعب المحاصر لجبثون بقتل الملك ملّكوا عمري رئيس الجيش، فحاصر ترصة. ولما رأى زمري أن المدينة أُخذت دخل قصر الملك وأحرقه على نفسه ومات.","xs":1},{"i":"t175","k":"b","e":"divided-kingdom","y":-883,"j":-928,"est":1,"t":"ملك تبني (إسرائيل)","r":[["1Ki",16,21,16,22]],"s":-927.8898,"d":170,"pp":[["تبني","tibni_2853"]],"ll":["السامرة"],"x":"بعد موت زمري ينقسم شعب إسرائيل نصفين: نصف وراء تبني بن جينة ليملّكوه، ونصف وراء عمري. ويقوى الشعب الذي وراء عمري، فيموت تبني ويملك عمري.","xs":1},{"i":"t176","k":"b","e":"divided-kingdom","y":-883,"j":-928,"est":1,"t":"ملك عمري (إسرائيل)","r":[["1Ki",16,22,16,28]],"s":-927.8898,"d":170,"pp":[["عمري","omri_2243"]],"ll":["السامرة"],"x":"يملك عمري على إسرائيل اثنتي عشرة سنة، منها ست في ترصة. يشتري جبل السامرة من شامر بوزنتين من الفضة ويبني عليه مدينة السامرة التي صارت عاصمة المملكة الشمالية. ويقول الكتاب إنه «أساء أكثر من جميع الذين قبله».","xs":1},{"i":"t178","k":"b","e":"divided-kingdom","y":-872,"j":-917,"est":1,"t":"ملك أخآب (إسرائيل)","r":[["1Ki",16,28,16,30]],"s":-916.8898,"d":170,"pp":[["أخآب","ahab_113"]],"ll":["السامرة"],"x":"يملك أخآب بن عمري على إسرائيل في السامرة اثنتين وعشرين سنة. يتزوج إيزابل ابنة ملك الصيدونيين، ويعبد البعل ويقيم له مذبحًا في بيته الذي بناه في السامرة، ويعمل سواري. ويقول الكتاب إنه «ازداد في عمل الإغاظة للرب إله إسرائيل أكثر من جميع ملوك إسرائيل الذين كانوا قبله».","xs":1},{"i":"t181","k":"b","e":"divided-kingdom","y":-868,"j":-913,"est":1,"t":"ملك يهوشافاط (يهوذا)","r":[["1Ki",22,41,22,50]],"s":-912.8898,"d":173,"pp":[["يهوشافاط","jehoshaphat_808"]],"ll":["أورشليم"],"x":"يملك يهوشافاط بن آسا على يهوذا خمسًا وعشرين سنة، ويسير في طريق أبيه ولا يحيد عنه، إلا أن المرتفعات لم تُنزع. ويصالح ملك إسرائيل. ويحاول أن يبني سفنًا في عصيون جابر لتذهب إلى أوفير من أجل الذهب، لكنها تنكسر.","xs":1},{"i":"t182","k":"b","e":"divided-kingdom","y":-864,"j":-909,"est":1,"t":"خدمة إيليا النبي","r":[["1Ki",17,1,21,29],["2Ki",1,1,5,27]],"s":-908.8898,"d":171,"pp":[["إيليا","elijah_1131"]],"x":"تمتد خدمة إيليا التشبي من إعلان انقطاع المطر أمام أخآب إلى صعوده في العاصفة. فيها: الغربان تعوله عند نهر كريث، وأرملة صرفة يبارك الرب دقيقها وزيتها ويقوم ابنها، ثم النار على جبل الكرمل، والهروب إلى حوريب حيث يكلمه الرب بصوت منخفض خفيف، ودعوة أليشع، وحكم الرب على أخآب بسبب كرم نابوت، ثم مواجهة أخزيا الذي سأل بعل زبوب.","xs":1},{"i":"elijah-carmel","k":"b","e":"divided-kingdom","y":-860,"t":"إيليا على جبل الكرمل","j":-905,"r":[["1Ki",18,null,18,null]],"d":171,"l":"جبل الكرمل","x":"نبي واحد أمام ٤٥٠ من أنبياء البعل: إيليا يصلي فتنزل نار من السماء على مذبح مغمور بالماء، ويسقط الشعب على وجوههم: «الرب هو الله!». وتنتهي المجاعة بعد ثلاث سنين بالمطر.","s":-905,"pp":[["إيليا","elijah_1131"],["الله","god_1324"],["أخآب","ahab_113"],["عوبديا","obadiah_2215"],["البعل","baal_573"],["إيزابل","jezebel_1605"]],"ll":["جبل الكرمل","يزرعيل"],"kx":"في أيام أخآب انتشرت عبادة البعل في إسرائيل بتأثير إيزابل، فأقام الله إيليا، واسمه معناه «إلهي هو يهوه». وعلى جبل الكرمل أرسل الرب نارًا أكلت ذبيحة إيليا بينما بقي البعل صامتًا، فصرخ الشعب: «الرب هو الله». ثم جاء انكسار إيليا وهروبه، ولقاء الله معه «بصوت منخفض خفيف»، علامة على رعاية الله لخدامه. وصعوده إلى السماء دون موت، ونبوة ملاخي عن مجيئه (ملاخي ٤: ٥–٦)، ربطا اسمه بيوحنا المعمدان الذي جاء «بروح إيليا وقوته» (لوقا ١: ١٧)."},{"i":"elijah-whirlwind","k":"b","e":"divided-kingdom","y":-852,"t":"صعود إيليا في العاصفة","j":-896,"r":[["2Ki",2,null,2,null]],"d":174,"l":"عبر الأردن","x":"مركبة من نار وخيل من نار تفصل بين إيليا وأليشع، ويصعد إيليا في العاصفة إلى السماء دون أن يموت. ويرفع أليشع رداءه الذي سقط عنه، وينال نصيبين من روحه.","s":-896},{"i":"elisha-ministry","k":"b","e":"divided-kingdom","y":-852,"t":"خدمة أليشع","ye":-796,"j":-896,"r":[["2Ki",2,null,13,null]],"d":174,"l":"مملكة إسرائيل","x":"خدمة أليشع الطويلة مليئة بمعجزات الرحمة: زيت الأرملة يكثر، وابن الشونمية يقوم، ونعمان السرياني يطهر من البرص، والحديد يطفو على الماء.","s":-896,"pp":[["أليشع","elisha_1153"]]},{"i":"t184","k":"b","e":"divided-kingdom","y":-852,"j":-896,"est":1,"t":"ملك أخزيا (إسرائيل)","r":[["1Ki",22,51,22,53]],"s":-895.8898,"d":173,"pp":[["أخزيا","ahaziah_120"]],"ll":["السامرة"],"x":"يملك أخزيا بن أخآب على إسرائيل سنتين، ويعمل الشر ويعبد البعل مثل أبيه وأمه. يسقط من الكوة في عليته فيمرض، ويرسل يسأل بعل زبوب إله عقرون، فيقابل إيليا رسله: «أليس لأنه لا يوجد في إسرائيل إله؟». ويموت حسب كلام الرب.","xs":1},{"i":"t187","k":"b","e":"divided-kingdom","y":-852,"j":-896,"est":1,"t":"ملك يهورام بن أخآب (إسرائيل)","r":[["2Ki",3,1,3,6]],"s":-895.88,"d":175,"pp":[["يهورام","joram_804"]],"ll":["السامرة"],"x":"يملك يهورام بن أخآب على إسرائيل اثنتي عشرة سنة، ويعمل الشر لكن ليس مثل أبيه وأمه، إذ أزال تمثال البعل. ويعصى عليه ميشع ملك موآب، فيخرج للحرب ومعه يهوشافاط ملك يهوذا وملك أدوم، وحين يعطشون في البرية يعطيهم الرب ماء بكلمة أليشع.","xs":1},{"i":"t188","k":"b","e":"divided-kingdom","y":-848,"j":-892,"est":1,"t":"ملك يهورام بن يهوشافاط (يهوذا)","r":[["2Ki",1,17,8,24]],"s":-891.88,"d":174,"pp":[["يهورام","jehoram_803"]],"ll":["أورشليم"],"x":"يملك يهورام بن يهوشافاط على يهوذا ثماني سنين، ويسير في طريق ملوك إسرائيل لأن ابنة أخآب كانت زوجته. وفي أيامه يعصى أدوم ولبنة على يهوذا. ويضيف سفر الأخبار أنه قتل إخوته، وجاءته رسالة من إيليا، ومات بمرض شديد.","xs":1},{"i":"t189","k":"b","e":"divided-kingdom","y":-841,"j":-885,"est":1,"t":"ملك أخزيا بن يهورام (يهوذا)","r":[["2Ki",8,25,8,29]],"s":-884.8799,"d":177,"pp":[["أخزيا","ahaziah_121"]],"ll":["أورشليم"],"x":"يملك أخزيا بن يهورام على يهوذا سنة واحدة وهو ابن اثنتين وعشرين سنة، وأمه عثليا من بيت أخآب، فيسير في طريق بيت أخآب. يذهب مع يورام ملك إسرائيل لمحاربة حزائيل ملك أرام في راموت جلعاد، ثم ينزل ليزوره في يزرعيل، فيقتله ياهو هناك.","xs":1},{"i":"t190","k":"b","e":"divided-kingdom","y":-841,"j":-885,"est":1,"t":"ملك ياهو (إسرائيل)","r":[["2Ki",9,2,10,36]],"s":-884.8799,"d":177,"pp":[["ياهو","jehu_817"]],"ll":["السامرة"],"x":"يرسل أليشع واحدًا من بني الأنبياء فيمسح ياهو ملكًا على إسرائيل. يقتل ياهو يورام ملك إسرائيل وأخزيا ملك يهوذا، ثم إيزابل، ويبيد بيت أخآب وعبدة البعل. لكنه لم يحد عن عجلي الذهب. ملك ثماني وعشرين سنة، وفي أيامه ابتدأ حزائيل يقتطع من أرض إسرائيل.","xs":1},{"i":"t191","k":"b","e":"divided-kingdom","y":-841,"j":-885,"est":1,"t":"ملك عثليا (يهوذا)","r":[["2Ki",11,1,11,3]],"s":-884.8799,"d":178,"pp":[["عثليا","athaliah_359"]],"ll":["أورشليم"],"x":"حين ترى عثليا أم أخزيا أن ابنها قد مات، تقوم وتبيد كل النسل الملكي وتملك على يهوذا ست سنين. لكن يهوشبع أخت أخزيا تسرق يوآش الطفل وتخبئه في بيت الرب. وفي السنة السابعة يُخرجه يهوياداع الكاهن ويمسحه ملكًا، وتُقتل عثليا.","xs":1},{"i":"t193","k":"b","e":"divided-kingdom","y":-834,"j":-878,"est":1,"t":"ملك يهوآش بن أخزيا (يهوذا)","r":[["2Ki",11,21,12,21]],"s":-877.8799,"d":178,"pp":[["يوآش","joash_1632"]],"ll":["أورشليم"],"x":"يملك يهوآش وهو ابن سبع سنين، ويملك أربعين سنة في أورشليم، ويعمل المستقيم كل أيام يهوياداع الكاهن. يرمم بيت الرب بالفضة التي تُجمع في صندوق عند المذبح. ولما صعد حزائيل ملك أرام أعطاه الأقداس والذهب، وفي النهاية يفتن عليه عبيده ويقتلونه.","xs":1},{"i":"carthage-founded","k":"w","e":"divided-kingdom","y":-814,"t":"تأسيس قرطاج","l":"شمال أفريقيا (تونس)","x":"مستوطنون من صور، يقودهم بحسب التقليد الملكة ديدو (أليسار)، يؤسسون قرطاج على ساحل شمال أفريقيا. وستكبر هذه المستعمرة الفينيقية لتصير قوة عظمى في المتوسط تنازع روما.","s":-814},{"i":"t195","k":"b","e":"divided-kingdom","y":-812,"j":-856,"est":1,"t":"ملك يهوآحاز بن ياهو (إسرائيل)","r":[["2Ki",13,1,13,9]],"s":-855.8799,"d":179,"pp":[["يهوأحاز","jehoahaz_784"]],"ll":["السامرة"],"x":"يملك يهوآحاز بن ياهو على إسرائيل سبع عشرة سنة، ويعمل الشر. فيدفع الرب إسرائيل ليد حزائيل ملك أرام حتى لم يبقَ له إلا خمسون فارسًا وعشر مركبات وعشرة آلاف راجل. ويتضرع يهوآحاز إلى الرب فيعطيهم مخلّصًا.","xs":1},{"i":"t197","k":"b","e":"divided-kingdom","y":-795,"j":-839,"est":1,"t":"ملك يهوآش بن يهوآحاز (إسرائيل)","r":[["2Ki",13,10,13,13]],"s":-838.8799,"d":179,"pp":[["يوآش","joash_1633"]],"ll":["السامرة"],"x":"يملك يهوآش بن يهوآحاز على إسرائيل ست عشرة سنة، ويعمل الشر. ينزل إلى أليشع في مرضه الأخير ويبكي عليه، فيأمره أليشع أن يرمي السهم ثم يضرب الأرض، فيضرب ثلاث مرات فقط، فيقول له إنه سيضرب أرام ثلاث مرات. وفي أيامه انتصر على أمصيا ملك يهوذا.","xs":1},{"i":"t198","k":"b","e":"divided-kingdom","y":-794,"j":-838,"est":1,"t":"ملك أمصيا (يهوذا)","r":[["2Ki",14,1,14,22]],"s":-837.8799,"d":180,"pp":[["أمصيا","amaziah_214"]],"ll":["أورشليم"],"x":"يملك أمصيا بن يوآش على يهوذا تسعًا وعشرين سنة، ويعمل المستقيم لكن ليس مثل داود. يقتل قاتلي أبيه ولا يقتل أبناءهم حسب الشريعة، ويضرب أدوم في وادي الملح. ثم يتحدى يهوآش ملك إسرائيل فيُهزم ويُهدم جزء من سور أورشليم، وفي النهاية يُقتل في لخيش.","xs":1},{"i":"jonah-nineveh","k":"b","e":"divided-kingdom","y":-780,"t":"يونان ينادي في نينوى","j":-824,"r":[["Jon",1,null,4,null]],"d":179,"l":"نينوى، أشور","x":"النبي الهارب، الذي ابتلعه الحوت ثم قذفه، ينادي أخيرًا في عاصمة أعداء إسرائيل، فيتوب كل أهل نينوى بالمسوح. يونان يغتاظ، والرب يسأله: «أفلا أشفق أنا على نينوى المدينة العظيمة؟».","s":-824,"pp":[["يونان","jonah_1689"]]},{"i":"t199","k":"b","e":"divided-kingdom","y":-780,"j":-824,"est":1,"t":"ملك يربعام الثاني (إسرائيل)","r":[["2Ki",14,23,14,29]],"s":-823.8799,"d":180,"pp":[["يربعام","jeroboam_873"]],"ll":["السامرة"],"x":"يملك يربعام بن يهوآش على إسرائيل إحدى وأربعين سنة، ويعمل الشر. لكن الرب يستخدمه ليرد تخوم إسرائيل من مدخل حماة إلى بحر العربة، حسب كلام يونان بن أمتاي النبي، لأن الرب رأى ضيق إسرائيل المر جدًا. وفي أيامه تنبأ عاموس وهوشع.","xs":1},{"i":"first-olympics","k":"w","e":"divided-kingdom","y":-776,"t":"أول دورة أوليمبية مسجلة","l":"أولمبيا، اليونان","x":"مدن اليونان تجتمع في أولمبيا لمسابقات رياضية تكريمًا لزيوس: أول دورة في تقليد استمر كل أربع سنين أكثر من ألف سنة، وبه حسب اليونانيون تقويمهم.","s":-776},{"i":"t202","k":"b","e":"divided-kingdom","y":-775,"j":-819,"est":1,"t":"نبوات يوئيل","r":[["Joe",1,1,3,21]],"s":-818.71,"d":181,"pp":[["يوئيل","joel_1660"]],"x":"يصف يوئيل ضربة جراد مدمرة يراها علامة على «يوم الرب»، ويدعو الشعب: «مزقوا قلوبكم لا ثيابكم وارجعوا إلى الرب إلهكم». ثم يعد بالرد وبانسكاب روح الله على كل بشر، وهي النبوة التي استشهد بها بطرس يوم الخمسين.","xs":1},{"i":"t204","k":"b","e":"divided-kingdom","y":-765,"j":-809,"est":1,"t":"ملك عزريا، أي عزيا (يهوذا)","r":[["2Ki",15,1,15,7]],"s":-808.8798,"d":185,"pp":[["عزيا","uzziah_375"]],"ll":["أورشليم"],"x":"يملك عزريا، الذي يُدعى أيضًا عزيا، على يهوذا اثنتين وخمسين سنة، ويعمل المستقيم إلا أن المرتفعات لم تُنزع. ويضربه الرب بالبرص فيسكن في بيت منفرد حتى يوم موته، بينما يحكم ابنه يوثام. ويشرح سفر الأخبار أن ذلك كان لأنه دخل الهيكل ليوقد البخور.","xs":1},{"i":"amos-hosea","k":"b","e":"divided-kingdom","y":-760,"t":"عاموس وهوشع يتنبآن لإسرائيل","j":-784,"r":[["Amo",1,null,1,null],["Hos",1,null,1,null]],"d":182,"l":"مملكة إسرائيل","x":"راعٍ من تقوع يطالب بالعدل: «ليجر الحق كالمياه والبر كنهر دائم»، وهوشع بزواجه المجروح يصوّر محبة الله الأمينة لإسرائيل الخائن. آخر إنذارات للشمال قبل مجيء أشور.","s":-784,"pp":[["عاموس","amos_238"],["هوشع","hosea_1555"]]},{"i":"t208","k":"b","e":"divided-kingdom","y":-759,"j":-783,"est":1,"t":"ملك زكريا بن يربعام (إسرائيل)","r":[["2Ki",15,8,15,9]],"s":-782.8798,"d":185,"pp":[["زكريا","zachariah_2969"]],"ll":["السامرة"],"x":"يملك زكريا بن يربعام على إسرائيل ستة أشهر، ويعمل الشر. فيفتن عليه شلوم بن يابيش ويضربه أمام الشعب ويقتله. وبموته يتم كلام الرب لياهو بأن بنيه يجلسون على كرسي إسرائيل إلى الجيل الرابع.","xs":1},{"i":"rome-founded","k":"w","e":"divided-kingdom","y":-753,"t":"تأسيس روما بحسب الأسطورة","l":"إيطاليا","x":"بحسب التقليد الروماني يؤسس رومولوس المدينة على تل بالاتين في ٢١ أبريل ٧٥٣ ق.م. ومن هذه القرية على نهر التيبر ستنمو الإمبراطورية التي حكمت عالم العهد الجديد.","s":-753},{"i":"homer-epics","k":"w","e":"divided-kingdom","y":-750,"t":"تأليف الإلياذة والأوديسة","l":"أيونية، العالم اليوناني","x":"الملاحم الشفهية عن حرب طروادة وتجوال أوديسيوس تتشكل في القصيدتين المنسوبتين إلى هوميروس: النصوص المؤسسة للثقافة اليونانية والأدب الغربي.","s":-750},{"i":"t209","k":"b","e":"divided-kingdom","y":-747,"j":-771,"est":1,"t":"ملك شلوم (إسرائيل)","r":[["2Ki",15,10,15,10]],"s":-770.8798,"d":185,"pp":[["شلوم","shallum_2514"]],"ll":["السامرة"],"x":"يملك شلوم بن يابيش شهرًا واحدًا في السامرة، ثم يصعد منحيم بن جادي من ترصة ويقتله ويملك عوضًا عنه. فترة اضطراب كبير في المملكة الشمالية تقترب فيها النهاية.","xs":1},{"i":"t212","k":"b","e":"divided-kingdom","y":-747,"j":-771,"est":1,"t":"ملك منحيم (إسرائيل)","r":[["2Ki",15,17,15,22]],"s":-770.8798,"d":185,"pp":[["منحيم","menahem_1996"]],"ll":["السامرة"],"x":"يملك منحيم على إسرائيل عشر سنين، ويعمل الشر، ويعامل تفصح بقسوة شديدة. ويأتي فول ملك أشور على الأرض، فيعطيه منحيم ألف وزنة من الفضة جمعها من كل جبابرة البأس، لكي تثبت المملكة في يده.","xs":1},{"i":"t214","k":"b","e":"divided-kingdom","y":-742,"j":-760,"est":1,"t":"ملك فقحيا (إسرائيل)","r":[["2Ki",15,23,15,26]],"s":-759.8798,"d":185,"pp":[["فقحيا","pekahiah_2300"]],"ll":["السامرة"],"x":"يملك فقحيا بن منحيم على إسرائيل سنتين، ويعمل الشر. فيفتن عليه فقح بن رمليا قائده ومعه خمسون رجلًا من بني جلعاد، ويقتله في قصر بيت الملك في السامرة.","xs":1},{"i":"isaiah-called","k":"b","e":"divided-kingdom","y":-740,"t":"رؤيا إشعياء في الهيكل","j":-758,"r":[["Isa",6,null,6,null]],"d":187,"l":"أورشليم","x":"في سنة وفاة عزيا الملك يرى إشعياء السيد جالسًا على كرسي عالٍ ومرتفع، والسرافيم ينادون: «قدوس قدوس قدوس». وبعد أن تطهّره جمرة من المذبح يجيب: «هأنذا أرسلني»، فتبدأ خدمة طويلة غنية برجاء المسيا.","s":-758,"pp":[["الله","god_1324"]],"kx":"امتدت خدمة إشعياء في أيام أربعة ملوك ليهوذا، وتناولت الخطر القريب (غزو أشور) والبعيد (السبي البابلي والملكوت المسياني). ورؤياه لقداسة الله في الأصحاح السادس هي أساس دعوته. وفي سفره أوضح نبوات العهد القديم عن المسيح: العذراء تحبل (٧: ١٤)، ويُدعى اسمه عجيبًا مشيرًا رئيس السلام (٩: ٦–٧)، والعبد المتألم «مجروح لأجل معاصينا» (٥٢: ١٣–٥٣: ١٢)، والسماوات الجديدة والأرض الجديدة (٦٥: ١٧). ويوازن رسالته بين الدينونة على الخطية ورجاء العودة والعزاء."},{"i":"t216","k":"b","e":"divided-kingdom","y":-740,"j":-758,"est":1,"t":"ملك فقح (إسرائيل)","r":[["2Ki",15,27,15,31]],"s":-757.8798,"d":185,"pp":[["فقح","pekah_2299"]],"ll":["السامرة"],"x":"يملك فقح بن رمليا على إسرائيل عشرين سنة، ويعمل الشر. يتحالف مع رصين ملك أرام ضد آحاز ملك يهوذا، وهي خلفية نبوة عمانوئيل في إشعياء ٧. وفي أيامه يأخذ تغلث فلاسر ملك أشور مدنًا كثيرة وجلعاد والجليل وكل أرض نفتالي ويسبي سكانها، ثم يفتن عليه هوشع ويقتله.","xs":1},{"i":"t217","k":"b","e":"divided-kingdom","y":-740,"j":-758,"est":1,"t":"نبوات إشعياء","r":[["Isa",1,1,66,24]],"s":-757.77,"d":186,"pp":[["إشعياء","isaiah_617"]],"x":"يحمل سفر إشعياء في ستة وستين أصحاحًا رؤيا إشعياء بن آموص عن يهوذا وأورشليم في أيام عزيا ويوثام وآحاز وحزقيا. فيه دينونة على الخطية ونداءات للتوبة، ونبوات عن عمانوئيل والملك الآتي من جذع يسى، ثم أصحاحات التعزية: العبد المتألم، وكورش الذي يُذكر باسمه، والسماوات الجديدة والأرض الجديدة.","xs":1},{"i":"t219","k":"b","e":"divided-kingdom","y":-739,"j":-757,"est":1,"t":"ملك يوثام (يهوذا)","r":[["2Ki",15,32,15,38]],"s":-756.8798,"d":185,"pp":[["يوثام","jotham_1735"]],"ll":["أورشليم"],"x":"يملك يوثام بن عزيا على يهوذا ست عشرة سنة، ويعمل المستقيم مثل أبيه، إلا أن المرتفعات لم تُنزع. يبني الباب الأعلى لبيت الرب. وفي أيامه يبدأ رصين ملك أرام وفقح بن رمليا يهاجمان يهوذا.","xs":1},{"i":"t220","k":"b","e":"divided-kingdom","y":-735,"j":-753,"est":1,"t":"نبوات ميخا","r":[["Mic",1,1,7,20]],"s":-752.67,"d":187,"pp":[["ميخا","micah_2053"]],"x":"ميخا المورشتي يتنبأ في أيام يوثام وآحاز وحزقيا عن السامرة وأورشليم معًا. يدين ظلم الأغنياء والقادة والأنبياء الكذبة، ويتنبأ عن الحاكم الذي يخرج من بيت لحم أفراتة (٥: ٢). ومن أشهر أقواله: «ماذا يطلبه منك الرب إلا أن تصنع الحق وتحب الرحمة وتسلك متواضعًا مع إلهك» (٦: ٨).","xs":1},{"i":"fall-of-samaria","k":"b","e":"divided-kingdom","y":-722,"t":"أشور تُسقط مملكة إسرائيل","j":-720,"r":[["2Ki",17,null,17,null]],"d":191,"l":"السامرة","x":"بعد حصار ثلاث سنين تسقط السامرة في يد أشور، ويُسبى الأسباط العشرة ويُشتتون في الإمبراطورية، والنص يؤكد أن ذلك «لأنهم لم يسمعوا لصوت الرب إلههم».","s":-720,"pp":[["الله","god_1324"],["يعقوب","israel_682"],["يهوذا","judah_1751"],["هوشع","hoshea_1559"],["يربعام","jeroboam_872"]],"ll":["أشور","السامرة","مصر","إسرائيل"],"kx":"بعد نحو قرنين من الارتداد وتقلّب الأسر الحاكمة، تسقط مملكة إسرائيل في يد أشور بعد حصار السامرة ثلاث سنين. سبى الأشوريون السكان وأسكنوا في الأرض شعوبًا أخرى، فاختلطت العبادة، ومن هذا الخليط جاء السامريون الذين نقابلهم في الأناجيل. ويقول الكتاب بوضوح إن السبي حدث «لأن بني إسرائيل أخطأوا إلى الرب إلههم» (الملوك الثاني ١٧: ٧). كان الأنبياء قد أنذروا أجيالًا، والآن تحققت الدينونة، لكن بقية من الأسباط الشمالية انضمت إلى يهوذا، ويخاطب يعقوب في رسالته «الاثني عشر سبطًا»."},{"i":"t221","k":"b","e":"divided-kingdom","y":-717,"j":-741,"est":1,"t":"ملك آحاز (يهوذا)","r":[["2Ki",16,1,16,20]],"s":-740.8798,"d":188,"pp":[["آحاز","ahaz_118"]],"ll":["أورشليم"],"x":"يملك آحاز بن يوثام على يهوذا ست عشرة سنة، ولا يعمل المستقيم بل يُجيز ابنه في النار. ولما حاصره رصين وفقح أرسل فضة بيت الرب وذهبه إلى تغلث فلاسر ملك أشور ليخلّصه. ثم رأى مذبحًا في دمشق فعمل مثله ووضعه في بيت الرب.","xs":1},{"i":"t224","k":"b","e":"divided-kingdom","y":-705,"j":-729,"est":1,"t":"ملك هوشع (إسرائيل)","r":[["2Ki",17,1,17,4]],"s":-728.8798,"d":191,"pp":[["هوشع","hoshea_1559"]],"ll":["السامرة"],"x":"يملك هوشع بن أيلة على إسرائيل تسع سنين، ويعمل الشر لكن ليس كملوك إسرائيل الذين قبله. يصير عبدًا لشلمنأصر ملك أشور، ثم يتآمر مع سوا ملك مصر ويمنع الجزية، فيقبض عليه ملك أشور ويحاصر السامرة ثلاث سنين حتى تسقط.","xs":1},{"i":"sennacherib-jerusalem","k":"b","e":"divided-kingdom","y":-701,"t":"خلاص أورشليم من سنحاريب","j":-725,"r":[["2Ki",18,null,19,null],["Isa",36,null,37,null]],"d":197,"l":"أورشليم","x":"جيش سنحاريب، بعد أن أخذ مدن يهوذا الحصينة، يحاصر أورشليم ويعيّر إلهها. حزقيا ينشر الرسالة أمام الرب، وفي تلك الليلة يضرب ملاك الرب جيش أشور فيرجع سنحاريب.","s":-725,"pp":[["حزقيا","hezekiah_1512"]],"ll":["أورشليم"],"kx":"قاد حزقيا إصلاحًا شاملًا: أزال المرتفعات وكسر التماثيل وأعاد العبادة في الهيكل. ولما حاصرت أشور أورشليم صلّى ونشر رسالة التهديد أمام الرب، وتنبأ إشعياء بالخلاص، وفي تلك الليلة ضرب ملاك الرب ١٨٥ ألفًا من جيش أشور فرجع سنحاريب (الملوك الثاني ١٩: ٣٥). لكن حزقيا أظهر بعد ذلك خزائنه لرسل ملك بابل، فتنبأ إشعياء بأن كل شيء سيُحمل يومًا إلى بابل. حياته تجمع بركة الأمانة وعاقبة الكبرياء."},{"i":"t228","k":"b","e":"divided-kingdom","y":-698,"j":-696,"est":1,"t":"ملك منسى (يهوذا)","r":[["2Ki",21,1,21,18]],"s":-695.8798,"d":207,"pp":[["منسى","manasseh_1930"]],"ll":["أورشليم"],"x":"يملك منسى وهو ابن اثنتي عشرة سنة، ويملك خمسًا وخمسين سنة، أطول ملك في يهوذا. يعيد بناء المرتفعات ويقيم مذابح للبعل ولجند السماء حتى في بيت الرب، ويُجيز ابنه في النار، ويسفك دمًا بريئًا كثيرًا. ويقول سفر الملوك إن خراب يهوذا تقرر بسبب خطاياه، ويذكر سفر الأخبار أنه أُخذ أسيرًا إلى بابل ثم تواضع وتاب.","xs":1},{"i":"ashurbanipal-library","k":"w","e":"divided-kingdom","y":-650,"t":"مكتبة آشور بانيبال في نينوى","l":"نينوى، أشور","x":"آخر ملوك أشور العظام يجمع أكثر من ثلاثين ألف لوح طيني من ملاحم وعرافة وعلوم وسجلات دولة في أعظم مكتبة في العالم القديم، ومنها جاء معظم أدب بلاد الرافدين الذي وصل إلينا.","s":-650},{"i":"t229","k":"b","e":"divided-kingdom","y":-645,"j":-662,"est":1,"t":"نبوات ناحوم","r":[["Nah",1,1,3,19]],"s":-661.66,"d":192,"pp":[["ناحوم","nahum_2145"]],"x":"يحمل سفر ناحوم وحيًا على نينوى عاصمة أشور، التي سبق أن تابت في أيام يونان ثم رجعت إلى قسوتها. يبدأ بإعلان أن «الرب صالح، حصن في يوم الضيق»، ثم يصف سقوط نينوى. وقد سقطت فعلًا نحو ٦١٢ ق.م.","xs":1},{"i":"jeremiah-called","k":"b","e":"divided-kingdom","y":-627,"t":"بداية خدمة إرميا","j":-628,"r":[["Jer",1,null,1,null]],"d":211,"l":"أورشليم","x":"إرميا، الذي جعله الله «نبيًا للشعوب» قبل أن يولد، يبدأ وهو شاب أربعين سنة من النبوة الباكية: يهوذا سيسقط في يد بابل، لكن الله يعد بعهد جديد مكتوب على القلب.","s":-628,"pp":[["الله","god_1324"],["إرميا","jeremiah_853"],["يوشيا","josiah_1730"]],"ll":["أورشليم"],"kx":"امتدت خدمة إرميا نحو أربعين سنة في العقود الأخيرة ليهوذا، يعلن أن دينونة بابل آتية لا محالة ويدعو إلى التوبة. واتُّهم بالخيانة لأنه دعا إلى الخضوع لبابل، وسُجن وسُخر منه وعاش وحيدًا، فصار «النبي الباكي» وصورة للمسيح المرفوض من خاصته. لكنه تنبأ أيضًا بالعهد الجديد الذي يكتب فيه الله شريعته على القلوب لا على ألواح الحجر (إرميا ٣١: ٣١–٣٤)، وهي النبوة التي يقتبسها سفر العبرانيين كاملة (عبرانيين ٨). وتُظهر حياته ثمن الأمانة النبوية."},{"i":"t234","k":"b","e":"divided-kingdom","y":-626,"j":-627,"est":1,"t":"نبوات إرميا","r":[["Jer",1,1,52,34]],"s":-626.76,"d":211,"pp":[["إرميا","jeremiah_853"]],"x":"يحمل سفر إرميا في اثنين وخمسين أصحاحًا خدمة إرميا بن حلقيا من السنة الثالثة عشرة ليوشيا إلى سبي أورشليم. فيه دعوات للتوبة، ورثاء، ومواجهات مع الملوك والأنبياء الكذبة، وسجن النبي، ونبوة السبعين سنة، ووعد العهد الجديد، وينتهي بسقوط أورشليم.","xs":1},{"i":"t231","k":"b","e":"divided-kingdom","y":-624,"j":-641,"est":1,"t":"ملك آمون (يهوذا)","r":[["2Ki",21,19,21,26]],"s":-640.8798,"d":207,"pp":[["آمون","amon_236"]],"ll":["أورشليم"],"x":"يملك آمون بن منسى على يهوذا سنتين، ويعمل الشر كما عمل أبوه، ويعبد الأصنام. فيفتن عليه عبيده ويقتلونه في بيته، فيقتل شعب الأرض الفاتنين ويملّكون يوشيا ابنه عوضًا عنه.","xs":1},{"i":"josiah-reform","k":"b","e":"divided-kingdom","y":-622,"t":"إصلاح يوشيا وسفر الشريعة","j":-639,"r":[["2Ki",22,null,23,null]],"d":210,"l":"أورشليم","x":"أثناء ترميم الهيكل يوجد سفر الشريعة. يسمعه يوشيا الملك فيمزق ثيابه، ويبدأ أعظم إصلاح في يهوذا: يحطم الأوثان ويعمل فصحًا لم يُعمل مثله منذ أيام القضاة.","s":-639,"pp":[["يوشيا","josiah_1730"]],"ll":["أورشليم"],"kx":"يملك يوشيا وهو ابن ثماني سنين، ويقود أشمل إصلاح في تاريخ يهوذا. يوجد سفر الشريعة أثناء ترميم الهيكل (ويرجّح كثيرون أنه سفر التثنية أو جزء منه)، فيجدد الشعب العهد، ويهدم يوشيا مذابح الأوثان في كل الأرض، ويعمل فصحًا لم يُعمل مثله منذ أيام القضاة. ومع ذلك يعلن الكتاب أن الدينونة قادمة بسبب خطايا منسى المتراكمة (الملوك الثاني ٢٣: ٢٦). ويموت يوشيا في مجدو أمام فرعون نخو. لكن الكتاب يشهد له: «لم يكن قبله ملك مثله... ولا بعده قام مثله» (٢٣: ٢٥)."},{"i":"t235","k":"b","e":"divided-kingdom","y":-612,"j":-609,"est":1,"t":"نبوات صفنيا","r":[["Zep",1,1,3,20]],"s":-608.64,"d":210,"pp":[["صفنيا","zephaniah_3040"]],"x":"صفنيا يتنبأ في أيام يوشيا، ويعلن قرب «يوم الرب العظيم» يوم سخط وضيق على يهوذا وعلى الأمم. لكنه يدعو المتضعين إلى طلب الرب، ويختم بوعد عجيب: «الرب إلهك في وسطك جبار، يخلّص. يبتهج بك فرحًا» (٣: ١٧).","xs":1},{"i":"t236","k":"b","e":"divided-kingdom","y":-611,"j":-608,"est":1,"t":"موت يوشيا في مجدو","r":[["2Ki",23,29,23,29]],"s":-607.8798,"d":214,"pp":[["يوشيا","josiah_1730"],["فرعون نخو","pharaoh-nechoh_2337"]],"ll":["مجدو"],"x":"يصعد فرعون نخو ملك مصر نحو نهر الفرات لمساعدة ملك أشور، فيخرج يوشيا لملاقاته في مجدو فيُقتل هناك. ويحمله عبيده في مركبة ميتًا إلى أورشليم ويُدفن في قبره، وينوح عليه إرميا وكل يهوذا.","xs":1},{"i":"t237","k":"b","e":"divided-kingdom","y":-611,"j":-608,"est":1,"t":"ملك يهوآحاز بن يوشيا (يهوذا)","r":[["2Ki",23,31,23,35]],"s":-607.8798,"d":214,"pp":[["يهوآحاز","jehoahaz_2516"]],"ll":["أورشليم"],"x":"يملك يهوآحاز بن يوشيا ثلاثة أشهر فقط، ويعمل الشر. فيقيده فرعون نخو في ربلة ويأخذه إلى مصر حيث يموت، ويفرض على الأرض جزية، ويملّك ألياقيم أخاه ويغيّر اسمه إلى يهوياقيم. ويسميه إرميا «شلوم» (إرميا ٢٢: ١١).","xs":1},{"i":"t238","k":"b","e":"divided-kingdom","y":-611,"j":-608,"est":1,"t":"ملك يهوياقيم (يهوذا)","r":[["2Ki",23,36,24,7]],"s":-607.8798,"d":214,"pp":[["يهوياقيم","jehoiakim_1085"]],"ll":["أورشليم"],"x":"يملك يهوياقيم على يهوذا إحدى عشرة سنة، ويعمل الشر، ويفرض الضرائب على الشعب ليدفع لفرعون. ثم يصعد نبوخذنصر ملك بابل فيصير يهوياقيم عبدًا له ثلاث سنين ثم يتمرد، فيرسل الرب عليه غزاة من الكلدانيين والأراميين والموآبيين وبني عمون.","xs":1},{"i":"t239","k":"b","e":"divided-kingdom","y":-609,"j":-606,"est":1,"t":"نبوات حبقوق","r":[["Hab",1,1,3,19]],"s":-605.65,"d":212,"pp":[["حبقوق","habakkuk_1334"]],"x":"حبقوق يسأل الله بجرأة: لماذا يسكت على الظلم في يهوذا؟ ولماذا يستخدم الكلدانيين الأشر منهم؟ ويجيبه الرب: «البار بإيمانه يحيا» (٢: ٤)، وهي الآية التي بنى عليها بولس تعليم التبرير. ويختم بصلاة إيمان: «فمع أنه لا يزهر التين... فإني أبتهج بالرب».","xs":1},{"i":"t240","k":"b","e":"divided-kingdom","y":-608,"j":-605,"est":1,"t":"نبوات دانيال","r":[["Dan",1,1,12,13]],"s":-604.73,"d":216,"pp":[["دانيآل","daniel_975"]],"x":"يجمع سفر دانيال في اثني عشر أصحاحًا قصص أمانة دانيال وأصحابه في بلاط بابل وفارس، ورؤى عن ممالك العالم المتعاقبة. فيه تمثال نبوخذنصر، وأتون النار، وجب الأسود، ورؤيا «مثل ابن إنسان» الآتي مع سحب السماء، ونبوة السبعين أسبوعًا. وجزء منه مكتوب بالأرامية لا بالعبرية (٢: ٤–٧: ٢٨).","xs":1},{"i":"first-deportation","k":"b","e":"divided-kingdom","y":-605,"t":"سبي دانيال إلى بابل","j":-602,"r":[["Dan",1,null,1,null]],"d":216,"l":"أورشليم ← بابل","x":"بعد أن يهزم نبوخذنصر مصر في كركميش، يأخذ أول المسبيين من أورشليم، ومنهم دانيال وأصحابه الثلاثة، شبان من النبلاء سيخدمون في قصور الإمبراطوريات دون أن يساوموا على إيمانهم.","s":-602,"pp":[["دانيآل","daniel_975"],["شدرخ","shadrach_1398"],["ميشخ","meshach_2092"],["عزريا","azariah_545"],["الله","god_1324"],["يهوياقيم","jehoiakim_1085"]],"kx":"دانيال من أول المسبيين، وظل أمينًا لعهد الله وسط بيئة وثنية. وتفسيره لأحلام نبوخذنصر وللكتابة في وليمة بيلشاصر يعلن أن الله متسلط على ممالك الأمم. ونبوة السبعين أسبوعًا (دانيال ٩) صارت إطارًا زمنيًا لانتظار المسيا، ورؤاه عن الحيوانات و«القديم الأيام» و«مثل ابن إنسان» أثّرت في سفر الرؤيا، ولقب «ابن الإنسان» هو اللقب الذي استخدمه يسوع لنفسه. ونجاة أصحابه من الأتون ونجاته من جب الأسود تؤكد أن الله يحفظ الأمناء، وحياته مثال لمن يخدم في مجتمع غريب دون أن يساوم على إيمانه."},{"i":"nebuchadnezzar-babylon","k":"w","e":"divided-kingdom","y":-600,"t":"نبوخذنصر الثاني يعيد بناء بابل","l":"بابل","x":"فاتح أورشليم يجعل بابل أعجوبة عصره: بوابة عشتار بأسودها وتنانينها الزرقاء المزججة، وأسوار مزدوجة ضخمة، وبحسب التقليد الحدائق المعلقة. «أليست هذه بابل العظيمة التي بنيتها؟».","s":-600},{"i":"second-deportation","k":"b","e":"divided-kingdom","y":-597,"t":"سبي حزقيال في السبي الثاني","j":-598,"r":[["2Ki",24,null,24,null],["Eze",1,null,1,null]],"d":217,"l":"أورشليم ← بابل","x":"أورشليم تستسلم، ويُسبى يهوياكين الملك وخزائن بيت الرب وعشرة آلاف أسير، ومنهم الكاهن حزقيال، إلى بابل، حيث يرى عند نهر خابور رؤى الله.","s":-598,"pp":[["الله","god_1324"],["يهوياقيم","jehoiakim_1085"],["يهوياكين","jehoiachin_791"],["نبوخذنصر","nebuchadnezzar_2167"],["صدقيا","zedekiah_1950"]],"ll":["بابل","أورشليم"]},{"i":"t241","k":"b","e":"divided-kingdom","y":-596,"j":-597,"est":1,"t":"ملك يهوياكين (يهوذا)","r":[["2Ki",24,8,24,17]],"s":-596.8798,"d":217,"pp":[["يهوياكين","jehoiachin_791"]],"ll":["أورشليم"],"x":"يملك يهوياكين وهو ابن ثماني عشرة سنة، ثلاثة أشهر فقط. يحاصر نبوخذنصر أورشليم فيخرج يهوياكين إليه مع أمه وعبيده، فيُسبى إلى بابل مع كنوز بيت الرب وعشرة آلاف من الرؤساء والجبابرة والصناع، ويملّك ملك بابل متنيا عمه ويغير اسمه إلى صدقيا.","xs":1},{"i":"t242","k":"b","e":"divided-kingdom","y":-595,"j":-596,"est":1,"t":"ملك صدقيا (يهوذا)","r":[["2Ki",24,18,25,7]],"s":-595.8798,"d":217,"pp":[["صدقيا","zedekiah_1950"]],"ll":["أورشليم"],"x":"يملك صدقيا على يهوذا إحدى عشرة سنة، ويعمل الشر، ويتمرد على ملك بابل. فيأتي نبوخذنصر ويحاصر أورشليم حتى يشتد الجوع، ثم تُثغر المدينة. يهرب صدقيا ليلًا فيُمسك في عربات أريحا، ويُذبح بنوه أمام عينيه، ثم تُقلع عيناه ويُقيد بسلسلتين ويؤخذ إلى بابل.","xs":1},{"i":"solon-athens","k":"w","e":"divided-kingdom","y":-594,"t":"إصلاحات صولون في أثينا","l":"أثينا، اليونان","x":"المشرّع صولون يلغي استعباد المدينين ويعيد تنظيم مجتمع أثينا، واضعًا أساسًا دستوريًا تطور بعد قرن إلى أول ديمقراطية في العالم.","s":-594},{"i":"t243","k":"b","e":"divided-kingdom","y":-591,"j":-592,"est":1,"t":"نبوات حزقيال","r":[["Eze",1,1,48,35]],"s":-591.74,"d":220,"pp":[["حزقيال","ezekiel_1237"]],"x":"يبدأ سفر حزقيال برؤيا مجد الله على نهر خابور في السنة الخامسة لسبي يهوياكين. وفي ثمانية وأربعين أصحاحًا: دعوة النبي رقيبًا، وأعمال رمزية، ومجد الرب يفارق الهيكل، ونبوات على الأمم. وبعد سقوط أورشليم تأتي وعود الرجاء: القلب الجديد، والعظام اليابسة، والهيكل الجديد، واسم المدينة «يهوه شمّه» أي الرب هناك.","xs":1},{"i":"fall-of-jerusalem","k":"b","e":"divided-kingdom","y":-586,"t":"سقوط أورشليم وخراب الهيكل","j":-587,"r":[["2Ki",25,null,25,null],["Lam",1,null,1,null]],"d":231,"l":"أورشليم","x":"بعد حصار طويل تُثغر بابل سور أورشليم وتحرق هيكل سليمان وتسبي الشعب. يُعمى الملك من نسل داود ويُقيد بالسلاسل، وإرميا يرثي الخراب، ومع ذلك يقول: «عظيمة أمانتك».","s":-587,"pp":[["جدليا","gedaliah_1287"],["نبوخذنصر","nebuchadnezzar_2167"],["نبوزرادان","nebuzar-adan_2169"],["الله","god_1324"],["صدقيا","zedekiah_1950"],["إسماعيل","ishmael_631"]],"ll":["بابل","أورشليم","ربلة","المصفاة"],"kx":"بعد حصار طويل يُثغر جيش نبوخذنصر سور أورشليم، ويحرق الهيكل، ويسبي الشعب إلى بابل. كان خراب بيت الله تحقيقًا للعنات العهد التي أنذر بها موسى، وتصديقًا لكلام إشعياء وإرميا وغيرهما. وسفر المراثي يعبّر عن هول الكارثة شعرًا. لكن السبي لم يكن رفضًا نهائيًا، بل تأديبًا طهّر الشعب من عبادة الأوثان. ويربط سفر الأخبار السبعين سنة (إرميا ٢٥: ١١–١٢) بسنوات السبت التي لم تُحفظ (أخبار الأيام الثاني ٣٦: ٢١). وصار السبي جرحًا كبيرًا في ذاكرة الشعب، وخلفية لرجاء الرد المسياني."},{"i":"babylonian-exile","k":"b","e":"exile-return","y":-586,"t":"يهوذا في السبي البابلي","ye":-538,"r":[["Psa",137,null,137,null],["Jer",29,null,29,null]],"d":250,"l":"بابل","x":"«على أنهار بابل هناك جلسنا، بكينا أيضًا». لكن السبي صار نارًا مطهِّرة: تثبتت العبادة في المجامع، وعَزّ الكتاب على الشعب، ورسالة إرميا توصي المسبيين أن يطلبوا سلام المدينة، لأن أفكار الله نحوهم «أفكار سلام لا شر، لأعطيكم آخرة ورجاء».","s":-586,"pp":[["الله","god_1324"]],"ll":["أورشليم","بابل","صهيون"]},{"i":"t244","k":"b","e":"exile-return","y":-583,"j":-584,"est":1,"t":"نبوات عوبديا","r":[["Oba",1,1,1,21]],"s":-583.69,"d":241,"pp":[["عوبديا","obadiah_2226"]],"x":"عوبديا أقصر أسفار العهد القديم، أصحاح واحد. وحي على أدوم، نسل عيسو، الذي شمت بأورشليم ووقف مع أعدائها يوم خرابها. يعلن أن يوم الرب قريب على كل الأمم، وأن «كما فعلت يُفعل بك»، ويختم بأن «الملك للرب».","xs":1},{"i":"fiery-furnace","k":"b","e":"exile-return","y":-580,"t":"أتون النار","j":-579,"r":[["Dan",3,null,3,null]],"d":245,"l":"بابل","x":"شدرخ وميشخ وعبدنغو يرفضون السجود لتمثال الذهب الذي أقامه نبوخذنصر، فيُلقون في أتون النار المتقدة، وهناك رابع يتمشى معهم، ويخرجون ولم تأتِ عليهم رائحة النار.","s":-579,"pp":[["نبوخذنصر","nebuchadnezzar_2167"],["شدرخ","shadrach_1398"],["ميشخ","meshach_2092"],["الله","god_1324"]],"ll":["بابل"]},{"i":"cyrus-conquers-babylon","k":"w","e":"exile-return","y":-539,"t":"كورش الكبير يفتح بابل","l":"بابل","x":"فارس تأخذ بابل تقريبًا دون معركة، ويؤسس كورش أكبر إمبراطورية عرفها العالم حتى ذلك الوقت. وسياسته في إرجاع الشعوب المسبية ومقادسها، المدونة على «أسطوانة كورش»، غيرت تاريخ اليهود.","s":-539},{"i":"writing-on-wall","k":"b","e":"exile-return","y":-539,"t":"وليمة بيلشاصر والكتابة على الحائط","j":-537,"r":[["Dan",5,null,5,null]],"d":251,"l":"بابل","x":"بينما يشرب بيلشاصر بآنية الهيكل، تظهر أصابع يد إنسان وتكتب على حائط القصر: «منا منا تقيل وفرسين». دانيال يقرأ الحكم: وُزنت بالموازين فوُجدت ناقصًا. وفي تلك الليلة تسقط بابل في يد فارس.","s":-537,"pp":[["بيلشاصر","belshazzar_437"],["الله","god_1324"],["دانيآل","daniel_975"],["نبوخذنصر","nebuchadnezzar_2167"]],"ll":["أورشليم"]},{"i":"lions-den","k":"b","e":"exile-return","y":-538,"t":"دانيال في جب الأسود","j":-537,"r":[["Dan",6,null,6,null]],"d":251,"l":"بابل","x":"الوزراء الحاسدون يوقعون بدانيال الشيخ، فيستمر في الصلاة نحو أورشليم ويُلقى في جب الأسود. الله يسد أفواه الأسود، وداريوس يأمر أن يرتعد الجميع أمام إله دانيال الحي.","s":-537,"pp":[["دانيآل","daniel_975"],["الله","god_1324"],["داريوس","darius_980"]]},{"i":"cyrus-decree","k":"b","e":"exile-return","y":-538,"t":"أمر كورش والرجوع الأول","j":-521,"r":[["Ezr",1,null,2,null]],"d":255,"l":"بابل ← أورشليم","x":"كما سمّاه إشعياء قبلها بأجيال، يأمر كورش ملك فارس أن يرجع المسبيون ويبنوا بيت الرب. نحو خمسين ألفًا يرجعون إلى أورشليم مع زربابل، حاملين آنية الهيكل إلى بيتها.","s":-521,"pp":[["الله","god_1324"],["كورش","cyrus_968"],["زربابل","zerubbabel_3054"],["نبوخذنصر","nebuchadnezzar_2167"],["سليمان","solomon_2762"]],"ll":["أورشليم","فارس"],"kx":"يفتح كورش ملك فارس بابل ويصدر أمرًا يسمح لليهود بالرجوع وبناء الهيكل، تحقيقًا لنبوة إشعياء التي ذكرته باسمه قبلها بأكثر من قرن (إشعياء ٤٤: ٢٨؛ ٤٥: ١). ويقود زربابل الرجوع الأول، نحو خمسين ألفًا، بينما بقي أكثر الشعب في بابل. يُظهر الرجوع أمانة الله لعهده، وأن السبي لم يكن رفضًا نهائيًا. والهيكل المبني من جديد، وإن كان أقل فخامة، حفظ العبادة والذبائح حتى مجيء المسيا."},{"i":"temple-foundation","k":"b","e":"exile-return","y":-536,"t":"وضع أساس الهيكل الثاني","j":-521,"r":[["Ezr",3,null,3,null]],"d":256,"l":"أورشليم","x":"بالأبواق والصنوج يضع الراجعون أساس الهيكل. الشباب يهتفون فرحًا، والشيوخ الذين رأوا البيت الأول يبكون بصوت عظيم، والصوت يُسمع إلى بعيد.","s":-521,"pp":[["الله","god_1324"],["يهوشع","joshua_893"],["يهوصاداق","josedech_815"],["زربابل","zerubbabel_3054"],["شألتئيل","shealtiel_2456"]],"ll":["أورشليم"]},{"i":"buddha","k":"w","e":"exile-return","y":-528,"t":"سيدهارتا غوتاما (بوذا)","l":"شمال الهند","x":"بحسب الحساب التقليدي يبدأ سيدهارتا غوتاما تعليمه الذي صار البوذية، في الوقت الذي كان فيه مسبيو يهوذا جالسين على أنهار بابل.","s":-528},{"i":"haggai-zechariah","k":"b","e":"exile-return","y":-520,"t":"حجي وزكريا يشجعان البنائين","j":-519,"r":[["Hag",1,null,2,null],["Zec",1,null,8,null]],"d":256,"l":"أورشليم","x":"بعد سنين توقف فيها العمل، يوقظ نبيّان الشعب الفاتر: «تشددوا يا جميع شعب الأرض واعملوا، فإني معكم». ورؤى زكريا تعد بملك آتٍ وديع راكب على حمار.","s":-519,"pp":[["زكريا","zechariah_3016"]]},{"i":"second-temple-completed","k":"b","e":"exile-return","y":-516,"t":"اكتمال الهيكل الثاني","j":-514,"r":[["Ezr",6,null,6,null]],"d":259,"l":"أورشليم","x":"بعد نحو سبعين سنة من حريق هيكل سليمان، يكتمل بيت الله الجديد ويُدشَّن بفرح ويُعمل الفصح. كان أقل فخامة من الأول، لكنه ظل قائمًا، بعد أن وسّعه هيرودس، حتى سنة ٧٠ م.","s":-514,"pp":[["الله","god_1324"],["داريوس","darius_978"],["كورش","cyrus_968"],["تتناي","tatnai_2831"],["شتربوزناي","shethar-boznai_2674"],["يعقوب","israel_682"]],"ll":["أورشليم"],"kx":"يبدأ الراجعون بناء الهيكل وسط مقاومة الشعوب المحيطة، ثم يتوقف العمل نحو ست عشرة سنة بسبب الفتور والمقاومة. فيقوم حجي وزكريا يوبخان الشعب لأنهم اهتموا ببيوتهم وتركوا بيت الله، ويشجعانهم على الإكمال. وحين اكتمل كان أقل بهاء من هيكل سليمان حتى بكى الشيوخ، لكن حجي تنبأ: «مجد هذا البيت الأخير يكون أعظم من مجد الأول» (حجي ٢: ٩)، ويرى المسيحيون تحقيق ذلك في دخول المسيح نفسه إلى هذا الهيكل."},{"i":"roman-republic","k":"w","e":"exile-return","y":-509,"t":"قيام الجمهورية الرومانية","l":"روما","x":"روما تطرد آخر ملوكها تاركوينيوس المتكبر وتتعهد ألا يحكمها رجل واحد بعد، فتنشئ القناصل ومجلس الشيوخ ومؤسسات الجمهورية التي قادت صعود روما.","s":-509},{"i":"confucius","k":"w","e":"exile-return","y":-500,"t":"كونفوشيوس يعلّم في الصين","l":"لو، الصين","x":"وسط تفكك حكم أسرة تشو يعلّم كونفوشيوس الفضيلة وبر الوالدين وصحة العلاقات: فلسفة شكلت حضارة شرق آسيا ألفين وخمس مئة سنة.","s":-500},{"i":"marathon","k":"w","e":"exile-return","y":-490,"t":"معركة ماراثون","l":"ماراثون، اليونان","x":"الأثينيون، وهم أقل عددًا، يهزمون أول غزو فارسي لليونان. وأسطورة العدّاء الذي حمل خبر النصر إلى أثينا أعطت اسمها للسباق الحديث.","s":-490},{"i":"thermopylae-salamis","k":"w","e":"exile-return","y":-480,"t":"ترموبيلاي وسلاميس","l":"اليونان","x":"أحشويروش ملك سفر أستير (زركسيس) يغزو اليونان بجيش ضخم. يموت ليونيداس وثلاث مئة إسبرطي في ممر ترموبيلاي، لكن الأسطول اليوناني يحطم فارس في سلاميس ويقلب مسار الحرب.","s":-480},{"i":"esther-queen","k":"b","e":"exile-return","y":-479,"t":"أستير ملكة على فارس","j":-460,"r":[["Est",2,null,2,null]],"d":261,"l":"شوشن، فارس","x":"يتيمة يهودية رباها ابن عمها مردخاي يختارها أحشويروش (زركسيس) ملكة دون أن تكشف أصلها، فتصير في القصر «لوقت مثل هذا».","s":-460,"pp":[["أستير","esther_1343"],["مردخاي","mordecai_2107"],["أحشويروش","ahasuerus_117"],["وشتي","vashti_2937"],["هيجاي","hegai_1477"]],"ll":["شوشن"]},{"i":"purim","k":"b","e":"exile-return","y":-473,"t":"فشل مؤامرة هامان وعيد الفوريم","j":-452,"r":[["Est",3,null,9,null]],"d":263,"l":"مملكة فارس","x":"هامان يدبر أمرًا بإهلاك كل اليهود في المملكة. أستير تخاطر بحياتها وتدخل إلى الملك دون أن تُدعى، فتنقلب المؤامرة ويُصلب هامان على الخشبة التي أعدها، ويُحتفل بالخلاص كل سنة في عيد الفوريم.","s":-452,"pp":[["هامان","haman_1360"],["مردخاي","mordecai_2107"],["أستير","esther_1343"],["أحشويروش","ahasuerus_117"],["همداثا","hammedatha_1362"],["هتاخ","hatach_1452"]],"ll":["شوشن"]},{"i":"ezra-returns","k":"b","e":"exile-return","y":-458,"t":"عزرا يرجع ليعلّم الشريعة","j":-456,"r":[["Ezr",7,null,10,null]],"d":261,"l":"بابل ← أورشليم","x":"الكاهن الكاتب عزرا يقود رجوعًا ثانيًا، وقد «هيأ قلبه لطلب شريعة الرب والعمل بها وليعلّم إسرائيل»، فيجدد جماعة كانت تنزلق إلى المساومة.","s":-456,"pp":[["الله","god_1324"],["عزرا","ezra_1245"],["أرتحشستا","artaxerxes_314"],["عيلام","elam_1052"],["فينحاس","phinehas_2349"],["داود","david_994"]],"ll":["أورشليم","بابل","أهوا"]},{"i":"parthenon","k":"w","e":"exile-return","y":-447,"t":"العصر الذهبي لأثينا وبدء البارثينون","l":"أثينا، اليونان","x":"في عهد بريكليس تبني أثينا البارثينون على الأكروبوليس، بينما يزدهر المسرح والفلسفة والديمقراطية: عصر ذهبي قصير ترك بصمته على كل الثقافة الغربية.","s":-447},{"i":"nehemiah-walls","k":"b","e":"exile-return","y":-445,"t":"نحميا يبني سور أورشليم","j":-456,"r":[["Neh",1,null,6,null]],"d":262,"l":"أورشليم","x":"ساقي الملك يأخذ إذنًا ليبني مدينة آبائه. ورغم السخرية والتهديد، والبناؤون يعملون بيد ويمسكون السلاح بالأخرى، يكمل السور في اثنين وخمسين يومًا.","s":-456,"pp":[["الله","god_1324"],["سنبلط","sanballat_2470"],["طوبيا","tobiah_2872"],["جشم","geshem_1307"],["ألياشيب","eliashib_1099"],["مشلام","meshullam_2031"]],"ll":["أورشليم","باب الدمن","المصفاة"],"kx":"يقود عزرا الكاتب الرجوع الثاني، حاملًا الشريعة، ويقود إصلاحًا دينيًا، ويدعو الشعب إلى التوبة عن الزيجات بالشعوب الوثنية وتجديد العهد. ثم يأتي نحميا ساقي أرتحشستا بإذن لبناء سور أورشليم، ورغم مقاومة سنبلط وطوبيا يكمل السور في اثنين وخمسين يومًا، فاعترف الأعداء أن «من قبل إلهنا عُمل هذا العمل». وعالج نحميا الظلم الاجتماعي وكسر السبت والزيجات الغريبة. ومعًا ثبّت عزرا ونحميا سلطان الشريعة وهوية الجماعة، وبهما ينتهي تاريخ العهد القديم."},{"i":"herodotus","k":"w","e":"exile-return","y":-440,"t":"هيرودوت يكتب «التواريخ»","l":"العالم اليوناني","x":"«أبو التاريخ» ينشر بحثه في الحروب بين اليونان وفارس: أول عمل كبير في التاريخ القصصي، مليء بالجغرافيا وأحوال الشعوب وقصص الشرق القديم.","s":-440},{"i":"malachi","k":"b","e":"exile-return","y":-430,"t":"ملاخي آخر أنبياء العهد القديم","j":-441,"r":[["Mal",1,null,4,null]],"d":272,"l":"أورشليم","x":"العهد القديم يُختم بوعد: «يأتي بغتة إلى هيكله السيد الذي تطلبونه»، وإيليا النبي يأتي أولًا ليعد الطريق. ثم أربعة قرون بلا نبي.","s":-441,"pp":[["ملاخي","malachi_1899"]]},{"i":"silent-years","k":"b","e":"intertestamental","y":-430,"t":"بداية القرون الأربعة «الصامتة»","l":"اليهودية","x":"بعد ملاخي لا يتكلم نبي في إسرائيل أربعة قرون. لكن الله في هذا الصمت يهيئ التاريخ: لغة يونانية مشتركة، وطرق رومانية، ومجامع في كل مدينة، وشعب ينتظر المسيا.","s":-430,"kx":"بعد ملاخي يتوقف الوحي النبوي نحو أربعة قرون. وفي هذه الفترة تتعاقب الإمبراطوريات على اليهودية: فارس ثم اليونان مع الإسكندر الأكبر، ثم انقسام مملكته بين البطالمة في مصر والسلوقيين في سوريا. ويدنّس أنطيوخس الرابع الهيكل (١٦٧ ق.م) فتقوم ثورة المكابيين وتأتي فترة استقلال قصيرة، ثم يأخذ الرومان البلاد (٦٣ ق.م). وفيها نشأت المجامع، وظهر الفريسيون والصدوقيون، وتُرجمت الأسفار إلى اليونانية. ومع أن الكتاب صامت عنها، كان الله يهيئ «ملء الزمان» (غلاطية ٤: ٤)."},{"i":"plato-academy","k":"w","e":"intertestamental","y":-387,"t":"أفلاطون يؤسس الأكاديمية","l":"أثينا، اليونان","x":"أعظم تلاميذ سقراط يؤسس مدرسة في بستان أكاديموس، نموذج الجامعة الأول، تُدرس فيها الفلسفة والرياضيات والسياسة، وفيها يتعلم أرسطو الشاب عشرين سنة.","s":-387},{"i":"alexander-conquers","k":"w","e":"intertestamental","y":-331,"t":"الإسكندر الأكبر يفتح الشرق","l":"من اليونان إلى الهند","x":"في عشر سنين يُسقط الإسكندر الإمبراطورية الفارسية وينشر لغة اليونان وثقافتهم من مصر إلى نهر السند، وقد رأى اليهود في ذلك تحقيقًا لرؤى دانيال. وتصير اليونانية العامية (كويني) اللغة المشتركة التي كُتب بها العهد الجديد.","s":-331},{"i":"alexander-dies","k":"w","e":"intertestamental","y":-323,"t":"موت الإسكندر وانقسام مملكته","l":"بابل","x":"يموت الإسكندر في بابل وهو ابن اثنتين وثلاثين سنة دون وارث، فيقتسم قادته العالم. وتظل اليهودية قرونًا بين أسرتين: البطالمة في مصر والسلوقيين في سوريا.","s":-323},{"i":"septuagint","k":"b","e":"intertestamental","y":-250,"t":"الترجمة السبعينية: الكتاب باليونانية","l":"الإسكندرية، مصر","x":"علماء يهود في الإسكندرية يبدأون ترجمة الأسفار العبرية إلى اليونانية: الترجمة السبعينية. صارت كتاب العالم الناطق باليونانية، وهي الترجمة التي يقتبس منها كتّاب العهد الجديد أكثر من غيرها.","s":-250},{"i":"great-wall","k":"w","e":"intertestamental","y":-221,"t":"تشين شي هوانغ يوحد الصين والسور العظيم","l":"الصين","x":"الإمبراطور الأول يوحد الممالك المتحاربة في الصين الإمبراطورية، ويوحد الكتابة والمقاييس، ويربط أجزاء السور العظيم الأقدم، ويُدفن مع جيش من جنود الطين.","s":-221},{"i":"rosetta-stone","k":"w","e":"intertestamental","y":-196,"t":"نقش حجر رشيد","l":"مصر","x":"كهنة منف ينقشون مرسومًا لبطليموس الخامس بالهيروغليفية والديموطيقية واليونانية. وحين اكتُشف الحجر سنة ١٧٩٩ صار المفتاح الذي فك رموز كتابة مصر القديمة.","s":-196},{"i":"antiochus-desecrates","k":"b","e":"intertestamental","y":-167,"t":"أنطيوخس الرابع يدنس الهيكل","r":[["Dan",11,31,11,31]],"d":254,"l":"أورشليم","x":"الملك السلوقي أنطيوخس أبيفانيس يمنع حفظ الشريعة، ويقدم خنزيرًا على مذبح لزيوس أقامه في الهيكل، وهو ما يراه كثيرون «رجسة الخراب» التي في دانيال، فتشتعل الثورة.","s":-167},{"i":"maccabean-revolt","k":"b","e":"intertestamental","y":-164,"t":"ثورة المكابيين وتجديد الهيكل","r":[["Joh",10,22,10,22]],"d":296,"l":"اليهودية","x":"يهوذا المكابي («المطرقة») وإخوته يهزمون جيوش السلوقيين ويطهرون الهيكل. ويُحتفل بتدشينه من جديد كل سنة في عيد الحانوكا، وهو «عيد التجديد» الذي حضره يسوع (يوحنا ١٠: ٢٢).","s":-164,"ll":["أورشليم"]},{"i":"dead-sea-scrolls-community","k":"b","e":"intertestamental","y":-150,"t":"جماعة قمران تنسخ الأسفار","l":"قمران، عند البحر الميت","x":"جماعة يهودية منعزلة تسكن قمران وتنسخ الأسفار بدقة شديدة. ومكتبتها، مخطوطات البحر الميت التي خُبئت في الكهوف ووُجدت سنة ١٩٤٧، حفظت مخطوطات للكتاب أقدم بألف سنة مما كان معروفًا قبلها.","s":-150},{"i":"hasmonean-dynasty","k":"b","e":"intertestamental","y":-142,"t":"الحشمونيون يحكمون اليهودية مستقلة","ye":-63,"l":"اليهودية","x":"نسل المكابيين يحكم دولة يهودية مستقلة لأول مرة منذ السبي البابلي. وفي هذا العصر يظهر الفريسيون والصدوقيون والأسينيون: الأحزاب الدينية التي نقابلها في الأناجيل.","s":-142},{"i":"roman-roads","k":"w","e":"intertestamental","y":-100,"t":"الطرق الرومانية تربط المتوسط","l":"العالم الروماني","x":"طرق روما المرصوفة المخططة بدقة، بعشرات الآلاف من الأميال، تربط المتوسط عالمًا واحدًا. وعلى هذه الطرق نفسها حمل الرسل الإنجيل.","s":-100},{"i":"pompey-jerusalem","k":"b","e":"intertestamental","y":-63,"t":"بومبي يأخذ أورشليم لروما","l":"أورشليم","x":"القائد الروماني بومبي يتدخل في حرب أهلية بين الحشمونيين، ويقتحم جبل الهيكل ويدخل قدس الأقداس. تصير اليهودية تابعة لروما، ويبدأ العالم السياسي الذي نقرأ عنه في العهد الجديد.","s":-63},{"i":"caesar-assassinated","k":"w","e":"intertestamental","y":-44,"t":"اغتيال يوليوس قيصر","l":"روما","x":"في منتصف مارس يقتل أعضاء مجلس الشيوخ الدكتاتور الذي أنهى الجمهورية فعليًا. والحروب الأهلية التي تلت أنهت روما الجمهورية ومهدت الطريق للإمبراطورية.","s":-44},{"i":"herod-king","k":"b","e":"intertestamental","y":-37,"t":"هيرودس الكبير يملك على اليهودية","ye":-4,"r":[["Mat",2,null,2,null]],"d":275,"l":"اليهودية","x":"روما تعيّنه «ملك اليهود»، فيحكم الأدومي الداهية القاسي بمشاريع بناء ضخمة ودماء في بيته نفسه. وهو هيرودس الذي زاره المجوس، والذي أمر بقتل أطفال بيت لحم.","s":-37,"pp":[["هيرودس","herod_1504"],["الله","god_1324"],["يسوع","jesus_905"],["يوسف","joseph_1715"]],"ll":["بيت لحم","مصر","اليهودية","أورشليم"]},{"i":"augustus","k":"w","e":"intertestamental","y":-27,"t":"أغسطس أول إمبراطور روماني","l":"روما","x":"أوكتافيوس، الملقب أغسطس، يجمع السلطة كلها في يده تحت أشكال الجمهورية القديمة، ويبدأ «السلام الروماني»: قرنان من السلام النسبي والطرق الآمنة، فيها جاء «ملء الزمان» وانطلق الإنجيل.","s":-27},{"i":"herod-temple","k":"b","e":"intertestamental","y":-20,"t":"هيرودس يبدأ تجديد الهيكل","r":[["Joh",2,20,2,20]],"d":279,"l":"أورشليم","x":"هيرودس يبدأ توسيعًا ضخمًا للهيكل الثاني، فيضاعف ساحة جبل الهيكل لتصير أكبر ساحة مقدسة في العالم الروماني. وفي أيام خدمة يسوع كان قد «بُني في ست وأربعين سنة» ويلمع بالرخام والذهب.","s":-20},{"i":"t7","k":"b","e":"life-of-christ","y":-3969,"j":-3873,"est":1,"t":"ميلاد شيث","r":[["Gen",4,25,5,3],["Luk",3,38,3,38],["1Ch",1,1,1,1]],"s":-3872.99,"d":2,"pp":[["شيث","seth_2504"],["آدم","adam_78"],["حواء","eve_1231"]],"ll":["عدن"],"x":"تلد حواء ابنًا آخر وتدعو اسمه شيث قائلة: «لأن الله قد وضع لي نسلًا آخر عوضًا عن هابيل». وفي أيام ابنه أنوش «ابتُدئ أن يُدعى باسم الرب». ومن شيث يمر النسب إلى نوح ثم إبراهيم، ويذكره لوقا في نسب يسوع.","xs":1},{"i":"t248","k":"b","e":"life-of-christ","y":-6,"j":-5,"est":1,"t":"البشارة بميلاد يوحنا","r":[["Luk",1,5,1,25]],"s":-4.58,"d":273,"pp":[["أليصابات","elisabeth_1152"],["زكريا","zacharias_2971"]],"ll":["أورشليم"],"x":"زكريا الكاهن، من فرقة أبيا، يدخل الهيكل ليبخّر، فيظهر له الملاك جبرائيل ويبشره بأن امرأته أليصابات العاقر ستلد ابنًا يسميه يوحنا، يتقدم أمام الرب بروح إيليا وقوته. ولأنه لم يصدق يصير صامتًا حتى يتم الكلام، وتحبل أليصابات.","xs":1},{"i":"annunciation","k":"b","e":"life-of-christ","y":-5,"t":"البشارة","j":-4,"r":[["Luk",1,26,1,38]],"d":273,"l":"الناصرة، الجليل","x":"الملاك جبرائيل يبشر عذراء مخطوبة ليوسف بأنها ستلد ابن العلي الذي لا يكون لملكه نهاية. ومريم تجيب: «هوذا أنا أمة الرب. ليكن لي كقولك».","s":-4,"pp":[["مريم","mary_1938"]],"ll":["الناصرة"]},{"i":"t253","k":"b","e":"life-of-christ","y":-5,"j":-4,"est":1,"t":"ملاك يظهر ليوسف في حلم","r":[["Mat",1,19,1,25]],"s":-3.6,"d":274,"pp":[["يوسف","joseph_1715"]],"ll":["الناصرة"],"x":"لما وُجدت مريم حبلى قبل أن يجتمعا، أراد يوسف، وكان بارًّا، أن يخليها سرًّا. لكن ملاك الرب يظهر له في حلم: «لا تخف أن تأخذ مريم امرأتك... فستلد ابنًا وتدعو اسمه يسوع، لأنه يخلّص شعبه من خطاياهم». فيأخذ يوسف امرأته كما أمره الملاك.","xs":1},{"i":"t251","k":"b","e":"life-of-christ","y":-5,"j":-4,"est":1,"t":"مريم تزور أليصابات","r":[["Luk",1,39,1,56]],"s":-3.58,"d":273,"pp":[["مريم","mary_1938"],["أليصابات","elisabeth_1152"]],"x":"تذهب مريم مسرعة إلى مدينة يهوذا في الجبال لتزور أليصابات. وحين تسمع أليصابات سلامها يرتكض الجنين في بطنها، وتمتلئ من الروح القدس وتقول: «مباركة أنت في النساء». فتسبّح مريم: «تعظّم نفسي الرب»، وتمكث عندها نحو ثلاثة أشهر.","xs":1},{"i":"t252","k":"b","e":"life-of-christ","y":-5,"j":-4,"est":1,"t":"ميلاد يوحنا المعمدان","r":[["Luk",1,57,1,80]],"s":-3.58,"d":273,"pp":[["يوحنا","john_1676"]],"x":"تلد أليصابات ابنًا، وفي اليوم الثامن يريدون أن يسموه زكريا باسم أبيه، فيكتب زكريا: «اسمه يوحنا». وفي الحال ينفتح فمه ويمتلئ من الروح القدس ويتنبأ: «مبارك الرب إله إسرائيل لأنه افتقد وصنع فداء لشعبه». وينمو الصبي ويكون في البراري إلى يوم ظهوره لإسرائيل.","xs":1},{"i":"birth-of-jesus","k":"b","e":"life-of-christ","y":-5,"t":"ميلاد يسوع","j":-3,"r":[["Luk",2,1,2,20],["Mat",1,18,1,25]],"d":274,"l":"بيت لحم","x":"في أيام اكتتاب أوغسطس قيصر، يولد المسيح في مدينة داود ويُضجع في مذود. والملائكة يبشرون الرعاة «بفرح عظيم يكون لجميع الشعب»: عمانوئيل، الله معنا.","s":-3,"pp":[["الله","god_1324"],["مريم","mary_1938"],["يوسف","joseph_1715"],["داود","david_994"],["يسوع","jesus_905"]],"ll":["بيت لحم"],"kx":"الكلمة الأزلي يصير جسدًا: يُحبل به من الروح القدس في العذراء مريم (إشعياء ٧: ١٤)، ويولد في بيت لحم (ميخا ٥: ٢) في أيام أوغسطس قيصر. الملائكة يبشرون الرعاة بميلاد «مخلص هو المسيح الرب»، والمجوس يأتون من المشرق يطلبون الملك المولود، فيقتل هيرودس أطفال بيت لحم. ميلاد يسوع هو محور تاريخ الفداء: تجسد الله، وتحقيق وعود العهد، وبداية الخليقة الجديدة. والطفل في المذود هو الإله الكامل والإنسان الكامل، الوسيط الواحد بين الله والناس (تيموثاوس الأولى ٢: ٥)."},{"i":"t259","k":"b","e":"life-of-christ","y":-5,"j":-3,"est":1,"t":"ختان يسوع","r":[["Luk",2,21,2,21]],"s":-2.58,"d":274,"pp":[["يسوع","jesus_905"]],"x":"في اليوم الثامن يُختتن الطفل ويُسمى يسوع، كما سماه الملاك قبل أن يُحبل به في البطن. وبهذا يخضع ابن الله المتجسد لشريعة موسى منذ أيامه الأولى.","xs":1},{"i":"t261","k":"b","e":"life-of-christ","y":-5,"j":-3,"est":1,"t":"تقديم يسوع في الهيكل","r":[["Luk",2,22,2,38]],"s":-2.58,"d":274,"pp":[["يوسف","joseph_1715"],["مريم","mary_1938"],["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"بعد أيام التطهير يصعد يوسف ومريم بالطفل إلى الهيكل ليقدماه للرب، ويقدمان ذبيحة الفقراء: زوج يمام أو فرخي حمام. يحمله سمعان الشيخ البار على ذراعيه ويقول: «الآن تطلق عبدك يا سيد حسب قولك بسلام، لأن عينيّ قد أبصرتا خلاصك»، وتتكلم حنة النبية عنه لجميع المنتظرين فداء في أورشليم.","xs":1},{"i":"magi-flight","k":"b","e":"life-of-christ","y":-4,"t":"زيارة المجوس والهروب إلى مصر","j":-3,"r":[["Mat",2,null,2,null]],"d":275,"l":"بيت لحم ← مصر","x":"مجوس من المشرق يتبعون النجم ليسجدوا للملك الطفل ويقدموا ذهبًا ولبانًا ومرًّا. ويوسف، بعد إنذار في حلم، يهرب بالعائلة إلى مصر بينما يقتل هيرودس أطفال بيت لحم.","s":-3,"pp":[["هيرودس","herod_1504"],["الله","god_1324"],["يسوع","jesus_905"],["يوسف","joseph_1715"]],"ll":["بيت لحم","مصر","اليهودية","أورشليم"]},{"i":"t258","k":"b","e":"life-of-christ","y":-4,"j":-3,"est":1,"t":"هيرودس يقتل أطفال بيت لحم","r":[["Mat",2,16,2,18]],"s":-2.6,"d":275,"pp":[["هيرودس","herod_1504"]],"ll":["بيت لحم"],"x":"لما رأى هيرودس أن المجوس سخروا به غضب جدًا، وأرسل فقتل جميع الصبيان الذين في بيت لحم وفي كل تخومها، من ابن سنتين فما دون. ويرى متى في ذلك تحقيقًا لقول إرميا: «راحيل تبكي على أولادها ولا تريد أن تتعزى».","xs":1},{"i":"t260","k":"b","e":"life-of-christ","y":-4,"j":-3,"est":1,"t":"الرجوع من مصر","r":[["Mat",2,19,2,22]],"s":-2.6,"d":275,"pp":[["يوسف","joseph_1715"],["مريم","mary_1938"],["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"بعد موت هيرودس يظهر ملاك الرب ليوسف في حلم في مصر ويأمره أن يرجع بالصبي وأمه إلى أرض إسرائيل. لكنه حين يسمع أن أرخيلاوس يملك على اليهودية مكان أبيه يخاف أن يذهب إلى هناك.","xs":1},{"i":"t262","k":"b","e":"life-of-christ","y":-4,"j":-3,"est":1,"t":"الرجوع إلى الناصرة","r":[["Mat",2,22,2,23],["Luk",2,39,2,39]],"s":-2.6,"d":275,"pp":[["يوسف","joseph_1715"],["مريم","mary_1938"],["يسوع","jesus_905"]],"ll":["الناصرة"],"x":"بعد إنذار في حلم ينصرف يوسف إلى نواحي الجليل ويسكن في مدينة الناصرة، «لكي يتم ما قيل بالأنبياء: إنه سيُدعى ناصريًا». ويذكر لوقا أنهم رجعوا إلى الناصرة بعد أن أكملوا كل شيء حسب ناموس الرب.","xs":1},{"i":"ovid-livy","k":"w","e":"life-of-christ","y":8,"t":"العصر الذهبي للأدب اللاتيني","l":"روما","x":"الأدب الروماني يبلغ ذروته: أوفيد يكمل «التحولات»، وليفي يكتب تاريخه الضخم لروما، وأعمال فرجيل وهوراس اللذين ماتا حديثًا تصير كلاسيكيات.","s":8},{"i":"boy-jesus-temple","k":"b","e":"life-of-christ","y":8,"t":"الصبي يسوع في الهيكل","j":9,"r":[["Luk",2,41,2,52]],"d":274,"l":"أورشليم","x":"وهو ابن اثنتي عشرة سنة يجلس يسوع في وسط المعلمين في الهيكل، فيُبهتون من فهمه. ويقول لأبويه القلقين: «ألم تعلما أنه ينبغي أن أكون فيما لأبي؟».","s":9,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"]},{"i":"tiberius-emperor","k":"w","e":"life-of-christ","y":14,"t":"طيباريوس إمبراطورًا على روما","l":"روما","x":"يموت أغسطس ويتولى ابن زوجته طيباريوس الحكم. وفي «السنة الخامسة عشرة من سلطنة طيباريوس قيصر» (لوقا ٣: ١) بدأ يوحنا المعمدان يكرز، وصورة طيباريوس على الدينار هي التي قيل عنها: «أعطوا ما لقيصر لقيصر».","s":14},{"i":"roman-empire-extent","k":"w","e":"life-of-christ","y":20,"t":"السلام الروماني في أوج قوته","l":"عالم البحر المتوسط","x":"نحو ستين إلى سبعين مليون إنسان يعيشون تحت سلام روماني واحد: عملة مشتركة وطرق بحرية آمنة وطرق محروسة واليونانية لغة مشتركة: بنية هيأتها العناية الإلهية لانتشار الإنجيل.","s":20},{"i":"john-baptist-ministry","k":"b","e":"life-of-christ","y":26,"t":"يوحنا المعمدان يعد الطريق","j":26,"r":[["Luk",3,null,3,null],["Mat",3,null,3,null]],"d":276,"l":"برية اليهودية ونهر الأردن","x":"بعد أربعة قرون من الصمت، صوت نبي يصرخ في البرية: «توبوا لأنه قد اقترب ملكوت السماوات». والجموع تخرج إلى الأردن لتعتمد من السابق الذي وعد به ملاخي، الآتي بروح إيليا.","s":26,"pp":[["يوحنا","john_1676"]],"ll":["الأردن"],"kx":"يظهر يوحنا المعمدان في البرية تحقيقًا لنبوة ملاخي عن مجيء إيليا، ونبوة إشعياء عن «صوت صارخ في البرية». يكرز بالتوبة ويعمّد في الأردن ويعد الطريق للمسيا. خدمته هي نقطة الانتقال من العهد القديم إلى الجديد: «الناموس والأنبياء إلى يوحنا» (لوقا ١٦: ١٦). وفي معمودية يسوع ينزل الروح مثل حمامة ويقول الآب: «هذا هو ابني الحبيب» (متى ٣: ١٧). ثم يُسجن يوحنا ويُقتل، فتسبق نهايته رفض المسيح نفسه. وكلمته «ينبغي أن ذلك يزيد وأني أنا أنقص» (يوحنا ٣: ٣٠) هي جوهر التلمذة."},{"i":"baptism-of-jesus","k":"b","e":"life-of-christ","y":26,"t":"معمودية يسوع وتجربته","j":26,"r":[["Mat",3,13,4,11]],"d":276,"l":"نهر الأردن وبرية اليهودية","x":"حين يصعد يسوع من الماء ينزل الروح مثل حمامة، وصوت الآب يقول: «هذا هو ابني الحبيب». ثم يُقتاد إلى البرية فيصوم أربعين يومًا ويرد كل تجربة من الشيطان بكلمة مكتوبة.","s":26,"pp":[["يسوع","jesus_905"],["الشيطان","satan_2476"]]},{"i":"pilate-governor","k":"w","e":"life-of-christ","y":26,"t":"تعيين بيلاطس البنطي واليًا على اليهودية","l":"قيصرية وأورشليم","x":"طيباريوس يرسل بيلاطس واليًا على اليهودية. يذكره المؤرخان تاسيتوس ويوسيفوس، ونقش حجري وُجد في قيصرية، وهو الحاكم الروماني الذي وقف يسوع أمامه للمحاكمة.","s":26},{"i":"wedding-at-cana","k":"b","e":"life-of-christ","y":27,"t":"تحويل الماء خمرًا في قانا","j":27,"r":[["Joh",2,1,2,11]],"d":279,"l":"قانا الجليل","x":"في عرس قرية يحول يسوع ستة أجران حجرية من الماء إلى أجود خمر: بداية الآيات التي «أظهر بها مجده فآمن به تلاميذه».","s":27,"pp":[["يسوع","jesus_905"]],"ll":["قانا"]},{"i":"t277","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"يسوع يترك اليهودية إلى الجليل","r":[["Mat",4,12,4,12],["Mar",1,14,1,14],["Luk",4,14,4,14],["Joh",4,1,4,4]],"s":27.4,"d":277,"pp":[["يسوع","jesus_905"]],"ll":["اليهودية","الجليل"],"x":"لما سمع يسوع أن يوحنا قد أُسلم، انصرف من اليهودية إلى الجليل، ويقول لوقا إنه رجع «بقوة الروح». ومن هنا تبدأ خدمته الكبرى في الجليل.","xs":1},{"i":"t279","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"يسوع في الجليل","r":[["Mat",4,12,4,12],["Mar",1,14,1,15],["Luk",4,14,4,15],["Joh",4,43,4,54]],"s":27.4,"d":277,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يبدأ يسوع يكرز في الجليل قائلًا: «قد كمل الزمان واقترب ملكوت الله، فتوبوا وآمنوا بالإنجيل». ويعلّم في مجامعهم ممجَّدًا من الجميع، ويخرج خبره في كل الكورة المحيطة.","xs":1},{"i":"t281","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"يسوع في كفرناحوم","r":[["Mat",4,13,4,17],["Luk",4,31,4,31]],"s":27.4,"d":277,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يترك يسوع الناصرة ويسكن في كفرناحوم التي عند البحر، في تخوم زبولون ونفتاليم، ليتم قول إشعياء: «الشعب الجالس في ظلمة أبصر نورًا عظيمًا». وصارت كفرناحوم مركز خدمته في الجليل.","xs":1},{"i":"t282","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"«أجعلكما صيادي الناس»","r":[["Mat",4,18,4,22],["Mar",1,16,1,20],["Luk",5,1,5,11]],"s":27.4,"d":277,"pp":[["يسوع","jesus_905"],["أندراوس","andrew_264"],["سمعان","peter_2745"],["زبدي","zebedee_2998"],["يعقوب","james_717"]],"ll":["بحر الجليل"],"x":"يرى يسوع سمعان وأندراوس يلقيان شبكة في البحر فيقول: «هلمّ ورائي فأجعلكما صيادي الناس»، فيتركان الشباك ويتبعانه، ثم يدعو يعقوب ويوحنا ابني زبدي فيتركان أباهما والسفينة. ويذكر لوقا معجزة صيد السمك الكثير التي جعلت بطرس يسجد قائلًا: «اخرج من سفينتي يا رب، لأني رجل خاطئ».","xs":1},{"i":"t284","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"شفاء حماة بطرس وكثيرين","r":[["Mat",8,14,8,17],["Mar",1,29,1,34],["Luk",4,38,4,41]],"s":27.4001,"d":283,"pp":[["يسوع","jesus_905"],["حماة سمعان","mother_of_the_wife_of_simon_2111"]],"ll":["كفرناحوم"],"x":"يدخل يسوع بيت سمعان فيجد حماته محمومة، فيلمس يدها فتتركها الحمى وتقوم وتخدمهم. وعند المساء يقدمون إليه مرضى ومجانين كثيرين فيشفيهم، ويرى متى في ذلك تحقيقًا لقول إشعياء: «هو أخذ أسقامنا وحمل أمراضنا».","xs":1},{"i":"t276","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"سجن يوحنا المعمدان","r":[["Mat",14,1,14,5],["Luk",3,19,3,20],["Mar",6,14,6,20]],"s":27.4001,"d":290,"pp":[["هيرودس رئيس الربع","herod_1505"],["يوحنا","john_1676"]],"x":"كان هيرودس رئيس الربع قد قبض على يوحنا وأوثقه في السجن بسبب هيروديا امرأة فيلبس أخيه، لأن يوحنا كان يقول له: «لا يحل أن تكون لك». وكان هيرودس يخاف يوحنا لأنه يعلم أنه رجل بار وقديس.","xs":1},{"i":"t283","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"إخراج روح نجس في مجمع كفرناحوم","r":[["Mar",1,21,1,28],["Luk",4,32,4,37]],"s":27.41,"d":276,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"في يوم السبت يدخل يسوع مجمع كفرناحوم ويعلّم، فيُبهتون من تعليمه لأنه كان يعلّمهم كمن له سلطان. ويصرخ إنسان به روح نجس: «أنا أعرفك من أنت: قدوس الله»، فينتهره يسوع ويخرج الروح منه، ويذيع خبره في كل الجليل.","xs":1},{"i":"t280","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"رفض يسوع في الناصرة","r":[["Luk",4,16,4,30]],"s":27.42,"d":277,"pp":[["يسوع","jesus_905"]],"ll":["الناصرة"],"x":"يدخل يسوع مجمع الناصرة يوم السبت، ويقرأ من سفر إشعياء: «روح الرب عليّ لأنه مسحني لأبشر المساكين»، ثم يقول: «اليوم قد تم هذا المكتوب في مسامعكم». وحين يذكّرهم بأرملة صرفة ونعمان السرياني يمتلئون غضبًا ويحاولون طرحه من حافة الجبل، أما هو فيجوز في وسطهم ويمضي.","xs":1},{"i":"t269","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"شهادة يوحنا عن يسوع","r":[["Joh",1,15,1,34]],"s":27.43,"d":278,"x":"يشهد يوحنا المعمدان أنه ليس المسيح بل «صوت صارخ في البرية». ولما يرى يسوع مقبلًا يقول: «هوذا حمل الله الذي يرفع خطية العالم»، ويشهد أنه رأى الروح نازلًا مثل حمامة ومستقرًا عليه، «وأنا قد رأيت وشهدت أن هذا هو ابن الله».","xs":1},{"i":"t270","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"التلاميذ الأولون","r":[["Joh",1,35,1,51]],"s":27.43,"d":278,"pp":[["نثنائيل","nathanael_2158"],["أندراوس","andrew_264"],["سمعان","peter_2745"],["فيلبس","philip_2344"],["يوحنا","john_1677"]],"x":"يتبع اثنان من تلاميذ يوحنا يسوع، أحدهما أندراوس، فيأتي بأخيه سمعان، ويقول له يسوع: «أنت تُدعى صفا» أي بطرس. ثم يدعو فيلبس، فيأتي فيلبس بنثنائيل الذي يسأل: «أمن الناصرة يمكن أن يكون شيء صالح؟»، ثم يعترف: «يا معلم، أنت ابن الله».","xs":1},{"i":"t273","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"الفصح الأول وتطهير الهيكل","r":[["Joh",2,13,2,25]],"s":27.43,"d":279,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"يصعد يسوع إلى أورشليم في الفصح، فيصنع سوطًا من حبال ويطرد باعة البقر والغنم والحمام والصيارف: «لا تجعلوا بيت أبي بيت تجارة». ولما سأله اليهود عن آية قال: «انقضوا هذا الهيكل، وفي ثلاثة أيام أقيمه»، وكان يقول عن هيكل جسده.","xs":1},{"i":"t274","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"يسوع ونيقوديموس","r":[["Joh",3,1,3,21]],"s":27.43,"d":279,"pp":[["يسوع","jesus_905"],["نيقوديموس","nicodemus_2204"]],"ll":["أورشليم"],"x":"يأتي نيقوديموس، رئيس لليهود، إلى يسوع ليلًا، فيقول له يسوع: «إن كان أحد لا يولد من فوق لا يقدر أن يرى ملكوت الله». ويشرح الولادة من الماء والروح، ويذكر الحية النحاسية، ثم الكلمات الشهيرة: «لأنه هكذا أحب الله العالم حتى بذل ابنه الوحيد».","xs":1},{"i":"t275","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"يوحنا المعمدان يشهد مرة أخرى","r":[["Joh",3,22,3,36]],"s":27.43,"d":279,"pp":[["يوحنا","john_1676"]],"ll":["عين نون"],"x":"يعمّد تلاميذ يسوع في اليهودية، فيأتي تلاميذ يوحنا متضايقين لأن الجميع يذهبون إليه. فيجيب يوحنا بأنه صديق العريس الذي يفرح لصوته، ويقول: «ينبغي أن ذلك يزيد وأني أنا أنقص».","xs":1},{"i":"t278","k":"b","e":"life-of-christ","y":27,"j":27,"est":1,"t":"المرأة السامرية","r":[["Joh",4,5,4,42]],"s":27.43,"d":280,"pp":[["يسوع","jesus_905"]],"ll":["سوخار"],"x":"عند بئر يعقوب في سوخار يطلب يسوع من امرأة سامرية أن تسقيه، ثم يحدثها عن الماء الحي، ويكشف حياتها، ويقول إن الساجدين الحقيقيين يسجدون للآب بالروح والحق، ثم يعلن: «أنا الذي أكلمك هو». فتترك جرتها وتدعو أهل المدينة، فيؤمن كثيرون ويقولون: «هذا هو بالحقيقة المسيح مخلّص العالم».","xs":1},{"i":"sermon-on-mount","k":"b","e":"life-of-christ","y":28,"t":"الموعظة على الجبل","j":28,"r":[["Mat",5,null,7,null]],"d":282,"l":"التلال المطلة على بحر الجليل","x":"«طوبى للمساكين بالروح...». يسوع يضع دستور الملكوت: التطويبات والصلاة الربانية ومحبة الأعداء، والجموع تُبهت من تعليمه لأنه كان يعلّم كمن له سلطان.","s":28,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"kx":"امتدت خدمة يسوع العلنية نحو ثلاث سنين: تعليم (ومنه الموعظة على الجبل وأمثال الملكوت)، ومعجزات (شفاء وإخراج أرواح وسلطان على الطبيعة)، وصدام متزايد مع القادة الدينيين. أعلن لنفسه ما لله وحده: غفران الخطايا وقبول السجود، وقال: «قبل أن يكون إبراهيم أنا كائن» (يوحنا ٨: ٥٨). ومعجزاته شهدت لدعواه وأعلنت أن الملكوت قد اقترب. دعا الاثني عشر ودرّبهم وأرسلهم، وأكمل الناموس وفسّره بسلطان: «سمعتم أنه قيل... وأما أنا فأقول لكم»."},{"i":"twelve-apostles","k":"b","e":"life-of-christ","y":28,"t":"يسوع يختار الاثني عشر","j":28,"r":[["Mar",3,13,3,19],["Luk",6,12,6,16]],"d":285,"l":"الجليل","x":"بعد ليلة قضاها في الصلاة، يختار يسوع اثني عشر من تلاميذه، صيادين وعشارًا وغيورًا، ليكونوا معه وليرسلهم: رؤساء إسرائيل الجديد.","s":28,"pp":[["سمعان","peter_2745"],["أندراوس","andrew_264"],["يعقوب","james_717"],["يوحنا","john_1677"],["فيلبس","philip_2344"],["برثولماوس","bartholomew_405"],["توما","thomas_2851"],["متى","matthew_1971"],["لباوس","lebbaeus_1815"],["يهوذا","judas_1760"]],"ll":["كفرناحوم"]},{"i":"t286","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء الأبرص","r":[["Mat",8,1,8,4],["Mar",1,40,1,44],["Luk",5,12,5,14]],"s":28.4001,"d":283,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يأتي إليه أبرص ساجدًا ويقول: «يا سيد، إن أردت تقدر أن تطهرني». فيمد يسوع يده ويلمسه قائلًا: «أريد، فاطهر»، وفي الحال يطهر برصه. ويوصيه أن يُري نفسه للكاهن ويقدم القربان الذي أمر به موسى.","xs":1},{"i":"t297","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء غلام قائد المئة","r":[["Mat",8,5,8,13],["Luk",7,1,7,10]],"s":28.4001,"d":283,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"قائد مئة في كفرناحوم يطلب شفاء غلامه، ويقول: «لست مستحقًا أن تدخل تحت سقفي، لكن قل كلمة فقط فيبرأ غلامي». فيتعجب يسوع ويقول: «لم أجد ولا في إسرائيل إيمانًا بمقدار هذا»، ويبرأ الغلام في تلك الساعة.","xs":1},{"i":"t387","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"مجنونا كورة الجدريين","r":[["Mat",8,28,8,34],["Mar",5,1,5,20],["Luk",8,26,8,39]],"s":28.4001,"d":283,"pp":[["يسوع","jesus_905"]],"x":"في كورة الجدريين يخرج من القبور إنسان به أرواح نجسة كثيرة، اسمه «لجئون» لأنهم كثيرون. يأذن لهم يسوع فيدخلون في قطيع خنازير يندفع إلى البحر. ويطلب أهل المدينة أن يمضي يسوع عن تخومهم، أما الرجل فيرسله ليخبر بما صنع الرب به، فينادي في العشر المدن.","xs":1},{"i":"t287","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء المفلوج","r":[["Mat",9,1,9,8],["Mar",1,45,2,12],["Luk",5,15,5,26]],"s":28.4001,"d":285,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يقدّمون إليه مفلوجًا، ويقول مرقس ولوقا إنهم دلّوه من السقف بسبب الجمع. يقول يسوع: «ثق يا بني، مغفورة لك خطاياك»، فيتهمه الكتبة بالتجديف. فيقول: «لكي تعلموا أن لابن الإنسان سلطانًا على الأرض أن يغفر الخطايا»، ويأمر المفلوج أن يحمل سريره ويذهب.","xs":1},{"i":"t288","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"يسوع يدعو متى","r":[["Mat",9,9,9,13],["Mar",2,13,2,17],["Luk",5,27,5,32]],"s":28.4001,"d":285,"pp":[["يسوع","jesus_905"],["متى","matthew_1971"]],"ll":["كفرناحوم"],"x":"يرى يسوع متى (لاوي) جالسًا عند مكان الجباية فيقول له: «اتبعني»، فيقوم ويتبعه. ويصنع متى وليمة يتكئ فيها عشارون وخطاة كثيرون مع يسوع، فيعترض الفريسيون، فيقول: «لا يحتاج الأصحاء إلى طبيب بل المرضى... لم آتِ لأدعو أبرارًا بل خطاة إلى التوبة».","xs":1},{"i":"t289","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"سؤال عن الصوم","r":[["Mat",9,14,9,15],["Mar",2,18,2,20],["Luk",5,33,5,35]],"s":28.4001,"d":285,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يسأل تلاميذ يوحنا والفريسيون لماذا لا يصوم تلاميذ يسوع. فيجيب: «هل يستطيع بنو العرس أن ينوحوا ما دام العريس معهم؟ ولكن ستأتي أيام حين يُرفع العريس عنهم فحينئذ يصومون».","xs":1},{"i":"t290","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"مثل الزقاق الجديدة","r":[["Mat",9,16,9,17],["Mar",2,21,2,22],["Luk",5,36,5,39]],"s":28.4001,"d":285,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يضرب يسوع مثلين: لا أحد يرقع ثوبًا عتيقًا بقطعة جديدة، ولا يجعلون خمرًا جديدة في زقاق عتيقة لئلا تنشق، بل يجعلون الخمر الجديدة في زقاق جديدة. فما يأتي به يسوع لا يُرقَّع به القديم.","xs":1},{"i":"t388","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"معجزات في كفرناحوم: ابنة يايرس ونازفة الدم","r":[["Mat",9,18,9,34],["Mar",5,21,5,43],["Luk",8,40,8,48]],"s":28.4001,"d":285,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يأتي يايرس رئيس المجمع يطلب من يسوع أن يأتي إلى ابنته المحتضرة. وفي الطريق تلمس هدب ثوبه امرأة بها نزف دم منذ اثنتي عشرة سنة فتبرأ، فيقول لها: «إيمانك قد شفاك». ثم يدخل بيت يايرس ويقول: «لم تمت الصبية لكنها نائمة»، ويمسك بيدها قائلًا: «طليثا قومي»، فتقوم.","xs":1},{"i":"t299","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"يسوع يتكلم عن يوحنا المعمدان","r":[["Mat",11,2,11,19],["Luk",7,18,7,35]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"],["يوحنا","john_1676"]],"ll":["الجليل"],"x":"يرسل يوحنا من السجن تلميذين يسألان: «أنت هو الآتي أم ننتظر آخر؟»، فيجيب يسوع بأعماله: العمي يبصرون والعرج يمشون والموتى يقومون والمساكين يُبشَّرون. ثم يشهد عن يوحنا: «لم يقم بين المولودين من النساء أعظم من يوحنا المعمدان».","xs":1},{"i":"t300","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"الويل لكورزين وبيت صيدا","r":[["Mat",11,20,11,30]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يوبخ يسوع المدن التي صُنعت فيها أكثر قواته ولم تتب: «ويل لك يا كورزين، ويل لك يا بيت صيدا». ثم يشكر الآب لأنه أخفى هذه عن الحكماء وأعلنها للأطفال، ويدعو: «تعالوا إليّ يا جميع المتعبين والثقيلي الأحمال وأنا أريحكم».","xs":1},{"i":"t292","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"قطف السنابل في السبت","r":[["Mat",12,1,12,8],["Mar",2,23,2,28],["Luk",6,1,6,5]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يجتاز يسوع بين الزروع في سبت، فيقطف تلاميذه سنابل ويأكلون، فيعترض الفريسيون. يذكّرهم يسوع بداود الذي أكل خبز التقدمة، ويقول: «السبت إنما جُعل لأجل الإنسان لا الإنسان لأجل السبت... فإن ابن الإنسان هو رب السبت أيضًا».","xs":1},{"i":"t293","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء اليد اليابسة","r":[["Mat",12,9,12,14],["Mar",3,1,3,6],["Luk",6,6,6,11]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"في المجمع إنسان يده يابسة، والفريسيون يراقبون هل يشفيه في السبت. يسألهم يسوع: «هل يحل في السبت فعل الخير أو فعل الشر؟»، ثم يقول للرجل: «مدّ يدك» فتعود صحيحة. فيخرج الفريسيون ويتشاورون عليه لكي يهلكوه.","xs":1},{"i":"t294","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء الجموع","r":[["Mat",12,15,12,21],["Mar",3,7,3,12],["Luk",6,17,6,19]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"ينصرف يسوع إلى البحر، ويتبعه جمع كثير من الجليل واليهودية وأورشليم وأدومية وعبر الأردن ونواحي صور وصيدا، فيشفيهم جميعًا ويوصيهم ألا يظهروه. ويرى متى في ذلك تحقيقًا لنبوة إشعياء عن عبد الرب الذي «قصبة مرضوضة لا يقصف».","xs":1},{"i":"t303","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء المجنون الأعمى الأخرس والحديث بعده","r":[["Mat",12,22,12,50],["Mar",3,19,3,30],["Luk",8,19,11,36]],"s":28.4001,"d":287,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يشفي يسوع مجنونًا أعمى وأخرس، فيقول الفريسيون إنه يُخرج الشياطين ببعلزبول. فيرد: «كل مملكة منقسمة على ذاتها تخرب»، ويحذّر من التجديف على الروح القدس، ويقول إنه لن تُعطى آية إلا آية يونان النبي. وحين تأتي أمه وإخوته يقول: «من يصنع مشيئة أبي الذي في السماوات هو أخي وأختي وأمي».","xs":1},{"i":"t386","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"أمثال على شاطئ البحر وتسكين العاصفة","r":[["Mat",8,18,13,53],["Mar",4,1,4,41],["Luk",8,4,9,62]],"s":28.4001,"d":283,"pp":[["يسوع","jesus_905"]],"ll":["بحر الجليل"],"x":"يجلس يسوع في سفينة ويعلّم الجمع على الشاطئ بأمثال: الزارع، والزوان، وحبة الخردل، والخميرة، والكنز المخفي، واللؤلؤة الكثيرة الثمن، والشبكة. وعند المساء يعبر البحر فيحدث نوء عظيم، فيقوم وينتهر الريح: «اسكت، ابكم»، فيصير هدوء عظيم، ويتساءل التلاميذ: «من هو هذا؟ فإن الريح أيضًا والبحر يطيعانه».","xs":1},{"i":"t285","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"الجولة الأولى في الجليل","r":[["Mar",1,35,1,39],["Mat",4,23,4,25],["Luk",4,42,4,44]],"s":28.41,"d":276,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["الجليل"],"x":"في الصبح باكرًا جدًا يقوم يسوع ويمضي إلى موضع خلاء ويصلي هناك. ولما يجده التلاميذ قائلين إن الجميع يطلبونه، يقول: «لنذهب إلى القرى المجاورة لأكرز هناك أيضًا، لأني لهذا خرجت». ويطوف كل الجليل يعلّم في المجامع ويشفي كل مرض.","xs":1},{"i":"t298","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"إقامة ابن أرملة نايين","r":[["Luk",7,11,7,17]],"s":28.4201,"d":283,"pp":[["يسوع","jesus_905"]],"ll":["نايين"],"x":"عند باب مدينة نايين يخرج ميت محمول، ابن وحيد لأمه وهي أرملة. يتحنن عليها يسوع ويقول: «لا تبكي»، ثم يلمس النعش: «أيها الشاب، لك أقول: قم». فيجلس الميت ويبتدئ يتكلم، ويمجد الجميع الله قائلين: «قد قام فينا نبي عظيم، وافتقد الله شعبه».","xs":1},{"i":"t301","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"امرأة خاطئة تدهن قدمي يسوع","r":[["Luk",7,36,7,50]],"s":28.4201,"d":283,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"في بيت سمعان الفريسي تأتي امرأة خاطئة وتبل قدمي يسوع بدموعها وتمسحهما بشعر رأسها وتدهنهما بالطيب. يتذمر سمعان في نفسه، فيضرب له يسوع مثل المديونين، ويقول: «قد غُفرت خطاياها الكثيرة لأنها أحبت كثيرًا»، ثم يقول لها: «إيمانك قد خلصك، اذهبي بسلام».","xs":1},{"i":"t302","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"الجولة الثانية في الجليل","r":[["Luk",8,1,8,3]],"s":28.4201,"d":284,"pp":[["يسوع","jesus_905"],["مريم","mary_1943"],["يونا","joanna_1629"],["سوسنة","susanna_2804"]],"ll":["الجليل"],"x":"يسير يسوع في مدينة وقرية يكرز ويبشر بملكوت الله، ومعه الاثنا عشر وبعض النساء اللواتي شفاهن: مريم المجدلية، ويونّا امرأة خوزي وكيل هيرودس، وسوسنة، وأخريات كثيرات كن يخدمنه من أموالهن.","xs":1},{"i":"t291","k":"b","e":"life-of-christ","y":28,"j":28,"est":1,"t":"شفاء مريض بركة بيت حسدا","r":[["Joh",5,1,5,47]],"s":28.4301,"d":291,"pp":[["يسوع","jesus_905"]],"ll":["بيت حسدا"],"x":"في أورشليم عند بركة بيت حسدا ذات الأروقة الخمسة إنسان مريض منذ ثمان وثلاثين سنة. يقول له يسوع: «قم، احمل سريرك وامشِ»، فيبرأ في الحال، وكان ذلك اليوم سبتًا. وحين يطلب اليهود قتله يقول: «أبي يعمل حتى الآن وأنا أعمل»، ثم يتكلم طويلًا عن سلطان الابن والشهود له: يوحنا والأعمال والآب والكتب.","xs":1},{"i":"feeding-5000","k":"b","e":"life-of-christ","y":29,"t":"إشباع الخمسة آلاف","j":29,"r":[["Joh",6,null,6,null],["Mar",6,30,6,44]],"d":291,"l":"قرب بيت صيدا، بحر الجليل","x":"من خمسة أرغفة شعير وسمكتين يُشبع يسوع جموعًا كثيرة، ويفضل اثنتا عشرة قفة: المعجزة الوحيدة المذكورة في الأناجيل الأربعة كلها. ثم يقول: «أنا هو خبز الحياة».","s":29,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["كفرناحوم"]},{"i":"transfiguration","k":"b","e":"life-of-christ","y":29,"t":"التجلي","j":29,"r":[["Mat",17,1,17,13],["Mar",9,2,9,13]],"d":293,"l":"جبل عالٍ (تقليديًا تابور أو حرمون)","x":"أمام بطرس ويعقوب ويوحنا يتغير منظر يسوع ويضيء وجهه كالشمس، وموسى وإيليا يتكلمان معه عن خروجه الذي كان عتيدًا أن يكمله في أورشليم. وصوت الآب: «هذا هو ابني الحبيب... له اسمعوا».","s":29,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"],["موسى","moses_2108"],["إيليا","elijah_1131"],["يوحنا","john_1677"],["يعقوب","james_717"]],"ll":["جبل حرمون"]},{"i":"t390","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الجولة الثالثة في الجليل وإرسال الاثني عشر","r":[["Mat",9,35,11,1],["Mar",6,7,6,13],["Luk",9,1,9,6]],"s":29.4001,"d":285,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يطوف يسوع المدن والقرى، ويتحنن على الجموع لأنهم «كغنم لا راعي لها»، ويقول: «الحصاد كثير ولكن الفعلة قليلون». ثم يدعو الاثني عشر ويعطيهم سلطانًا ويرسلهم اثنين اثنين ليكرزوا ويشفوا، ويوصيهم بوصايا الإرسالية في متى ١٠.","xs":1},{"i":"t389","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الرفض الثاني في الناصرة","r":[["Mat",13,54,13,58],["Mar",6,1,6,6]],"s":29.4001,"d":289,"pp":[["يسوع","jesus_905"]],"ll":["الناصرة"],"x":"يأتي يسوع إلى وطنه ويعلّم في مجمعهم فيُبهتون ويقولون: «أليس هذا ابن النجار؟». فيعثرون به، فيقول: «ليس نبي بلا كرامة إلا في وطنه»، ولم يصنع هناك قوات كثيرة لعدم إيمانهم.","xs":1},{"i":"t391","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"قطع رأس يوحنا المعمدان","r":[["Mat",14,6,14,12],["Mar",6,21,6,29],["Luk",9,7,9,9]],"s":29.4001,"d":290,"pp":[["يوحنا","john_1676"],["هيرودس رئيس الربع","herod_1505"]],"x":"في يوم ميلاد هيرودس ترقص ابنة هيروديا فيعدها بقسم أن يعطيها ما تطلب، فتطلب بتحريض أمها رأس يوحنا المعمدان على طبق. فيحزن الملك لكنه من أجل القسم يرسل ويقطع رأس يوحنا في السجن. ويأتي تلاميذه فيدفنون الجسد ويخبرون يسوع.","xs":1},{"i":"t394","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"يسوع يمشي على الماء","r":[["Mat",14,22,14,33],["Mar",6,45,6,52],["Joh",6,15,6,21]],"s":29.4001,"d":290,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["بحر الجليل"],"x":"بعد إشباع الجموع يصعد يسوع إلى الجبل ليصلي، والتلاميذ في السفينة تعذبهم الأمواج. وفي الهزيع الرابع من الليل يأتي إليهم ماشيًا على البحر: «تشجعوا، أنا هو، لا تخافوا». ويمشي بطرس على الماء ثم يخاف فيبتدئ يغرق، فيمسكه يسوع، ويسجد له الذين في السفينة: «بالحقيقة أنت ابن الله».","xs":1},{"i":"t396","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء المرضى في جنيسارت","r":[["Mat",14,34,14,36],["Mar",6,53,6,56]],"s":29.4001,"d":290,"pp":[["يسوع","jesus_905"]],"ll":["جنيسارت"],"x":"يعبرون إلى أرض جنيسارت، فيعرفه أهل المكان ويرسلون إلى كل الكورة، ويقدمون إليه جميع المرضى، ويطلبون أن يلمسوا هدب ثوبه فقط، فكل من لمسه نال الشفاء.","xs":1},{"i":"t398","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الوصية وتقليد الشيوخ","r":[["Mat",15,1,15,20],["Mar",7,1,7,23]],"s":29.4002,"d":292,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["كفرناحوم"],"x":"يأتي فريسيون وكتبة من أورشليم يسألون لماذا يأكل التلاميذ بأيدٍ غير مغسولة، مخالفين تقليد الشيوخ. فيجيب يسوع: «وأنتم أيضًا لماذا تتعدون وصية الله بسبب تقليدكم؟»، ويستشهد بإشعياء: «هذا الشعب يكرمني بشفتيه وأما قلبه فمبتعد عني بعيدًا». ثم يعلّم أن ما يخرج من القلب هو الذي ينجس الإنسان.","xs":1},{"i":"t399","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء ابنة المرأة الكنعانية","r":[["Mat",15,21,15,28],["Mar",7,24,7,30]],"s":29.4002,"d":292,"pp":[["يسوع","jesus_905"]],"ll":["صور","صيدون"],"x":"في نواحي صور وصيدا تصرخ إليه امرأة كنعانية من أجل ابنتها المجنونة. يقول لها: «ليس حسنًا أن يؤخذ خبز البنين ويُطرح للكلاب»، فتجيب: «نعم يا سيد، والكلاب أيضًا تأكل من الفتات الذي يسقط من مائدة أربابها». فيقول: «يا امرأة، عظيم إيمانك»، وتُشفى ابنتها من تلك الساعة.","xs":1},{"i":"t401","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"إشباع الأربعة آلاف","r":[["Mat",15,32,15,39],["Mar",8,1,8,9]],"s":29.4002,"d":292,"pp":[["يسوع","jesus_905"]],"ll":["العشر المدن"],"x":"تبقى الجموع مع يسوع ثلاثة أيام وليس لهم ما يأكلون، فيتحنن عليهم. ومن سبع خبزات وقليل من صغار السمك يُشبع أربعة آلاف رجل ما عدا النساء والأولاد، ويرفعون ما فضل من الكسر سبعة سلال مملوءة.","xs":1},{"i":"t404","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"اعتراف بطرس: «أنت هو المسيح ابن الله الحي»","r":[["Mat",16,13,16,20],["Mar",8,27,8,30],["Luk",9,18,9,21]],"s":29.4002,"d":292,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["قيصرية فيلبس"],"x":"في نواحي قيصرية فيلبس يسأل يسوع تلاميذه: «من يقول الناس إني أنا ابن الإنسان؟... وأنتم من تقولون إني أنا؟». فيجيب بطرس: «أنت هو المسيح ابن الله الحي». فيقول له يسوع إن لحمًا ودمًا لم يعلن له هذا بل الآب، ويعده: «على هذه الصخرة أبني كنيستي».","xs":1},{"i":"t405","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"يسوع ينبئ بموته وقيامته","r":[["Mat",16,21,16,28],["Mar",8,31,9,1],["Luk",9,22,9,27]],"s":29.4002,"d":292,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["قيصرية فيلبس"],"x":"من ذلك الوقت يبتدئ يسوع يُظهر لتلاميذه أنه ينبغي أن يذهب إلى أورشليم ويتألم كثيرًا ويُقتل وفي اليوم الثالث يقوم. ينتهره بطرس فيقول له: «اذهب عني يا شيطان». ثم يعلّم: «إن أراد أحد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني... ماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه؟».","xs":1},{"i":"t407","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء الغلام المصروع","r":[["Mat",17,14,17,21],["Mar",9,14,9,29],["Luk",9,37,9,42]],"s":29.4002,"d":293,"pp":[["يسوع","jesus_905"]],"ll":["جبل حرمون"],"x":"بعد النزول من جبل التجلي يقدّم أب ابنه المصروع، وقد عجز التلاميذ عن شفائه. يقول الأب: «أؤمن يا سيد، فأعن عدم إيماني»، فينتهر يسوع الروح ويبرأ الغلام. ويشرح لتلاميذه قوة الإيمان ولو كان مثل حبة خردل، وأن هذا الجنس لا يخرج إلا بالصلاة.","xs":1},{"i":"t408","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الإنباء الثاني بالموت والقيامة","r":[["Mat",17,22,17,23],["Mar",9,30,9,32],["Luk",9,43,9,45]],"s":29.4002,"d":293,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"وهم يترددون في الجليل يقول يسوع مرة ثانية: «ابن الإنسان سوف يُسلَّم إلى أيدي الناس فيقتلونه، وفي اليوم الثالث يقوم». فيحزن التلاميذ جدًا، ولم يفهموا القول وخافوا أن يسألوه.","xs":1},{"i":"t409","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الإستار في فم السمكة","r":[["Mat",17,24,17,27]],"s":29.4002,"d":293,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["كفرناحوم"],"x":"في كفرناحوم يسأل جباة الدرهمين بطرس: «أما يوفي معلمكم الدرهمين؟». فيبيّن يسوع أن البنين أحرار، لكن لئلا يعثرهم يرسل بطرس إلى البحر ليلقي صنارة، فيجد في فم أول سمكة إستارًا يدفعه عنه وعن نفسه.","xs":1},{"i":"t410","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"تعليم عن الاتضاع والعثرات والمصالحة","r":[["Mat",18,1,18,35],["Mar",9,33,9,50],["Luk",9,46,9,50]],"s":29.4002,"d":294,"pp":[["يسوع","jesus_905"]],"ll":["كفرناحوم"],"x":"يسأل التلاميذ: «من هو أعظم في ملكوت السماوات؟»، فيقيم يسوع ولدًا في وسطهم: «إن لم ترجعوا وتصيروا مثل الأولاد فلن تدخلوا ملكوت السماوات». ثم يعلّم عن العثرات، والخروف الضال، ومعاتبة الأخ المخطئ، والغفران «إلى سبعين مرة سبع مرات»، ويضرب مثل العبد الذي لا يرحم.","xs":1},{"i":"t400","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء جموع عند بحر الجليل","r":[["Mar",7,31,7,37],["Mat",15,29,15,31]],"s":29.4101,"d":292,"pp":[["يسوع","jesus_905"]],"ll":["العشر المدن","بحر الجليل"],"x":"يرجع يسوع من نواحي صور وصيدا إلى بحر الجليل عبر العشر المدن، فيقدمون إليه أصم أعقد، فيضع أصابعه في أذنيه ويقول: «إفّثا» أي انفتح، فينفتح سمعه وينطق. وتأتي جموع كثيرة بعرج وعمي وخرس وشُل فيشفيهم، فيمجدون إله إسرائيل.","xs":1},{"i":"t402","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الحديث مع الفريسيين والصدوقيين","r":[["Mar",8,10,8,21],["Mat",16,1,16,12]],"s":29.4101,"d":292,"pp":[["يسوع","jesus_905"]],"ll":["دلمانوثة"],"x":"يأتي الفريسيون والصدوقيون يطلبون آية من السماء ليجربوه، فيقول: «تعرفون أن تميزوا وجه السماء، وأما علامات الأزمنة فلا تستطيعون». ثم يحذّر تلاميذه: «تحرزوا من خمير الفريسيين والصدوقيين»، فيظنون أنه يتكلم عن الخبز، ثم يفهمون أنه يقصد تعليمهم.","xs":1},{"i":"t403","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء أعمى في بيت صيدا","r":[["Mar",8,22,8,26]],"s":29.4101,"d":292,"pp":[["يسوع","jesus_905"]],"ll":["بيت صيدا"],"x":"في بيت صيدا يقدّمون إليه أعمى، فيأخذه خارج القرية ويتفل في عينيه ويضع يديه عليه، فيقول: «أبصر الناس كأشجار يمشون». ثم يضع يديه مرة أخرى على عينيه فيعود صحيحًا ويبصر كل إنسان جليًا، المعجزة الوحيدة التي تمت على مرحلتين.","xs":1},{"i":"t421","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"قرية سامرية ترفض يسوع","r":[["Luk",9,51,9,56]],"s":29.4201,"d":286,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"حين تقترب أيام ارتفاعه يثبّت يسوع وجهه لينطلق إلى أورشليم، ويرسل رسلًا إلى قرية للسامريين فلا يقبلونه. يقول يعقوب ويوحنا: «أتريد أن نقول أن تنزل نار من السماء فتفنيهم؟»، فينتهرهما يسوع، ويمضون إلى قرية أخرى.","xs":1},{"i":"t422","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"إرسال السبعين","r":[["Luk",10,1,10,24]],"s":29.4201,"d":297,"pp":[["يسوع","jesus_905"]],"x":"يعيّن الرب سبعين آخرين ويرسلهم اثنين اثنين أمام وجهه إلى كل مدينة كان مزمعًا أن يأتي إليها: «ها أنا أرسلكم مثل حملان بين ذئاب». ويرجعون بفرح: «حتى الشياطين تخضع لنا باسمك»، فيقول: «لا تفرحوا بهذا... بل افرحوا بالحري أن أسماءكم كُتبت في السماوات».","xs":1},{"i":"t423","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"مثل السامري الصالح","r":[["Luk",10,25,10,37]],"s":29.4201,"d":297,"pp":[["يسوع","jesus_905"]],"ll":["اليهودية"],"x":"يسأل ناموسي: «ماذا أعمل لأرث الحياة الأبدية؟»، ثم: «من هو قريبي؟». فيروي يسوع قصة إنسان وقع بين لصوص، مرّ به كاهن ولاوي وجازا مقابله، أما سامري فتحنن عليه وضمد جراحه وأوصله إلى فندق. ثم يقول: «اذهب أنت أيضًا واصنع هكذا».","xs":1},{"i":"t424","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"يسوع في بيت مرثا ومريم","r":[["Luk",10,38,10,42]],"s":29.4201,"d":297,"pp":[["يسوع","jesus_905"],["مرثا","martha_1937"],["مريم","mary_1939"]],"ll":["بيت عنيا"],"x":"تستقبل مرثا يسوع في بيتها، وتجلس أختها مريم عند قدميه تسمع كلامه، بينما مرثا مرتبكة في خدمة كثيرة. تطلب منه أن يقول لمريم أن تعينها، فيقول: «مرثا مرثا، أنت تهتمين وتضطربين لأجل أمور كثيرة، ولكن الحاجة إلى واحد. فاختارت مريم النصيب الصالح».","xs":1},{"i":"t425","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"تعليم الصلاة الربانية","r":[["Luk",11,1,11,13]],"s":29.4201,"d":297,"pp":[["يسوع","jesus_905"]],"x":"بعد أن يصلي يسوع يطلب منه أحد تلاميذه: «يا رب علّمنا أن نصلي»، فيعلّمهم الصلاة الربانية. ثم يضرب مثل الصديق الذي يأتي نصف الليل، ويقول: «اسألوا تعطوا، اطلبوا تجدوا»، ويختم بأن الآب السماوي يعطي الروح القدس للذين يسألونه.","xs":1},{"i":"t428","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الويلات والأمثال مع الفريسيين","r":[["Luk",11,37,13,9]],"s":29.4201,"d":297,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"x":"في بيت فريسي يعلن يسوع ويلات على الفريسيين والناموسيين لأنهم يهتمون بالظاهر ويتركون الحق ومحبة الله. ثم يعلّم الجموع: يحذّر من الرياء، ويضرب مثل الغني الغبي، ويقول «لا تهتموا»، ويوصي بالسهر، ويدعو إلى التوبة، ويختم بمثل التينة غير المثمرة.","xs":1},{"i":"t429","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء المرأة المنحنية منذ ثماني عشرة سنة","r":[["Luk",13,10,13,17]],"s":29.4201,"d":298,"pp":[["يسوع","jesus_905"]],"x":"في مجمع يوم السبت امرأة بها روح ضعف منذ ثماني عشرة سنة، منحنية لا تقدر أن تنتصب. يدعوها يسوع: «يا امرأة، إنك محلولة من ضعفك»، ويضع يديه عليها فتستقيم وتمجد الله. يغتاظ رئيس المجمع، فيرد يسوع بأن هذه ابنة إبراهيم كان ينبغي أن تُحل في يوم السبت، فيخزى معاندوه.","xs":1},{"i":"t430","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"مثل حبة الخردل والخميرة","r":[["Luk",13,18,13,21]],"s":29.4201,"d":298,"pp":[["يسوع","jesus_905"]],"x":"يشبّه يسوع ملكوت الله بحبة خردل أخذها إنسان وألقاها في بستانه فنمت وصارت شجرة كبيرة تتآوى طيور السماء في أغصانها، وبخميرة أخذتها امرأة وخبأتها في ثلاثة أكيال دقيق حتى اختمر الجميع.","xs":1},{"i":"t412","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"عيد المظال","r":[["Joh",7,1,7,52]],"s":29.4301,"d":295,"pp":[["يسوع","jesus_905"],["نيقوديموس","nicodemus_2204"]],"ll":["الجليل","أورشليم"],"x":"إخوة يسوع لم يكونوا يؤمنون به. يصعد إلى عيد المظال في الخفاء، ثم يعلّم في الهيكل في وسط العيد. وفي اليوم الأخير العظيم يقف وينادي: «إن عطش أحد فليقبل إليّ ويشرب»، وكان يقول هذا عن الروح. فيحدث انشقاق، ويرجع الخدام الذين أُرسلوا ليمسكوه قائلين: «لم يتكلم قط إنسان هكذا مثل هذا الإنسان».","xs":1},{"i":"t419","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"المرأة التي أُمسكت في زنا","r":[["Joh",7,53,8,11]],"s":29.4301,"d":295,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"يقدّم الكتبة والفريسيون امرأة أُمسكت في زنا ليجربوه بشريعة موسى. ينحني يسوع ويكتب على الأرض ثم يقول: «من كان منكم بلا خطية فليرمها أولًا بحجر»، فيخرجون واحدًا فواحدًا. ثم يقول لها: «ولا أنا أدينك. اذهبي ولا تخطئي أيضًا».","xs":1},{"i":"t420","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"«أنا هو نور العالم» وحديث «أنا كائن»","r":[["Joh",8,12,8,59]],"s":29.4301,"d":295,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"يقول يسوع: «أنا هو نور العالم، من يتبعني فلا يمشي في الظلمة بل يكون له نور الحياة». ويجادله اليهود طويلًا، فيقول: «تعرفون الحق والحق يحرركم»، ويختم: «قبل أن يكون إبراهيم أنا كائن»، فيرفعون حجارة ليرجموه.","xs":1},{"i":"t426","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"شفاء المولود أعمى","r":[["Joh",9,1,9,41]],"s":29.4301,"d":296,"pp":[["يسوع","jesus_905"]],"ll":["سلوام"],"x":"يرى يسوع إنسانًا أعمى منذ ولادته، فيسأله التلاميذ: من أخطأ؟ فيقول: «لا هذا أخطأ ولا أبواه، لكن لتظهر أعمال الله فيه». يطلي عينيه بالطين ويرسله ليغتسل في بركة سلوام فيرجع بصيرًا. ويحقق معه الفريسيون فيقول: «كنت أعمى والآن أبصر»، فيطردونه، فيجده يسوع ويؤمن به ويسجد له.","xs":1},{"i":"t427","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"الراعي الصالح","r":[["Joh",10,1,10,21]],"s":29.4301,"d":296,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"يقول يسوع: «أنا هو الباب، إن دخل بي أحد فيخلص»، ثم: «أنا هو الراعي الصالح، والراعي الصالح يبذل نفسه عن الخراف». ويتكلم عن خراف أخر ليست من هذه الحظيرة ينبغي أن يأتي بها، ويقول إنه يضع نفسه ليأخذها أيضًا. فيحدث انشقاق بين اليهود بسبب هذا الكلام.","xs":1},{"i":"t431","k":"b","e":"life-of-christ","y":29,"j":29,"est":1,"t":"عيد التجديد","r":[["Joh",10,22,10,39]],"s":29.4301,"d":296,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"في عيد التجديد في الشتاء يتمشى يسوع في رواق سليمان، فيحيط به اليهود: «إن كنت أنت المسيح فقل لنا جهرًا». فيقول: «خرافي تسمع صوتي... ولا يخطفها أحد من يدي... أنا والآب واحد». فيتناولون حجارة ليرجموه، فيخرج من أيديهم.","xs":1},{"i":"raising-lazarus","k":"b","e":"life-of-christ","y":33,"t":"إقامة لعازر","j":30,"r":[["Joh",11,null,11,null]],"d":301,"l":"بيت عنيا","x":"«أنا هو القيامة والحياة». يسوع يبكي عند قبر صديقه، ثم ينادي لعازر الميت منذ أربعة أيام فيخرج حيًا: الآية الكبرى التي جعلت المجمع يقرر قتله.","s":30,"pp":[["يسوع","jesus_905"],["مريم","mary_1939"],["لعازر","lazarus_1812"]],"ll":["بيت عنيا"]},{"i":"last-supper","k":"b","e":"life-of-christ","y":33,"t":"العشاء الأخير وجثسيماني","j":30,"r":[["Luk",22,null,22,null],["Joh",13,null,17,null]],"d":312,"l":"أورشليم وجبل الزيتون","x":"في الفصح يغسل يسوع أرجل تلاميذه ويعطيهم الخبز والكأس، العهد الجديد بدمه. وفي جثسيماني يصلي بجهاد: «لتكن لا إرادتي بل إرادتك»، ثم يُسلَّم بقبلة.","s":30,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"]},{"i":"crucifixion","k":"b","e":"life-of-christ","y":33,"t":"الصلب","j":30,"r":[["Mat",27,null,27,null],["Mar",15,null,15,null],["Luk",23,null,23,null],["Joh",19,null,19,null],["Isa",53,null,53,null]],"d":314,"l":"الجلجثة، أورشليم","x":"يُحكم على يسوع في أيام بيلاطس البنطي ويُصلب بين لصين، والظلمة تغطي الأرض وحجاب الهيكل ينشق. «قد أُكمل»: حمل الله الذي يرفع خطية العالم. (يؤرخ الدارسون هذا الفصح بسنة ٣٠ أو ٣٣ م).","s":30,"pp":[["يسوع","jesus_905"],["مريم","mary_1940"],["أم ابني زبدي","mother_of_zebedees_children_2112"],["يوسف","joseph_1716"],["بيلاطس البنطي","pilate_2365"],["سالومة","salome_2464"]],"ll":["جلجثة"],"kx":"يُسلَّم يسوع بيد يهوذا، ويُقبض عليه، ويُحاكم أمام رؤساء اليهود ثم أمام الرومان، ويُصلب في الجلجثة في وقت الفصح: حمل الله الذي يرفع خطية العالم. ويرى العهد الجديد في موته تحقيقًا لنبوات ورموز كثيرة: العبد المتألم (إشعياء ٥٣)، وخروف الفصح، والحية النحاسية. حمل الخطية وأكمل الفداء. وفي اليوم الثالث قام بالجسد من الأموات، غالبًا الخطية والموت. والقيامة تثبت أنه المسيح، وتُعلن قبول الآب لذبيحته، وتضمن قيامة المؤمنين. «المسيح مات من أجل خطايانا... وأنه دُفن وأنه قام في اليوم الثالث» (كورنثوس الأولى ١٥: ٣–٤)."},{"i":"resurrection","k":"b","e":"life-of-christ","y":33,"t":"القيامة","j":30,"r":[["Mat",28,null,28,null],["Joh",20,null,20,null]],"d":316,"l":"أورشليم","x":"في أول الأسبوع يوجد القبر فارغًا. ويسوع المقام يظهر لمريم المجدلية وللاثني عشر ولأكثر من خمس مئة أخ دفعة واحدة: الحدث الذي يقوم عليه الإيمان المسيحي كله.","s":30,"pp":[["يسوع","jesus_905"],["مريم","mary_1940"],["سالومة","salome_2464"],["توما","thomas_2851"]],"ll":["أورشليم","جبل الزيتون","بحر الجليل"]},{"i":"ascension","k":"b","e":"life-of-christ","y":33,"t":"الصعود والإرسالية العظمى","j":30,"r":[["Mat",28,18,28,20],["Act",1,1,1,11]],"d":316,"l":"جبل الزيتون","x":"بعد أربعين يومًا من الظهورات، يرسل يسوع تلاميذه: «اذهبوا وتلمذوا جميع الأمم»، ويصعد إلى يمين الآب، مع الوعد بأنه سيأتي هكذا كما رأوه منطلقًا.","s":30,"pp":[["يسوع","jesus_905"],["الله","god_1324"]],"ll":["جبل الزيتون"],"kx":"بعد أربعين يومًا من القيامة يصعد يسوع بالجسد إلى السماء من جبل الزيتون والتلاميذ ينظرون، ويعد الملاكان بأنه «سيأتي هكذا كما رأيتموه منطلقًا إلى السماء» (أعمال ١: ١١). والصعود هو تمجيد المسيح وجلوسه عن يمين الآب، حيث يملك ويشفع في المؤمنين ويسكب الروح القدس الموعود. لم يكن ذهابه تخليًا عن تلاميذه، بل كان لازمًا لمجيء الروح وبداية عصر الكنيسة (يوحنا ١٦: ٧). وجلوسه عن اليمين تحقيق للمزمور ١١٠: ١، وأساس خدمته الكهنوتية الدائمة (عبرانيين ٧–١٠)."},{"i":"t438","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"يسوع يعلّم في عبر الأردن","r":[["Mat",19,1,20,28],["Mar",10,1,10,45],["Luk",18,15,18,34]],"s":30.4002,"d":303,"pp":[["يسوع","jesus_905"]],"x":"ينتقل يسوع من الجليل إلى تخوم اليهودية عبر الأردن. يجيب عن سؤال الطلاق، ويبارك الأولاد: «دعوا الأولاد يأتون إليّ»، ويقابل الشاب الغني، ويضرب مثل الفعلة في الكرم، وينبئ للمرة الثالثة بموته. وحين يطلب ابنا زبدي الجلوس عن يمينه ويساره يقول: «ابن الإنسان لم يأتِ ليُخدم بل ليَخدم وليبذل نفسه فدية عن كثيرين».","xs":1},{"i":"t439","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"شفاء بارتيماوس الأعمى","r":[["Mat",20,29,20,34],["Mar",10,46,10,52],["Luk",18,35,18,43]],"s":30.4002,"d":303,"pp":[["يسوع","jesus_905"],["بارتيماوس","bartimaeus_406"]],"ll":["أريحا"],"x":"عند الخروج من أريحا يصرخ بارتيماوس الأعمى الجالس على الطريق: «يا يسوع ابن داود، ارحمني». ينتهره كثيرون فيصرخ أكثر. فيقف يسوع ويسأله: «ماذا تريد أن أفعل بك؟»، فيقول: «أن أبصر»، فيقول: «اذهب، إيمانك قد شفاك»، فيبصر للوقت ويتبعه في الطريق.","xs":1},{"i":"t445","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"تطهير الهيكل","r":[["Mat",21,12,21,17],["Mar",11,15,11,19],["Luk",19,45,19,48]],"s":30.4002,"d":304,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"بعد دخوله أورشليم يدخل يسوع الهيكل ويُخرج الذين كانوا يبيعون ويشترون، ويقلب موائد الصيارفة: «بيتي بيت الصلاة يُدعى، وأنتم جعلتموه مغارة لصوص». ويشفي العمي والعرج في الهيكل، والأولاد يصرخون «أوصنا لابن داود»، فيطلب رؤساء الكهنة والكتبة كيف يهلكونه.","xs":1},{"i":"t448","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"المجادلات في الهيكل","r":[["Mat",21,23,23,39],["Mar",11,27,12,44],["Luk",20,1,21,4]],"s":30.4002,"d":304,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"],"x":"في الأيام الأخيرة قبل الصلب تأتي إليه في الهيكل أسئلة متتالية: بأي سلطان تفعل هذا؟ هل تحل الجزية لقيصر؟ وسؤال الصدوقيين عن القيامة، وأي وصية هي العظمى. ويضرب أمثال الابنين والكرامين الأردياء وعرس ابن الملك، ثم يعلن الويلات على الكتبة والفريسيين، ويمدح الأرملة التي ألقت فلسين.","xs":1},{"i":"t449","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"حديث جبل الزيتون","r":[["Mat",24,1,25,46],["Mar",13,1,13,37],["Luk",21,5,21,36]],"s":30.4002,"d":308,"pp":[["سمعان","peter_2745"],["يعقوب","james_717"],["يوحنا","john_1677"],["أندراوس","andrew_264"],["يسوع","jesus_905"]],"ll":["جبل الزيتون"],"x":"حين يُري التلاميذ يسوع أبنية الهيكل يقول: «لا يُترك ههنا حجر على حجر لا يُنقض». وعلى جبل الزيتون يسألونه عن العلامات، فيتكلم عن الحروب والمجاعات والمسحاء الكذبة والضيق العظيم ومجيء ابن الإنسان على سحاب السماء، ويوصي بالسهر بأمثال العذارى العشر والوزنات، ويصف الدينونة حين يفصل الخراف عن الجداء.","xs":1},{"i":"t450","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"مؤامرة رؤساء الكهنة","r":[["Mat",26,1,26,5],["Mar",14,1,14,2],["Luk",22,1,22,2]],"s":30.4003,"d":312,"pp":[["قيافا","caiaphas_532"]],"ll":["أورشليم"],"x":"قبل الفصح بيومين يجتمع رؤساء الكهنة والكتبة وشيوخ الشعب إلى دار رئيس الكهنة قيافا، ويتشاورون لكي يمسكوا يسوع بمكر ويقتلوه. لكنهم يقولون: «ليس في العيد لئلا يكون شغب في الشعب».","xs":1},{"i":"t451","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"يهوذا يتفق على تسليم يسوع","r":[["Mat",26,14,26,16],["Mar",14,10,14,11],["Luk",22,3,22,6]],"s":30.4003,"d":312,"pp":[["يهوذا","judas_1760"]],"ll":["أورشليم"],"x":"يذهب يهوذا الإسخريوطي، أحد الاثني عشر، إلى رؤساء الكهنة ويقول: «ماذا تريدون أن تعطوني وأنا أسلمه إليكم؟»، فيجعلون له ثلاثين من الفضة. ويقول لوقا إن الشيطان دخل في يهوذا، ومن ذلك الوقت كان يطلب فرصة ليسلمه.","xs":1},{"i":"t454","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"الصلاة في جثسيماني والقبض على يسوع","r":[["Mat",26,36,26,56],["Mar",14,32,14,52],["Luk",22,39,22,53],["Joh",18,1,18,12]],"s":30.4003,"d":312,"pp":[["يسوع","jesus_905"],["يهوذا","judas_1760"],["سمعان","peter_2745"]],"ll":["جثسيماني"],"x":"في جثسيماني يقول يسوع: «نفسي حزينة جدًا حتى الموت»، ويصلي: «يا أبتاه، إن أمكن فلتعبر عني هذه الكأس، ولكن ليس كما أريد أنا بل كما تريد أنت»، والتلاميذ نيام. ثم يأتي يهوذا مع جمع بسيوف وعصي ويسلّمه بقبلة. يضرب بطرس عبد رئيس الكهنة بالسيف، فيقول له يسوع أن يرد سيفه، ويتركه التلاميذ كلهم ويهربون.","xs":1},{"i":"t455","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"المحاكمة أمام رؤساء اليهود","r":[["Mat",26,57,27,2],["Mar",14,53,14,72],["Luk",22,54,22,71],["Joh",18,13,18,27]],"s":30.4003,"d":312,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"],["قيافا","caiaphas_532"]],"ll":["أورشليم"],"x":"يمضون بيسوع إلى قيافا رئيس الكهنة، ويطلبون شهادة زور. يسأله رئيس الكهنة: «أأنت المسيح ابن الله؟»، فيجيب: «أنت قلت... من الآن تبصرون ابن الإنسان جالسًا عن يمين القوة»، فيحكمون أنه مستوجب الموت ويبصقون في وجهه. وفي الدار ينكره بطرس ثلاث مرات ويصيح الديك، فيخرج ويبكي بكاءً مرًّا.","xs":1},{"i":"t457","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"يهوذا يشنق نفسه","r":[["Mat",27,3,27,10]],"s":30.4003,"d":314,"pp":[["يسوع","jesus_905"],["يهوذا","judas_1760"]],"ll":["أورشليم"],"x":"لما رأى يهوذا أن يسوع قد دين ندم، وردّ الثلاثين من الفضة قائلًا: «قد أخطأت إذ سلمت دمًا بريئًا». فطرح الفضة في الهيكل ومضى وخنق نفسه. واشترى رؤساء الكهنة بالفضة حقل الفخاري مقبرة للغرباء، وسُمي «حقل الدم».","xs":1},{"i":"t456","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"المحاكمة أمام بيلاطس وهيرودس","r":[["Mat",27,11,27,31],["Mar",15,1,15,20],["Luk",23,1,23,25],["Joh",18,28,19,16]],"s":30.4003,"d":314,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"],["بيلاطس البنطي","pilate_2365"],["باراباس","barabbas_399"]],"ll":["أورشليم"],"x":"يسأل بيلاطس يسوع: «أأنت ملك اليهود؟»، ويرسله إلى هيرودس الذي يحتقره ويستهزئ به ثم يرده. يحاول بيلاطس إطلاقه، لكن الجمع يطلب باراباس ويصرخ: «اصلبه!». فيغسل بيلاطس يديه ويسلّمه بعد أن يجلده، ويُلبسه العسكر رداء قرمزيًا وإكليلًا من شوك ويستهزئون به.","xs":1},{"i":"t458","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"حمل الصليب إلى الجلجثة","r":[["Mat",27,32,27,34],["Mar",15,21,15,23],["Luk",23,26,23,32],["Joh",19,17,19,17]],"s":30.4003,"d":314,"pp":[["يسوع","jesus_905"],["سمعان","simon_2749"]],"ll":["جلجثة"],"x":"وهم خارجون يسخّرون سمعان القيرواني ليحمل الصليب. وتتبعه نساء يلطمن وينحن، فيقول لهن: «يا بنات أورشليم، لا تبكين عليّ بل ابكين على أنفسكن». ويأتون به إلى الجلجثة، أي موضع الجمجمة، ومعه مذنبان آخران.","xs":1},{"i":"t446","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"لعن شجرة التين","r":[["Mar",11,11,11,14],["Mat",21,18,21,19]],"s":30.4101,"d":304,"pp":[["يسوع","jesus_905"]],"ll":["جبل الزيتون"],"x":"في الطريق من بيت عنيا يجوع يسوع، فيرى شجرة تين عليها ورق، فيأتي فلا يجد فيها إلا ورقًا. فيقول لها: «لا يأكل أحد منك ثمرًا بعد إلى الأبد». وكان هذا عملًا رمزيًا قبل تطهير الهيكل مباشرة.","xs":1},{"i":"t447","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"درس شجرة التين اليابسة","r":[["Mar",11,20,11,26],["Mat",21,20,21,22]],"s":30.4101,"d":304,"pp":[["يسوع","jesus_905"],["سمعان","peter_2745"]],"ll":["جبل الزيتون"],"x":"في الصباح يرون التينة يابسة من الأصول، فيتعجب بطرس. فيقول يسوع: «ليكن لكم إيمان بالله»، ويعلّم أن من يؤمن ولا يشك يحرك الجبال، وأن كل ما يطلبونه في الصلاة مؤمنين ينالونه، ويوصيهم أن يغفروا إذا وقفوا يصلون.","xs":1},{"i":"t436","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"شفاء العشرة البرص","r":[["Luk",17,11,17,19]],"s":30.4202,"d":300,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"بين السامرة والجليل يستقبله عشرة رجال برص، يقفون من بعيد ويصرخون: «يا يسوع يا معلم ارحمنا». يقول لهم: «اذهبوا وأروا أنفسكم للكهنة»، وفيما هم منطلقون يطهرون. يرجع واحد منهم فقط ليمجد الله ويشكره، وكان سامريًا، فيقول يسوع: «أليس العشرة قد طهروا؟ فأين التسعة؟».","xs":1},{"i":"t437","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"تعليم عن مجيء الملكوت وأمثال أخرى","r":[["Luk",17,20,18,14]],"s":30.4202,"d":300,"pp":[["يسوع","jesus_905"]],"ll":["الجليل"],"x":"يسأل الفريسيون متى يأتي ملكوت الله، فيقول: «لا يأتي ملكوت الله بمراقبة... ها ملكوت الله داخلكم». ثم يتكلم عن مجيء ابن الإنسان بغتة كأيام نوح ولوط: «اذكروا امرأة لوط». ويضرب مثل قاضي الظلم والأرملة اللحوح، ومثل الفريسي والعشار الذي قال: «اللهم ارحمني أنا الخاطئ».","xs":1},{"i":"t440","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"إيمان زكا ومثل الأمناء","r":[["Luk",19,1,19,28]],"s":30.4202,"d":302,"pp":[["يسوع","jesus_905"],["زكا","zacchaeus_2961"]],"ll":["أريحا"],"x":"في أريحا يصعد زكا رئيس العشارين إلى جميزة ليرى يسوع، فيقول له: «أسرع وانزل، لأنه ينبغي أن أمكث اليوم في بيتك». يتوب زكا ويعد أن يعطي نصف أمواله للمساكين ويرد أربعة أضعاف. ثم يضرب يسوع مثل الأمناء العشرة لأنهم كانوا يظنون أن ملكوت الله عتيد أن يظهر في الحال.","xs":1},{"i":"t432","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"التعليم والشفاء في الطريق إلى أورشليم","r":[["Joh",10,40,10,42],["Luk",13,22,17,10]],"s":30.4301,"d":296,"pp":[["يسوع","jesus_905"]],"ll":["الأردن"],"x":"يمضي يسوع إلى عبر الأردن حيث كان يوحنا يعمّد، فيؤمن به كثيرون هناك. وفي الطريق نحو أورشليم يعلّم عن الباب الضيق، ويبكي على أورشليم، ويشفي رجلًا مستسقيًا، ويضرب أمثال العشاء العظيم والخروف الضال والدرهم المفقود والابن الضال والوكيل الظالم والغني ولعازر.","xs":1},{"i":"t434","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"رؤساء الكهنة يتشاورون لقتل يسوع","r":[["Joh",11,47,11,53]],"s":30.4301,"d":301,"pp":[["قيافا","caiaphas_532"]],"ll":["أورشليم"],"x":"بعد إقامة لعازر يجمع رؤساء الكهنة والفريسيون مجمعًا: «إن تركناه هكذا يؤمن الجميع به، فيأتي الرومانيون». فيقول قيافا: «خير لنا أن يموت إنسان واحد عن الشعب ولا تهلك الأمة كلها»، ويشرح يوحنا أنه تنبأ دون أن يدري بأن يسوع سيموت عن الأمة. ومن ذلك اليوم تشاوروا ليقتلوه.","xs":1},{"i":"t435","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"يسوع يمضي إلى أفرايم","r":[["Joh",11,54,11,57]],"s":30.4301,"d":301,"pp":[["يسوع","jesus_905"]],"ll":["أفرايم"],"x":"لم يعد يسوع يمشي بين اليهود علانية، بل يمضي إلى الكورة القريبة من البرية، إلى مدينة يقال لها أفرايم، ويمكث هناك مع تلاميذه. واقترب الفصح، والناس يتساءلون في الهيكل هل يأتي إلى العيد، والرؤساء قد أمروا أن من يعرف مكانه يخبرهم.","xs":1},{"i":"t441","k":"b","e":"life-of-christ","y":33,"j":30,"est":1,"t":"مريم تدهن يسوع في بيت عنيا","r":[["Joh",12,1,12,11]],"s":30.4301,"d":301,"pp":[["يسوع","jesus_905"],["مريم","mary_1939"],["مرثا","martha_1937"],["لعازر","lazarus_1812"]],"ll":["بيت عنيا"],"x":"قبل الفصح بستة أيام يصنعون ليسوع عشاء في بيت عنيا، ومرثا تخدم ولعازر من المتكئين. تأخذ مريم منًا من طيب ناردين خالص كثير الثمن وتدهن قدمي يسوع وتمسحهما بشعرها، فيمتلئ البيت من رائحة الطيب. يعترض يهوذا، فيقول يسوع: «اتركوها، إنها ليوم تكفيني قد حفظته».","xs":1},{"i":"triumphal-entry","k":"b","e":"life-of-christ","y":33,"t":"الدخول الانتصاري إلى أورشليم","j":33,"r":[["Mat",21,1,21,11],["Zec",9,9,9,9]],"d":304,"l":"أورشليم","x":"يسوع يدخل أورشليم راكبًا على جحش كما تنبأ زكريا، والجموع تفرش سعف النخل وتصرخ: «أوصنا لابن داود!»: أحد الشعانين وبداية أسبوع الآلام.","s":33,"pp":[["يسوع","jesus_905"]],"ll":["أورشليم"]},{"i":"pentecost","k":"b","e":"early-church","y":33,"t":"يوم الخمسين: انسكاب الروح","j":30,"r":[["Act",2,null,2,null]],"d":317,"l":"أورشليم","x":"بعد خمسين يومًا من القيامة ينزل الروح القدس بصوت ريح وألسنة كأنها من نار، والتلاميذ يتكلمون بعظائم الله بلغة كل زائر. بطرس يعظ ويعتمد نحو ثلاثة آلاف نفس: ميلاد الكنيسة.","s":30,"pp":[["سمعان","peter_2745"]],"ll":["أورشليم"],"kx":"بعد خمسين يومًا من الفصح والقيامة ينزل الروح القدس في يوم الخمسين بصوت كهبوب ريح عاصفة وألسنة كأنها من نار، فيتكلم التلاميذ بألسنة يفهمها الزائرون من كل الأمم. ويعظ بطرس فيعتمد نحو ثلاثة آلاف نفس، وتولد الكنيسة. تحقق في ذلك نبوة يوئيل (يوئيل ٢: ٢٨–٣٢) ووعد يسوع بالمعزي (يوحنا ١٤–١٦). ويرى كثيرون في يوم الخمسين عكسًا لبابل: اللغات التي فرّقت البشر صارت وسيلة لجمعهم حول الإنجيل، في جماعة واحدة تتخطى حدود الشعوب."},{"i":"t306","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"اختيار متياس بدل يهوذا","r":[["Act",1,12,1,26]],"s":30.44,"d":317,"pp":[["متياس","matthias_1972"],["برسابا","barsabas_1720"],["مريم","mary_1938"],["لباوس","lebbaeus_1815"],["سمعان","simon_2746"],["حلفى","alphaeus_192"],["متى","matthew_1971"],["برثولماوس","bartholomew_405"],["توما","thomas_2851"],["فيلبس","philip_2344"],["أندراوس","andrew_264"],["يوحنا","john_1677"],["يعقوب","james_718"]],"ll":["أورشليم"],"x":"بعد الصعود يرجع التلاميذ إلى أورشليم ويواظبون على الصلاة في العلية، وكان عددهم نحو مئة وعشرين. يقوم بطرس ويقول إنه ينبغي أن يأخذ آخر وظيفة يهوذا، فيقيمون اثنين: يوسف المدعو برسابا ومتياس، ويصلّون ثم يلقون قرعة فتقع على متياس، فيُحسب مع الأحد عشر رسولًا.","xs":1},{"i":"t309","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"الكنيسة تنمو","r":[["Act",2,42,2,47]],"s":30.44,"d":317,"ll":["أورشليم"],"x":"يواظب المؤمنون الجدد على تعليم الرسل والشركة وكسر الخبز والصلوات، وتُجرى عجائب وآيات كثيرة على أيدي الرسل. وكانوا يبيعون الأملاك ويقسمونها حسب احتياج كل واحد، ويكسرون الخبز في البيوت بابتهاج وبساطة قلب، «وكان الرب كل يوم يضم إلى الكنيسة الذين يخلصون».","xs":1},{"i":"t310","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"شفاء الأعرج عند باب الجميل","r":[["Act",3,1,3,10]],"s":30.44,"d":318,"pp":[["يوحنا","john_1677"],["سمعان","peter_2745"]],"ll":["الباب الجميل"],"x":"يصعد بطرس ويوحنا إلى الهيكل في ساعة الصلاة التاسعة، فيطلب منهما صدقة رجل أعرج من بطن أمه عند الباب الذي يقال له الجميل. يقول بطرس: «ليس لي فضة ولا ذهب، ولكن الذي لي فإياه أعطيك: باسم يسوع المسيح الناصري قم وامشِ»، فيقوم ويدخل الهيكل ماشيًا وطافرًا ومسبحًا الله.","xs":1},{"i":"t311","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"بطرس يعظ في رواق سليمان","r":[["Act",3,11,3,26]],"s":30.44,"d":318,"pp":[["سمعان","peter_2745"]],"ll":["رواق سليمان"],"x":"يجتمع الشعب مندهشين في رواق سليمان، فيقول بطرس إن هذا لم يكن بقوتهما، بل باسم يسوع الذي أنكروه وقتلوه، «ورئيس الحياة قتلتموه، الذي أقامه الله من الأموات». ويدعوهم: «توبوا وارجعوا لتُمحى خطاياكم»، ويذكّرهم بأن يسوع هو النبي الذي تكلم عنه موسى.","xs":1},{"i":"t312","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"محاكمة بطرس ويوحنا","r":[["Act",4,1,4,22]],"s":30.44,"d":318,"pp":[["يوحنا","john_1677"],["الروح القدس","holy_spirit_7400"],["سمعان","peter_2745"],["الإسكندر","alexander_187"],["قيافا","caiaphas_532"],["حنان","annas_269"]],"ll":["أورشليم"],"x":"يقبض الكهنة وقائد جند الهيكل والصدوقيون على بطرس ويوحنا، ومع ذلك يصير عدد المؤمنين نحو خمسة آلاف. وأمام المجمع يقول بطرس: «ليس بأحد غيره الخلاص». فيتعجب الرؤساء من مجاهرتهما وهما «عديما العلم وعاميان»، ويعرفون أنهما كانا مع يسوع، ويأمرونهما ألا يتكلما باسمه، فيقولان: «إن كان حقًا أمام الله أن نسمع لكم أكثر من الله فاحكموا».","xs":1},{"i":"t313","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"المؤمنون يصلّون طالبين المجاهرة","r":[["Act",4,23,4,31]],"s":30.44,"d":318,"pp":[["الروح القدس","holy_spirit_7400"],["الله","god_1324"]],"ll":["أورشليم"],"x":"بعد إطلاق بطرس ويوحنا يرفع المؤمنون بنفس واحدة صوتًا إلى الله، ويذكرون المزمور الثاني عن ارتجاج الأمم على الرب وعلى مسيحه، ثم يطلبون: «امنح عبيدك أن يتكلموا بكلامك بكل مجاهرة». فيتزعزع المكان ويمتلئ الجميع من الروح القدس ويتكلمون بكلام الله بمجاهرة.","xs":1},{"i":"t314","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"كان عندهم كل شيء مشتركًا","r":[["Act",4,32,4,37]],"s":30.44,"d":318,"pp":[["برنابا","barnabas_1722"]],"ll":["أورشليم"],"x":"كان لجمهور المؤمنين قلب واحد ونفس واحدة، ولم يكن أحد يقول إن شيئًا من أمواله له، بل كان عندهم كل شيء مشتركًا، ولم يكن فيهم أحد محتاجًا. ومن هؤلاء يوسف الذي دعاه الرسل برنابا، اللاوي القبرسي، الذي باع حقلًا ووضع ثمنه عند أرجل الرسل.","xs":1},{"i":"t315","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"حنانيا وسفيرة","r":[["Act",5,1,5,11]],"s":30.4401,"d":318,"pp":[["الله","god_1324"],["الروح القدس","holy_spirit_7400"],["الشيطان","satan_2476"],["سمعان","peter_2745"],["سفيرة","sapphira_2472"],["حنانيا","ananias_258"]],"ll":["أورشليم"],"x":"يبيع حنانيا وامرأته سفيرة ملكًا ويختلسان من الثمن، ويضعان الباقي عند أرجل الرسل كأنه الكل. فيقول له بطرس: «أنت لم تكذب على الناس بل على الله»، فيسقط ويموت، وبعد نحو ثلاث ساعات تموت امرأته أيضًا. «فصار خوف عظيم على جميع الكنيسة».","xs":1},{"i":"t316","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"آيات وعجائب في رواق سليمان","r":[["Act",5,12,5,17]],"s":30.4401,"d":318,"pp":[["سمعان","peter_2745"]],"ll":["رواق سليمان"],"x":"تُجرى على أيدي الرسل آيات وعجائب كثيرة، وكان الجميع بنفس واحدة في رواق سليمان، ومؤمنون ينضمون للرب أكثر فأكثر. حتى كانوا يحملون المرضى إلى الشوارع لكي يقع ولو ظل بطرس على بعضهم، فيمتلئ رئيس الكهنة والصدوقيون غيرة.","xs":1},{"i":"t317","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"القبض على الرسل ومحاكمتهم","r":[["Act",5,18,5,33]],"s":30.4401,"d":318,"pp":[["سمعان","peter_2745"]],"ll":["أورشليم"],"x":"يضع الرؤساء الرسل في الحبس العام، لكن ملاك الرب يفتح أبواب السجن ليلًا ويقول: «اذهبوا قفوا وكلموا الشعب في الهيكل». ولما أُحضروا أمام المجمع وسُئلوا لماذا لم يطيعوا الأمر، أجاب بطرس والرسل: «ينبغي أن يُطاع الله أكثر من الناس»، فحنق الرؤساء وتشاوروا أن يقتلوهم.","xs":1},{"i":"t318","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"نصيحة غمالائيل وإطلاق الرسل","r":[["Act",5,34,5,42]],"s":30.4401,"d":318,"pp":[["غمالائيل","gamaliel_1277"]],"ll":["أورشليم"],"x":"يقوم غمالائيل، معلم الناموس المكرم عند الشعب، وينصح المجمع: «إن كان هذا الرأي أو هذا العمل من الناس فسوف ينتقض، وإن كان من الله فلا تقدرون أن تنقضوه». فيجلدون الرسل ويطلقونهم، فيذهبون فرحين لأنهم حُسبوا مستأهلين أن يُهانوا من أجل اسمه، ولا يكفّون عن التعليم كل يوم.","xs":1},{"i":"t319","k":"b","e":"early-church","y":33,"j":30,"est":1,"t":"اختيار السبعة للخدمة","r":[["Act",6,1,6,7]],"s":30.4401,"d":319,"pp":[["نيقولاوس","nicolas_2205"],["برميناس","parmenas_2272"],["تيمون","timon_2862"],["نيكانور","nicanor_2203"],["بروخورس","prochorus_2371"],["فيلبس","philip_2347"],["استفانوس","stephen_2802"],["الروح القدس","holy_spirit_7400"]],"ll":["أورشليم"],"x":"يتذمر اليونانيون من المؤمنين على العبرانيين لأن أراملهم كن يُغفل عنهن في الخدمة اليومية. فيطلب الرسل اختيار سبعة رجال مشهود لهم ومملوئين من الروح القدس والحكمة، فيختارون استفانوس وفيلبس وبروخورس ونيكانور وتيمون وبرميناس ونيقولاوس، ويضع الرسل عليهم الأيادي. وكانت كلمة الله تنمو.","xs":1},{"i":"stephen-martyred","k":"b","e":"early-church","y":34,"t":"استفانوس أول الشهداء","j":30,"r":[["Act",6,null,7,null]],"d":319,"l":"أورشليم","x":"استفانوس، المملوء نعمة وقوة، يحاكم المجمع من تاريخ إسرائيل نفسه، ويرى ابن الإنسان قائمًا عن يمين الله. يُرجم وهو يصلي لأجل قاتليه، والشهود يخلعون ثيابهم عند رجلي شاب اسمه شاول.","s":30,"pp":[["استفانوس","stephen_2802"]],"ll":["أورشليم"]},{"i":"t323","k":"b","e":"early-church","y":34,"j":31,"est":1,"t":"شاول يضطهد الكنيسة","r":[["Act",8,1,8,3]],"s":31.4401,"d":320,"pp":[["بولس","paul_2479"],["استفانوس","stephen_2802"]],"ll":["أورشليم"],"x":"كان شاول راضيًا بقتل استفانوس، وحدث في ذلك اليوم اضطهاد عظيم على الكنيسة في أورشليم، فتشتت الجميع في كور اليهودية والسامرة ما عدا الرسل. ويحمل رجال أتقياء استفانوس ويعملون عليه مناحة عظيمة، أما شاول فكان يسطو على الكنيسة ويدخل البيوت ويجر رجالًا ونساء إلى السجن.","xs":1},{"i":"t324","k":"b","e":"early-church","y":34,"j":31,"est":1,"t":"فيلبس يكرز في السامرة","r":[["Act",8,4,8,25]],"s":31.4401,"d":320,"pp":[["الروح القدس","holy_spirit_7400"],["يوحنا","john_1677"],["سمعان","peter_2745"],["سيمون","simon_2752"],["فيلبس","philip_2347"]],"ll":["السامرة"],"x":"يجول المشتتون مبشرين بالكلمة، وينزل فيلبس إلى مدينة من السامرة ويكرز بالمسيح، وتصاحب كرازته آيات، فيكون فرح عظيم. ويؤمن سيمون الساحر ويعتمد. ثم يأتي بطرس ويوحنا ويصليان فيقبل السامريون الروح القدس، وحين يقدم سيمون دراهم ليأخذ هذا السلطان يقول له بطرس: «لتكن فضتك معك للهلاك».","xs":1},{"i":"conversion-of-saul","k":"b","e":"early-church","y":35,"t":"إيمان شاول","j":32,"r":[["Act",9,null,9,null]],"d":320,"l":"طريق دمشق","x":"أشد مضطهدي الكنيسة يُعمى بنور من السماء: «شاول، شاول، لماذا تضطهدني؟». الفريسي يصير بولس، الإناء المختار ليحمل اسم المسيح أمام الأمم.","s":32,"pp":[["الروح القدس","holy_spirit_7400"],["حنانيا","ananias_259"],["بولس","paul_2479"]],"ll":["الزقاق المستقيم","دمشق"],"kx":"شاول الطرسوسي، الفريسي الغيور ومضطهد المسيحيين، يلتقي المسيح المقام على طريق دمشق، فيُعمى ويتضع، ثم يتحول إلى بولس الرسول، الأداة الأولى لحمل الإنجيل إلى الأمم. إيمانه شاهد على نعمة الله التي تغلب مقاومة الإنسان. وتعليمه اليهودي العميق مع الإعلان المباشر من المسيح أهّلاه لشرح الإيمان المسيحي بوضوح. ورسائله، وهي جزء كبير من العهد الجديد، تشرح التبرير بالإيمان والاتحاد بالمسيح والكنيسة جسد المسيح والحياة المسيحية."},{"i":"t325","k":"b","e":"early-church","y":35,"j":32,"est":1,"t":"إيمان الخصي الحبشي","r":[["Act",8,26,8,40]],"s":32.4401,"d":320,"pp":[["الروح القدس","holy_spirit_7400"],["كنداكة","candace_916"],["فيلبس","philip_2347"]],"ll":["غزة"],"x":"يرسل ملاك الرب فيلبس إلى الطريق النازلة من أورشليم إلى غزة، فيجد رجلًا حبشيًا خصيًا وزيرًا لكنداكة ملكة الحبشة، يقرأ في إشعياء: «مثل شاة سيق إلى الذبح». يسأله: «ألعلك تفهم ما أنت تقرأ؟»، ويبشره بيسوع من هذا الكتاب، فيعمّده، ويخطف الروح فيلبس، ويذهب الخصي في طريقه فرحًا.","xs":1},{"i":"cornelius","k":"b","e":"early-church","y":40,"t":"الإنجيل يصل إلى الأمم","j":38,"r":[["Act",10,null,10,null]],"d":321,"l":"قيصرية","x":"برؤيا على السطح: «ما طهره الله لا تدنسه أنت»، يدخل بطرس بيت قائد المئة الروماني كرنيليوس. الروح القدس يحل على أمميين غير مختونين، وينفتح باب الإيمان للأمم.","s":38,"pp":[["الروح القدس","holy_spirit_7400"],["سمعان","simon_2753"],["كرنيليوس","cornelius_956"]],"ll":["يافا","قيصرية"]},{"i":"t327","k":"b","e":"early-church","y":40,"j":38,"est":1,"t":"شاول يكرز بالمسيح","r":[["Act",9,20,9,31]],"s":38.4401,"d":320,"pp":[["الروح القدس","holy_spirit_7400"],["برنابا","barnabas_1722"],["بولس","paul_2479"]],"ll":["طرسوس","قيصرية","دمشق","أورشليم"],"x":"للوقت يكرز شاول في المجامع بالمسيح أن هذا هو ابن الله، فيتحير اليهود في دمشق ويتشاورون ليقتلوه، فيدليه التلاميذ ليلًا من السور في سل. وفي أورشليم يخاف منه التلاميذ حتى يأخذه برنابا إلى الرسل. ثم يرسلونه إلى طرسوس، وتكون للكنائس سلام وتُبنى وتتكاثر.","xs":1},{"i":"t328","k":"b","e":"early-church","y":40,"j":38,"est":1,"t":"بطرس يشفي إينياس ويقيم طابيثا","r":[["Act",9,32,9,43]],"s":38.4401,"d":320,"pp":[["سمعان","simon_2753"],["غزالة","dorcas_2810"],["إينياس","aeneas_106"]],"ll":["يافا","شارون","لدة"],"x":"في لدة يجد بطرس إنسانًا اسمه إينياس مضطجعًا مفلوجًا منذ ثماني سنين، فيقول له: «يا إينياس، يشفيك يسوع المسيح. قم»، فيقوم. وفي يافا تموت تلميذة اسمها طابيثا (غزالة) كانت ممتلئة أعمالًا صالحة، فيأتي بطرس ويصلي ويقول: «يا طابيثا قومي»، فتفتح عينيها، ويؤمن كثيرون بالرب.","xs":1},{"i":"t330","k":"b","e":"early-church","y":40,"j":38,"est":1,"t":"بطرس يكرز للأمم في قيصرية","r":[["Act",10,34,10,48]],"s":38.4401,"d":321,"pp":[["الروح القدس","holy_spirit_7400"],["سمعان","peter_2745"]],"ll":["قيصرية"],"x":"في بيت كرنيليوس يقول بطرس: «بالحق أنا أجد أن الله لا يقبل الوجوه، بل في كل أمة الذي يتقيه ويصنع البر مقبول عنده». وبينما هو يتكلم عن يسوع يحل الروح القدس على جميع السامعين، فيندهش المؤمنون من أهل الختان، ويأمر بطرس أن يعتمدوا باسم الرب.","xs":1},{"i":"t331","k":"b","e":"early-church","y":40,"j":38,"est":1,"t":"بطرس يدافع عن خلاص الأمم","r":[["Act",11,1,11,18]],"s":38.4401,"d":321,"pp":[["سمعان","peter_2745"]],"ll":["أورشليم"],"x":"يخاصم أهل الختان بطرس في أورشليم لأنه دخل إلى رجال غير مختونين وأكل معهم. فيشرح لهم الأمر بالترتيب: الرؤيا، والرجال المرسلون، وحلول الروح القدس عليهم «كما علينا أيضًا في البداءة»، ويقول: «فمن أنا؟ أقادر أن أمنع الله؟». فيسكتون ويمجدون الله: «إذًا أعطى الله الأمم أيضًا التوبة للحياة».","xs":1},{"i":"claudius-britain","k":"w","e":"early-church","y":43,"t":"روما تغزو بريطانيا","l":"بريطانيا","x":"الإمبراطور كلوديوس يبدأ غزو بريطانيا ويضمها إلى الإمبراطورية. وخلال عقود تصل طرق روما ومدنها إلى أطراف العالم المعروف، ومعها في النهاية الإنجيل.","s":43},{"i":"james-martyred","k":"b","e":"early-church","y":44,"t":"قتل يعقوب وإنقاذ بطرس من السجن","j":40,"r":[["Act",12,null,12,null]],"d":322,"l":"أورشليم","x":"هيرودس أغريباس الأول يقتل يعقوب أخا يوحنا بالسيف، أول من مات من الاثني عشر، ويقبض على بطرس. لكن ملاكًا يُخرج بطرس من السجن مارًّا بالحراس بينما الكنيسة تصلي.","s":40,"pp":[["يعقوب","james_719"],["رودا","rhoda_2439"],["مريم","mary_1941"],["سمعان","peter_2745"],["هيرودس أغريباس","herod_1506"]],"ll":["اليهودية"]},{"i":"t332","k":"b","e":"early-church","y":44,"j":40,"est":1,"t":"دُعي التلاميذ مسيحيين أولًا في أنطاكية","r":[["Act",11,19,11,30]],"s":40.4401,"d":321,"pp":[["أغابوس","agabus_107"],["بولس","paul_2479"],["برنابا","barnabas_1722"]],"ll":["أنطاكية"],"x":"يصل المشتتون إلى فينيقية وقبرس وأنطاكية، وبعضهم يكلم اليونانيين مبشرين بالرب يسوع، فيؤمن عدد كثير. يُرسل برنابا إلى أنطاكية فيفرح، ثم يأتي بشاول من طرسوس، ويعلّمان سنة كاملة، «ودُعي التلاميذ مسيحيين في أنطاكية أولًا». وحين يتنبأ أغابوس بجوع يرسلون معونة إلى الإخوة في اليهودية.","xs":1},{"i":"first-missionary-journey","k":"b","e":"early-church","y":46,"t":"رحلة بولس التبشيرية الأولى","ye":48,"j":45,"r":[["Act",13,null,14,null]],"d":322,"l":"قبرس وغلاطية","x":"يُرسل بولس مع برنابا من أنطاكية، فيكرز في قبرس وجنوب آسيا الصغرى ويؤسس كنائس في مدينة بعد أخرى. يُرجم في لسترة ويُترك ظنًّا أنه مات، لكنه يكمل.","s":45,"pp":[["برنابا","barnabas_1722"],["يوحنا","mark_1679"],["بولس","paul_2479"]],"ll":["إيقونية","أنطاكية","بافوس","أورشليم","بمفيلية","برجة"],"kx":"قام بولس بثلاث رحلات تبشيرية كبرى في آسيا الصغرى واليونان، وأسس كنائس في مدن رئيسية مثل أنطاكية وأفسس وفيلبي وكورنثوس وتسالونيكي. كان يحاور في المجامع، ويناقش الفلاسفة في أثينا، ويصنع المعجزات، ويحتمل الاضطهاد، ويكتب رسائل تعالج قضايا التعليم والحياة. وكانت طريقته تجمع بين الكرازة والتلمذة وإقامة الشيوخ ومتابعة الكنائس بالرسائل والمرسلين. وتحقق في رحلاته أمر المسيح بالشهادة «إلى أقصى الأرض»، ويسجل سفر الأعمال تقدّم الإنجيل رغم كل مقاومة. «لكنني لست أحتسب لشيء، ولا نفسي ثمينة عندي، حتى أتمم بفرح سعيي» (أعمال ٢٠: ٢٤)."},{"i":"t336","k":"b","e":"early-church","y":48,"j":45,"est":1,"t":"موت هيرودس","r":[["Act",12,20,12,23]],"s":45.4401,"d":322,"pp":[["هيرودس أغريباس","herod_1506"]],"ll":["قيصرية"],"x":"في يوم معيّن يلبس هيرودس الحلة الملوكية ويخاطب أهل صور وصيدا، فيصرخ الشعب: «هذا صوت إله لا صوت إنسان». ففي الحال يضربه ملاك الرب لأنه لم يعطِ المجد لله، فيصير يأكله الدود ويموت. «وأما كلمة الله فكانت تنمو وتزيد».","xs":1},{"i":"t337","k":"b","e":"early-church","y":48,"j":45,"est":1,"t":"إفراز برنابا وشاول للخدمة","r":[["Act",12,24,13,3]],"s":45.4401,"d":322,"pp":[["الروح القدس","holy_spirit_7400"],["مناين","manaen_1926"],["لوكيوس","lucius_1833"],["سمعان","simeon_2744"],["يوحنا","mark_1679"],["بولس","paul_2479"],["برنابا","barnabas_1722"]],"ll":["أنطاكية"],"x":"في الكنيسة بأنطاكية أنبياء ومعلمون: برنابا وسمعان الذي يدعى نيجر ولوكيوس القيرواني ومناين وشاول. وبينما هم يخدمون الرب ويصومون يقول الروح القدس: «أفرزوا لي برنابا وشاول للعمل الذي دعوتهما إليه». فيصومون ويصلون ويضعون عليهما الأيادي ويطلقونهما.","xs":1},{"i":"t339","k":"b","e":"early-church","y":48,"j":45,"est":1,"t":"برنابا وشاول في قبرس","r":[["Act",13,4,13,12]],"s":45.4401,"d":322,"pp":[["عليم","elymas_403"],["بولس","paul_2479"],["برنابا","barnabas_1722"],["سرجيوس","sergius_2502"],["يوحنا","mark_1679"]],"ll":["بافوس","سلاميس","قبرس","سلوكية"],"x":"ينزل برنابا وشاول إلى سلوكية ثم يسافران إلى قبرس، ويناديان في مجامع سلاميس ومعهما يوحنا مرقس. وفي بافوس يقاومهما عليم الساحر محاولًا أن يفسد الوالي سرجيوس بولس عن الإيمان، فيمتلئ شاول، الذي هو بولس، من الروح القدس ويعلن عليه العمى إلى حين، فيؤمن الوالي مندهشًا من تعليم الرب.","xs":1},{"i":"jerusalem-council","k":"b","e":"early-church","y":49,"t":"مجمع أورشليم","j":46,"r":[["Act",15,null,15,null]],"d":323,"l":"أورشليم","x":"هل يجب على المؤمنين من الأمم أن يحفظوا ناموس موسى؟ الرسل والمشايخ يحكمون بوضوح: الخلاص بنعمة الرب يسوع وحدها. الإنجيل لن يكون فرعًا من الناموس.","s":46,"pp":[["سيلا","silas_2740"],["يهوذا","judas_1759"],["يعقوب","james_719"],["سمعان","peter_2745"],["برنابا","barnabas_1722"],["بولس","paul_2479"]],"ll":["أورشليم"],"kx":"ثار خلاف: هل يجب على المؤمنين من الأمم أن يُختتنوا ويحفظوا ناموس موسى؟ اجتمع الرسل والمشايخ في أورشليم. روى بطرس كيف قبل الله الأمم بالإيمان في بيت كرنيليوس، وأخبر بولس وبرنابا بما صنعه الله بين الأمم، واستشهد يعقوب بنبوة عاموس ٩ عن دخول الأمم. وحكم المجمع ألا يُثقَّل على الأمم بالختان والناموس، بل يمتنعون عن أمور محددة حفاظًا على الشركة مع المؤمنين من اليهود. وثبّت القرار أن الخلاص «بنعمة الرب يسوع» (أعمال ١٥: ١١)، وأن الكنيسة مفتوحة لكل الأمم."},{"i":"t341","k":"b","e":"early-church","y":49,"j":46,"est":1,"t":"الخدمة في إيقونية","r":[["Act",14,1,14,5]],"s":46.4401,"d":322,"pp":[["بولس","paul_2479"],["برنابا","barnabas_1722"]],"ll":["إيقونية"],"x":"في إيقونية يدخلان مجمع اليهود ويتكلمان حتى يؤمن جمهور كثير من اليهود واليونانيين. لكن اليهود غير المؤمنين يغرون نفوس الأمم، فينشق جمهور المدينة. يمكثان زمانًا طويلًا يجاهران والرب يشهد بآيات وعجائب، ثم يهربان حين يعلمان بمحاولة لرجمهما.","xs":1},{"i":"t342","k":"b","e":"early-church","y":49,"j":46,"est":1,"t":"الخدمة في لسترة ودربة","r":[["Act",14,6,14,20]],"s":46.4401,"d":322,"pp":[["برنابا","barnabas_1722"],["بولس","paul_2479"]],"ll":["دربة","لسترة"],"x":"في لسترة يشفي بولس رجلًا عاجز الرجلين مقعدًا من بطن أمه، فيظن الجمع أنهما إلهان: يدعون برنابا «زفس» وبولس «هرمس»، ويريد كاهن زفس أن يذبح لهما. فيمزقان ثيابهما: «نحن أيضًا بشر تحت آلام مثلكم». ثم يأتي يهود من أنطاكية وإيقونية فيرجمون بولس ويجرونه خارج المدينة ظانين أنه مات، لكنه يقوم ويخرج مع برنابا إلى دربة.","xs":1},{"i":"t343","k":"b","e":"early-church","y":49,"j":46,"est":1,"t":"الرجوع إلى أنطاكية سوريا","r":[["Act",14,21,14,28]],"s":46.4401,"d":322,"pp":[["برنابا","barnabas_1722"],["بولس","paul_2479"]],"ll":["أنطاكية","برجة","أتالية","بمفيلية","بيسيدية","إيقونية","لسترة"],"x":"يرجع بولس وبرنابا إلى لسترة وإيقونية وأنطاكية يشددان أنفس التلاميذ: «بضيقات كثيرة ينبغي أن ندخل ملكوت الله»، وينتخبان لهم قسوسًا في كل كنيسة. ثم يرجعان إلى أنطاكية ويخبران بكل ما صنع الله معهما «وأنه فتح للأمم باب الإيمان».","xs":1},{"i":"gospel-to-europe","k":"b","e":"early-church","y":49,"t":"الإنجيل يصل إلى أوروبا","ye":52,"j":53,"r":[["Act",16,null,18,null]],"d":323,"l":"فيلبي وتسالونيكي وأثينا وكورنثوس","x":"بعد رؤيا رجل مكدوني يدعوه، يعبر بولس إلى أوروبا: سجان فيلبي يؤمن في نصف الليل، وبولس يحاور الفلاسفة في أريوس باغوس بأثينا، ويعلّم سنة وستة أشهر في كورنثوس.","s":53,"pp":[["بولس","paul_2479"],["يسوع","jesus_905"],["الله","god_1324"],["سيلا","silas_2740"],["تيموثاوس","timotheus_2863"],["ياسون","jason_742"]],"ll":["مكدونية","أثينا","تسالونيكي","أريوس باغوس"]},{"i":"t346","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"افتراق بولس وبرنابا","r":[["Act",15,35,15,39]],"s":47.4402,"d":323,"pp":[["يوحنا","mark_1679"],["برنابا","barnabas_1722"],["بولس","paul_2479"]],"ll":["قبرس","أنطاكية"],"x":"يقترح بولس على برنابا أن يرجعا ويفتقدا الإخوة في كل مدينة. يريد برنابا أن يأخذ معهما يوحنا مرقس، لكن بولس يرى ألا يأخذاه لأنه فارقهما من بمفيلية. فيحصل بينهما مشاجرة حتى يفارق أحدهما الآخر، فيأخذ برنابا مرقس ويسافر إلى قبرس.","xs":1},{"i":"t348","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"بداية الرحلة التبشيرية الثانية","r":[["Act",15,40,15,41]],"s":47.4402,"d":323,"pp":[["سيلا","silas_2740"],["بولس","paul_2479"]],"ll":["أرام","كيليكية","أنطاكية"],"x":"يختار بولس سيلا ويخرج مستودعًا من الإخوة إلى نعمة الله، ويجتاز في سورية وكيليكية يشدد الكنائس. وتبدأ بذلك الرحلة التي ستحمل الإنجيل إلى أوروبا.","xs":1},{"i":"t349","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"تيموثاوس ينضم إلى بولس وسيلا","r":[["Act",16,1,16,5]],"s":47.4402,"d":323,"pp":[["بولس","paul_2479"],["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"]],"ll":["لسترة","دربة"],"x":"في دربة ولسترة يجد بولس تلميذًا اسمه تيموثاوس، ابن امرأة يهودية مؤمنة وأبوه يوناني، مشهودًا له من الإخوة. يأخذه بولس معه ويختنه من أجل اليهود الذين في تلك الأماكن، ويسلّمون الكنائس قرارات مجمع أورشليم، «فكانت الكنائس تتشدد في الإيمان وتزداد في العدد كل يوم».","xs":1},{"i":"t350","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"عبر فريجية وغلاطية","r":[["Act",16,6,16,8]],"s":47.4402,"d":323,"pp":[["تيموثاوس","timotheus_2863"],["بولس","paul_2479"],["سيلا","silas_2740"],["الروح القدس","holy_spirit_7400"]],"ll":["ترواس","ميسيا","أسيا","غلاطية","فريجية"],"x":"يجتاز بولس ورفقاؤه في فريجية وكورة غلاطية، ويمنعهم الروح القدس أن يتكلموا بالكلمة في أسيا. ولما حاولوا أن يذهبوا إلى بثينية لم يدعهم الروح، فيجتازون ميسيا وينحدرون إلى ترواس.","xs":1},{"i":"t351","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"رؤيا الرجل المكدوني","r":[["Act",16,9,16,12]],"s":47.4402,"d":323,"pp":[["بولس","paul_2479"],["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"],["لوقا","luke_1836"]],"ll":["فيلبي","نيابوليس","ساموثراكي","ترواس","مكدونية"],"x":"يرى بولس في الليل رؤيا: رجل مكدوني قائم يطلب إليه: «اعبر إلى مكدونية وأعنا». فيطلبون الخروج في الحال متحققين أن الرب دعاهم، ويبدأ لوقا هنا يكتب بصيغة «نحن» علامة على انضمامه. ويقلعون إلى ساموثراكي ثم نيابوليس ثم فيلبي، أول مدينة من مقاطعة مكدونية.","xs":1},{"i":"t352","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"إيمان ليدية","r":[["Act",16,13,16,15]],"s":47.4402,"d":323,"pp":[["بولس","paul_2479"],["ليدية","lydia_1837"],["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"],["لوقا","luke_1836"]],"ll":["فيلبي"],"x":"في يوم السبت يخرجون إلى خارج المدينة عند نهر حيث جرت العادة أن تكون صلاة، ويكلمون النساء المجتمعات. وكانت هناك امرأة اسمها ليدية، بياعة أرجوان من ثياتيرا متعبدة لله، «ففتح الرب قلبها لتصغي إلى ما كان يقوله بولس»، فتعتمد هي وأهل بيتها وتلزمهم أن يمكثوا في بيتها.","xs":1},{"i":"t353","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"إخراج روح العرافة","r":[["Act",16,16,16,18]],"s":47.4402,"d":323,"pp":[["بولس","paul_2479"],["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"],["لوقا","luke_1836"]],"ll":["فيلبي"],"x":"تستقبلهم جارية بها روح عرافة، كانت تكسب مواليها مكسبًا كثيرًا، وتتبعهم أيامًا كثيرة صارخة: «هؤلاء الناس هم عبيد الله العلي». فيتضجر بولس ويلتفت إلى الروح قائلًا: «أنا آمرك باسم يسوع المسيح أن تخرج منها»، فيخرج في تلك الساعة.","xs":1},{"i":"t354","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"سجن بولس وسيلا","r":[["Act",16,19,16,34]],"s":47.4402,"d":323,"pp":[["سيلا","silas_2740"],["بولس","paul_2479"]],"ll":["فيلبي"],"x":"لما رأى موالي الجارية أنه قد خرج رجاء مكسبهم، أمسكوا بولس وسيلا وجروهما إلى السوق أمام الحكام قائلين إنهما يبلبلان المدينة. فيمزق الولاة ثيابهما ويأمرون أن يُضربا بالعصي، ويُلقيان في السجن الداخلي وتُضبط أرجلهما في المقطرة.","xs":1},{"i":"t355","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"إيمان سجان فيلبي","r":[["Act",16,25,16,34]],"s":47.4402,"d":323,"pp":[["سيلا","silas_2740"],["بولس","paul_2479"]],"ll":["فيلبي"],"x":"نحو نصف الليل كان بولس وسيلا يصليان ويسبحان الله والمسجونون يسمعونهما، فتحدث زلزلة عظيمة وتنفتح الأبواب. يهمّ السجان أن يقتل نفسه، فيصرخ بولس: «لا تفعل بنفسك شيئًا رديًا، لأن جميعنا ههنا». فيسأل: «ماذا ينبغي أن أفعل لكي أخلص؟»، فيقولان: «آمن بالرب يسوع المسيح فتخلص أنت وأهل بيتك»، ويعتمد هو وأهله في الحال.","xs":1},{"i":"t356","k":"b","e":"early-church","y":50,"j":47,"est":1,"t":"إطلاق بولس وسيلا","r":[["Act",16,35,16,40]],"s":47.4402,"d":323,"pp":[["ليدية","lydia_1837"],["بولس","paul_2479"],["سيلا","silas_2740"]],"ll":["فيلبي"],"x":"في الصباح يرسل الولاة ليُطلق الرجلان، فيقول بولس: «ضربونا جهرًا غير مقضي علينا ونحن رجلان رومانيان... فليأتوا هم أنفسهم ويخرجونا». فيخاف الولاة حين يسمعون أنهما رومانيان، ويأتون ويتضرعون إليهما أن يخرجا من المدينة. فيدخلان بيت ليدية ويعزيان الإخوة ثم يخرجان.","xs":1},{"i":"t357","k":"b","e":"early-church","y":51,"j":48,"est":1,"t":"الشغب في تسالونيكي","r":[["Act",17,1,17,9]],"s":48.4402,"d":324,"pp":[["ياسون","jason_742"],["سيلا","silas_2740"],["بولس","paul_2479"]],"ll":["تسالونيكي"],"x":"في تسالونيكي يحاج بولس اليهود في المجمع ثلاثة سبوت من الكتب أن المسيح كان ينبغي أن يتألم ويقوم، فيقتنع بعضهم وجمهور كثير من اليونانيين. لكن اليهود يغارون ويجمعون أشرارًا ويهيجون المدينة، ويجرون ياسون إلى الحكام صارخين: «إن هؤلاء الذين فتنوا المسكونة حضروا إلى ههنا أيضًا». فيرسل الإخوة بولس وسيلا ليلًا.","xs":1},{"i":"t358","k":"b","e":"early-church","y":51,"j":48,"est":1,"t":"الخدمة في بيرية","r":[["Act",17,10,17,15]],"s":48.4402,"d":324,"pp":[["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"],["بولس","paul_2479"]],"ll":["بيرية"],"x":"في بيرية كان اليهود «أشرف من الذين في تسالونيكي، فقبلوا الكلمة بكل نشاط فاحصين الكتب كل يوم: هل هذه الأمور هكذا؟». فيؤمن كثيرون منهم ومن اليونانيين. لكن يهودًا من تسالونيكي يأتون ويهيجون الجموع، فيرسل الإخوة بولس إلى أثينا، ويبقى سيلا وتيموثاوس هناك.","xs":1},{"i":"t359","k":"b","e":"early-church","y":51,"j":48,"est":1,"t":"بولس يكرز في أثينا","r":[["Act",17,16,17,34]],"s":48.4402,"d":324,"pp":[["دامرس","damaris_972"],["ديونيسيوس","dionysius_1013"],["بولس","paul_2479"]],"ll":["أريوس باغوس","أثينا"],"x":"تحتد روح بولس حين يرى أثينا مملوءة أصنامًا، فيحاور في المجمع وفي السوق كل يوم. ويأخذه الفلاسفة الأبيكوريون والرواقيون إلى أريوس باغوس، فيبدأ من مذبح مكتوب عليه «لإله مجهول»، ويقول: «لأننا به نحيا ونتحرك ونوجد»، ويدعوهم إلى التوبة لأن الله أقام يومًا للدينونة وأقام المسيح من الأموات. يستهزئ بعضهم، ويؤمن آخرون منهم ديونيسيوس الأريوباغي وامرأة اسمها دامرس.","xs":1},{"i":"t360","k":"b","e":"early-church","y":52,"j":49,"est":1,"t":"الخدمة في كورنثوس وكتابة رسالتي تسالونيكي","r":[["Act",18,1,18,17]],"s":49.4402,"d":324,"pp":[["سوستانيس","sosthenes_2772"],["غاليون","gallio_1275"],["كريسبس","crispus_961"],["يوستس","justus_1766"],["تيموثاوس","timotheus_2863"],["سيلا","silas_2740"],["بريسكلا","priscilla_2370"],["أكيلا","aquila_279"],["بولس","paul_2479"]],"ll":["أخائية","كورنثوس"],"x":"في كورنثوس يجد بولس أكيلا وبريسكلا، اليهوديين اللذين خرجا من رومية بأمر كلوديوس، ويعمل معهما في صناعة الخيام. وحين يقاومه اليهود يقول: «من الآن أذهب إلى الأمم»، ويؤمن كريسبس رئيس المجمع. ويقول له الرب في رؤيا: «لا تخف بل تكلم ولا تسكت... لأن لي شعبًا كثيرًا في هذه المدينة»، فيقيم سنة وستة أشهر، ويرفض غاليون والي أخائية دعوى اليهود عليه. ومن هنا يُرجَّح أنه كتب رسالتي تسالونيكي.","xs":1},{"i":"t347","k":"b","e":"early-church","y":52,"j":49,"est":1,"t":"بولس يكتب رسالة غلاطية","r":[["Gal",1,1,1,1]],"s":49.48,"d":326,"pp":[["بولس","paul_2479"]],"x":"يكتب بولس إلى كنائس غلاطية رسالة حادة يدافع فيها عن إنجيل النعمة ضد من يعلّمون أن الأمم يجب أن يختتنوا ويحفظوا الناموس: «إذ نعلم أن الإنسان لا يتبرر بأعمال الناموس بل بإيمان يسوع المسيح». ويضعها Theographic نحو ٤٩ م، لكن تاريخ كتابتها محل خلاف بين الدارسين، فبعضهم يضعها في منتصف الخمسينيات.","xs":1},{"i":"t361","k":"b","e":"early-church","y":53,"j":50,"est":1,"t":"الرجوع من الرحلة الثانية","r":[["Act",18,18,18,23]],"s":50.4402,"d":324,"pp":[["أكيلا","aquila_279"],["بريسكلا","priscilla_2370"],["بولس","paul_2479"]],"ll":["فريجية","غلاطية","قيصرية","أنطاكية","أفسس","أرام","كنخريا"],"x":"يلبث بولس أيامًا كثيرة في كورنثوس، ثم يودع الإخوة ويسافر إلى سورية ومعه بريسكلا وأكيلا، بعد أن حلق رأسه في كنخريا لأنه كان عليه نذر. ويمر بأفسس ويحاور اليهود ويعد بالرجوع «إن شاء الله»، ثم ينزل إلى قيصرية ويصعد ويسلم على الكنيسة، ثم ينحدر إلى أنطاكية.","xs":1},{"i":"t362","k":"b","e":"early-church","y":53,"j":50,"est":1,"t":"بداية الرحلة التبشيرية الثالثة","r":[["Act",18,24,18,28]],"s":50.4402,"d":324,"pp":[["بريسكلا","priscilla_2370"],["أكيلا","aquila_279"],["أبلوس","apollos_276"]],"ll":["أخائية","أفسس"],"x":"يأتي إلى أفسس يهودي اسمه أبلوس، إسكندري الجنس، رجل فصيح مقتدر في الكتب، لكنه لا يعرف إلا معمودية يوحنا. فيأخذه أكيلا وبريسكلا ويشرحان له طريق الرب بأكثر تدقيق، فيذهب إلى أخائية ويفحم اليهود جهرًا مبينًا بالكتب أن يسوع هو المسيح. وفي هذا الوقت يخرج بولس ويجتاز كورة غلاطية وفريجية يشدد التلاميذ.","xs":1},{"i":"ephesus-ministry","k":"b","e":"early-church","y":53,"t":"رحلة بولس الثالثة: أفسس","ye":57,"j":58,"r":[["Act",19,null,20,null]],"d":326,"l":"أفسس، آسيا الصغرى","x":"أكثر من سنتين يعلّم بولس كل يوم في أفسس حتى سمع «جميع الساكنين في أسيا» الكلمة. كتب السحر تُحرق، وصاغة الفضة صنّاع هياكل أرطاميس يثيرون الشغب، ومن هذه الفترة جاءت رسائل مثل كورنثوس الأولى ورومية.","s":58,"pp":[["بولس","paul_2479"],["يسوع","jesus_905"],["الله","god_1324"],["أرطاميس","diana_1008"],["الروح القدس","holy_spirit_7400"],["يوحنا","john_1676"]],"ll":["أفسس","أسيا","مكدونية","أورشليم"]},{"i":"t364","k":"b","e":"early-church","y":56,"j":53,"est":1,"t":"الخدمة في أفسس وكتابة كورنثوس الأولى","r":[["Act",19,1,19,22]],"s":53.4402,"d":326,"pp":[["أراستس","erastus_1213"],["تيموثاوس","timotheus_2863"],["سكاوا","sceva_2480"],["تيرانس","tyrannus_2886"],["بولس","paul_2479"]],"ll":["أسيا","أفسس"],"x":"في أفسس يجد بولس تلاميذ لم يسمعوا بالروح القدس، فيعتمدون باسم الرب يسوع ويحل الروح عليهم. يتكلم في المجمع ثلاثة أشهر ثم في مدرسة تيرانس سنتين، حتى سمع جميع الساكنين في أسيا كلمة الرب. وتُجرى على يديه قوات غير المعتادة، ويحرق كثيرون كتب السحر التي قُدرت بخمسين ألفًا من الفضة. ومن هنا كتب رسالة كورنثوس الأولى (١٦: ٨).","xs":1},{"i":"t365","k":"b","e":"early-church","y":56,"j":53,"est":1,"t":"الشغب في أفسس","r":[["Act",19,23,19,41]],"s":53.4402,"d":326,"pp":[["إسكندر","alexander_188"],["أرسترخس","aristarchus_306"],["غايوس","gaius_1269"],["بولس","paul_2479"],["ديمتريوس","demetrius_1007"]],"ll":["أسيا","أفسس"],"x":"يجمع ديمتريوس الصائغ، صانع هياكل فضة لأرطاميس، أصحاب الصناعة ويقول إن بولس يقنع الناس أن الآلهة المصنوعة بالأيدي ليست آلهة. فيمتلئون غضبًا ويصرخون نحو ساعتين في المسرح: «عظيمة هي أرطاميس الأفسسيين». ويهدّئ كاتب المدينة الجمع ويصرفهم.","xs":1},{"i":"t366","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"في مكدونية واليونان","r":[["Act",20,1,20,6]],"s":54.4402,"d":334,"pp":[["تروفيمس","trophimus_2880"],["تيخيكس","tychicus_2885"],["تيموثاوس","timotheus_2863"],["غايوس","gaius_1270"],["سكوندس","secundus_2482"],["أرسترخس","aristarchus_306"],["سوباترس","sopater_2770"],["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["فيلبي","ترواس","اليونان","مكدونية"],"x":"بعد الشغب يذهب بولس إلى مكدونية ويعظ الإخوة كثيرًا، ثم يأتي إلى اليونان ويقيم ثلاثة أشهر. وحين يكيد اليهود له يرجع عن طريق مكدونية، ويرافقه سوباترس وأرسترخس وسكوندس وغايوس وتيموثاوس وتيخيكس وتروفيمس، ثم يقلع من فيلبي بعد أيام الفطير إلى ترواس.","xs":1},{"i":"t367","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"إقامة أفتيخوس","r":[["Act",20,7,20,12]],"s":54.4402,"d":334,"pp":[["أفتيخوس","eutychus_1230"],["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["ترواس"],"x":"في أول الأسبوع يجتمع التلاميذ في ترواس ليكسروا خبزًا، ويطيل بولس الكلام إلى نصف الليل. يغلب النوم شابًا اسمه أفتيخوس كان جالسًا في الطاقة، فيسقط من الطبقة الثالثة ويُحمل ميتًا. ينزل بولس ويعتنقه ويقول: «لا تضطربوا لأن نفسه فيه»، ثم يكسر الخبز ويتكلم حتى الفجر، ويأتون بالفتى حيًا فيتعزون كثيرًا.","xs":1},{"i":"t368","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"الإبحار إلى ميليتس","r":[["Act",20,13,20,16]],"s":54.4402,"d":334,"pp":[["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["أسيا","خيوس","ميليتس","ساموس","ميتيليني","أسوس","تروجيليون"],"x":"يسافر رفقاء بولس بالسفينة إلى أسوس، ويمشي هو إليها برًا، ثم يقلعون إلى ميتيليني وخيوس وساموس وميليتس. وكان بولس قد عزم أن يتجاوز أفسس لئلا يضيع وقتًا في أسيا، لأنه كان يسرع ليكون في أورشليم في يوم الخمسين إن أمكن.","xs":1},{"i":"t369","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"بولس يكلم قسوس أفسس","r":[["Act",20,17,20,38]],"s":54.4402,"d":334,"pp":[["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["ميليتس"],"x":"يستدعي بولس قسوس كنيسة أفسس إلى ميليتس ويودعهم: يذكّرهم كيف خدم الرب بكل تواضع ودموع ولم يؤخر شيئًا من الفوائد، ويقول إن وثقًا وشدائد تنتظره. ويوصيهم: «احترزوا إذًا لأنفسكم ولجميع الرعية... لترعوا كنيسة الله التي اقتناها بدمه»، ويذكر قول الرب يسوع: «مغبوط هو العطاء أكثر من الأخذ». ثم يجثو ويصلي معهم، ويبكون جميعًا.","xs":1},{"i":"t370","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"من ميليتس إلى أورشليم","r":[["Act",21,1,21,17]],"s":54.4402,"d":334,"pp":[["مناسون","mnason_2102"],["أغابوس","agabus_107"],["فيلبس","philip_2347"],["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["اليهودية","قيصرية","بتولمايس","أورشليم","صور","أرام","قبرس","فينيقية","باترا","رودس","كوس"],"x":"يبحر بولس عبر كوس ورودس وباترا إلى صور، حيث يقول له التلاميذ بالروح ألا يصعد إلى أورشليم. وفي قيصرية في بيت فيلبس المبشر يأخذ النبي أغابوس منطقة بولس ويربط يديه ورجليه علامة على ما سيحدث له. يتوسلون إليه ألا يصعد فيقول: «إني مستعد ليس أن أُربط فقط بل أن أموت أيضًا في أورشليم لأجل اسم الرب يسوع»، فيسكتون قائلين: «لتكن مشيئة الرب».","xs":1},{"i":"t371","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"بولس عند يعقوب والمشايخ","r":[["Act",21,18,21,26]],"s":54.4402,"d":334,"pp":[["يعقوب","james_719"],["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["أورشليم"],"x":"يدخل بولس إلى يعقوب ويحضر جميع المشايخ، ويحدثهم بما فعله الله بين الأمم بواسطة خدمته فيمجدون الرب. لكنهم يخبرونه أن ربوات من اليهود المؤمنين غيورون للناموس، وقد سمعوا أنه يعلّم ترك موسى. فيشيرون عليه أن يتطهر مع أربعة رجال عليهم نذر ويدفع عنهم، فيفعل ويدخل الهيكل.","xs":1},{"i":"t372","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"القبض على بولس في الهيكل","r":[["Act",21,27,21,36]],"s":54.4402,"d":334,"pp":[["بولس","paul_2479"],["تروفيمس","trophimus_2880"]],"ll":["أورشليم"],"x":"يرى يهود من أسيا بولس في الهيكل فيهيجون الجمع صارخين: «هذا هو الرجل الذي يعلّم الجميع في كل مكان ضدًّا للشعب والناموس وهذا الموضع»، ظانين أنه أدخل تروفيمس الأفسسي إلى الهيكل. يجرّونه خارجًا ويطلبون قتله، فيأتي أمير الكتيبة بالعسكر وينقذه ويقيده بسلسلتين.","xs":1},{"i":"t373","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"بولس يروي قصة إيمانه","r":[["Act",21,37,22,29]],"s":54.4402,"d":334,"pp":[["بولس","paul_2479"]],"ll":["أورشليم"],"x":"على الدرج يستأذن بولس أن يكلم الشعب، ويخاطبهم باللغة العبرانية: يهودي من طرسوس، تربى عند رجلي غمالائيل، اضطهد هذا الطريق، ثم ظهر له الرب في طريق دمشق وأرسله إلى الأمم. وعند كلمة «الأمم» يصرخ الجمع، فيأمر الأمير بفحصه بالجلد، فيقول بولس: «أيجوز لكم أن تجلدوا إنسانًا رومانيًا غير مقضي عليه؟»، فيخاف الأمير.","xs":1},{"i":"t374","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"بولس أمام المجمع","r":[["Act",22,30,23,11]],"s":54.4402,"d":334,"pp":[["حنانيا","ananias_260"],["بولس","paul_2479"]],"ll":["أورشليم"],"x":"يقف بولس أمام المجمع ويقول إنه عاش بكل ضمير صالح أمام الله، فيأمر حنانيا رئيس الكهنة أن يضربوه على فمه. وحين يرى أن المجمع فريق منه صدوقيون وفريق فريسيون يصرخ: «على رجاء قيامة الأموات أنا أُحاكم»، فيحدث انشقاق شديد. وفي الليلة التالية يقف به الرب ويقول: «ثق يا بولس، لأنك كما شهدت بما لي في أورشليم هكذا ينبغي أن تشهد في رومية أيضًا».","xs":1},{"i":"t375","k":"b","e":"early-church","y":57,"j":54,"est":1,"t":"المؤامرة لقتل بولس","r":[["Act",23,12,23,22]],"s":54.4402,"d":335,"pp":[["بولس","paul_2479"]],"ll":["أورشليم"],"x":"يتحالف أكثر من أربعين رجلًا من اليهود على أنفسهم ألا يأكلوا ولا يشربوا حتى يقتلوا بولس، ويطلبون من رؤساء الكهنة أن يُحضروه إلى المجمع ليكمنوا له في الطريق. لكن ابن أخت بولس يسمع بالكمين فيخبر بولس ثم أمير الكتيبة.","xs":1},{"i":"paul-to-rome","k":"b","e":"early-church","y":57,"t":"القبض على بولس ورحلته إلى رومية","ye":60,"j":60,"r":[["Act",21,null,28,null]],"d":334,"l":"أورشليم ← قيصرية ← مليطة ← رومية","x":"يُقبض على بولس في الهيكل فيرفع دعواه إلى قيصر بصفته رومانيًا. وبعد سنتين في السجن ومحاكمات أمام الولاة وملك، وانكسار السفينة عند مليطة، يصل إلى رومية ويكرز بملكوت الله «بكل مجاهرة بلا مانع».","s":60,"pp":[["بولس","paul_2479"],["الله","god_1324"],["يسوع","jesus_905"],["فستوس","portius_2367"],["أغريباس","agrippa_111"],["فيلكس","felix_1257"]],"ll":["أورشليم","قيصرية","دمشق","كيليكية"]},{"i":"t376","k":"b","e":"early-church","y":59,"j":56,"est":1,"t":"إرسال بولس إلى فيلكس","r":[["Act",23,23,24,27]],"s":56.4402,"d":335,"pp":[["فستوس","portius_2367"],["دروسلا","drusilla_1024"],["ترتلس","tertullus_2844"],["حنانيا","ananias_260"],["كلوديوس","claudius_948"],["فيلكس","felix_1257"],["بولس","paul_2479"]],"ll":["أنتيباتريس","قيصرية"],"x":"يرسل الأمير بولس ليلًا بحراسة كبيرة إلى قيصرية مع رسالة إلى فيلكس الوالي. ويأتي حنانيا وترتلس الخطيب فيتهمونه بأنه «مفسد ومهيّج فتنة» ومقدام شيعة الناصريين، فيدافع بولس بأنه يعبد إله آبائه وله رجاء القيامة. ويسمعه فيلكس مع دروسلا امرأته، وحين يتكلم بولس عن البر والتعفف والدينونة العتيدة يرتعب فيلكس ويقول: «أما الآن فاذهب»، ويبقى بولس سجينًا سنتين.","xs":1},{"i":"t377","k":"b","e":"early-church","y":59,"j":56,"est":1,"t":"بولس يرفع دعواه إلى قيصر","r":[["Act",25,1,25,12]],"s":56.4403,"d":346,"pp":[["بولس","paul_2479"],["فستوس","portius_2367"]],"ll":["قيصرية"],"x":"يأتي فستوس واليًا جديدًا، ويطلب رؤساء اليهود أن يُحضر بولس إلى أورشليم وهم يكمنون ليقتلوه. وفي المحاكمة بقيصرية يسأله فستوس إن كان يريد أن يُحاكم في أورشليم، فيقول بولس: «أنا واقف لدى كرسي ولاية قيصر حيث ينبغي أن أُحاكم... إلى قيصر أنا رافع دعواي». فيجيب فستوس: «إلى قيصر رفعت دعواك، إلى قيصر تذهب».","xs":1},{"i":"t378","k":"b","e":"early-church","y":59,"j":56,"est":1,"t":"أغريباس وبرنيكي عند فستوس","r":[["Act",25,13,25,21]],"s":56.4403,"d":346,"pp":[["أوغسطس","augustus_366"],["بولس","paul_2479"],["فستوس","portius_2367"],["برنيكي","bernice_482"],["أغريباس","agrippa_111"]],"ll":["قيصرية"],"x":"يأتي أغريباس الملك وبرنيكي إلى قيصرية ليسلما على فستوس، فيعرض فستوس عليه أمر بولس: لم يجد فيه شيئًا من الشرور، بل مسائل في ديانتهم وعن «واحد اسمه يسوع قد مات، وكان بولس يقول إنه حي». فيقول أغريباس: «كنت أريد أنا أيضًا أن أسمع الإنسان».","xs":1},{"i":"t379","k":"b","e":"early-church","y":59,"j":56,"est":1,"t":"بولس أمام أغريباس","r":[["Act",25,22,26,32]],"s":56.4403,"d":346,"pp":[["أوغسطس","augustus_366"],["بولس","paul_2479"],["برنيكي","bernice_482"],["فستوس","portius_2367"],["أغريباس","agrippa_111"]],"ll":["قيصرية"],"x":"في احتفال كبير يقف بولس أمام أغريباس ويروي قصته: فريسي اضطهد المؤمنين، ثم نور من السماء أفضل من لمعان الشمس في طريق دمشق، وإرسالية الرب له إلى الأمم «لتفتح عيونهم كي يرجعوا من ظلمات إلى نور». يقول فستوس: «أنت تهذي يا بولس»، ويقول أغريباس: «بقليل تقنعني أن أصير مسيحيًا». ويتفقون أنه كان يمكن إطلاقه لو لم يرفع دعواه إلى قيصر.","xs":1},{"i":"t380","k":"b","e":"early-church","y":59,"j":56,"est":1,"t":"بداية الرحلة إلى رومية","r":[["Act",27,1,27,12]],"s":56.4403,"d":347,"pp":[["أرسترخس","aristarchus_306"],["يوليوس","julius_1763"],["بولس","paul_2479"],["لوقا","luke_1836"]],"ll":["فينكس","لسائية","المواني الحسنة","كريت","كنيدس","سلموني","الإسكندرية","كيليكية","ليكية","ميرا","بمفيلية","قبرس","صيدون","أسيا","أدراميتي","إيطاليا"],"x":"يُسلَّم بولس مع أسرى آخرين إلى قائد مئة اسمه يوليوس، ويبحرون في سفينة أدراميتية ومعهم أرسترخس ولوقا. يعاملهم يوليوس بالرفق في صيداء، ثم في ميرا ينقلهم إلى سفينة إسكندرية مسافرة إلى إيطاليا. ويسيرون ببطء حتى المواني الحسنة في كريت، وينذرهم بولس بأن السفر سيكون بضرر، لكن قائد المئة يصدّق ربان السفينة وصاحبها.","xs":1},{"i":"t382","k":"b","e":"early-church","y":60,"j":57,"est":1,"t":"العاصفة وانكسار السفينة","r":[["Act",27,13,27,44]],"s":57.4403,"d":347,"pp":[["بولس","paul_2479"],["يوليوس","julius_1763"],["أرسترخس","aristarchus_306"],["لوقا","luke_1836"]],"ll":["بحر أدريا","السيرتس","كلودي","كريت"],"x":"تهب ريح زوبعية يقال لها أوروكليدون، فتنجرف السفينة أيامًا كثيرة لا تظهر فيها شمس ولا نجوم، ويُنزع كل رجاء في النجاة. يقف بولس في وسطهم ويقول إن ملاك الله ظهر له وأكد أنه لا تكون خسارة نفس واحدة. وفي الليلة الرابعة عشرة يقتربون من البر، ويأكل الجميع، وكانوا مئتين وستة وسبعين نفسًا، ثم تنكسر السفينة ويصل الجميع إلى البر سالمين.","xs":1},{"i":"t383","k":"b","e":"early-church","y":60,"j":57,"est":1,"t":"بولس في مليطة","r":[["Act",28,1,28,10]],"s":57.4403,"d":347,"pp":[["بوبليوس","publius_2374"],["بولس","paul_2479"],["يوليوس","julius_1763"],["أرسترخس","aristarchus_306"],["لوقا","luke_1836"]],"ll":["مليطة"],"x":"يتبين أن الجزيرة اسمها مليطة، ويقدم أهلها لهم إحسانًا غير المعتاد. تخرج أفعى من النار وتنشب في يد بولس، فينفضها ولا يتضرر، فيظنونه إلهًا. ويشفي بولس أبا بوبليوس مقدم الجزيرة من الحمى والزحار، ثم يأتي باقي المرضى ويُشفون، ويكرمونهم ويزودونهم عند السفر بعد ثلاثة أشهر.","xs":1},{"i":"t384","k":"b","e":"early-church","y":60,"j":57,"est":1,"t":"بولس يصل إلى رومية","r":[["Act",28,11,28,16]],"s":57.4403,"d":347,"pp":[["بولس","paul_2479"],["يوليوس","julius_1763"],["أرسترخس","aristarchus_306"],["لوقا","luke_1836"]],"ll":["الثلاثة الحوانيت","فورن أبيوس","رومية","بوطيولي","ريغيون","سراكوسا"],"x":"يبحرون في سفينة إسكندرية شتّت في الجزيرة، ويمرون بسراكوسا وريغيون ثم بوطيولي حيث يجدون إخوة. ويأتي إخوة من رومية لملاقاتهم إلى فورن أبيوس والثلاثة الحوانيت، «فلما رآهم بولس شكر الله وتشجع». وفي رومية يُؤذن له أن يقيم وحده مع العسكري الذي كان يحرسه.","xs":1},{"i":"t385","k":"b","e":"early-church","y":60,"j":57,"est":1,"t":"سجن بولس الأول في رومية","r":[["Act",28,17,28,31]],"s":57.4403,"d":347,"pp":[["بولس","paul_2479"],["لوقا","luke_1836"],["ديماس","demas_1006"],["أبفراس","epaphras_1195"]],"ll":["رومية"],"x":"يستدعي بولس وجوه اليهود في رومية ويقول: «من أجل رجاء إسرائيل موثق بهذه السلسلة»، ويشرح لهم ملكوت الله من الصباح إلى المساء من ناموس موسى والأنبياء. يقتنع بعضهم ولا يؤمن آخرون، فيستشهد بإشعياء ويقول إن خلاص الله أُرسل إلى الأمم. ويقيم سنتين كاملتين في بيت استأجره، يقبل جميع الذين يدخلون إليه، كارزًا بملكوت الله ومعلّمًا عن الرب يسوع «بكل مجاهرة بلا مانع».","xs":1},{"i":"prison-epistles","k":"b","e":"early-church","y":60,"t":"كتابة رسائل السجن","ye":62,"r":[["Eph",1,null,1,null],["Phi",1,null,1,null],["Col",1,null,1,null],["Phm",1,null,1,null]],"d":348,"l":"رومية","x":"وهو تحت الحراسة في بيت في رومية، مقيدًا بجندي، يكتب بولس رسائل تحلّق بسمو المسيح: «لأن لي الحياة هي المسيح والموت هو ربح».","s":60,"pp":[["يسوع","jesus_905"],["الله","god_1324"]]},{"i":"gospels-written","k":"b","e":"early-church","y":60,"t":"كتابة الأناجيل","ye":95,"r":[["Mat",1,null,1,null],["Mar",1,null,1,null],["Luk",1,null,1,null],["Joh",1,null,1,null]],"d":274,"l":"أنحاء العالم الروماني","x":"في حياة من عاصروا الأحداث، تدوّن الأناجيل الأربعة شهادة الرسل عن حياة يسوع وموته وقيامته، والأرجح أن مرقس أولها ويوحنا آخرها، «لتؤمنوا».","s":60,"pp":[["يسوع","jesus_905"],["يوسف","joseph_1715"],["داود","david_994"],["إبراهيم","abraham_58"],["مريم","mary_1938"],["الله","god_1324"]],"ll":["بابل"],"kx":"في عصر الرسل كُتبت أسفار العهد الجديد بالوحي: رسائل بولس (نحو ٤٨–٦٥ م) شرحت الإيمان المسيحي، والأناجيل (نحو ٦٠–٩٠ م) سجلت حياة يسوع وموته وقيامته، وسفر الأعمال سجل انتشار الكنيسة، والعبرانيين ويعقوب وبطرس ويهوذا عالجت قضايا محددة، وكتابات يوحنا (نحو ٨٥–٩٥ م) قدّمت آخر شهادة رسولية. ومع نهاية القرن الأول كانت الأسفار قد اكتملت، وإن استغرق الاعتراف الرسمي بها وقتًا أطول. وبموت الرسل انتهت الفترة التأسيسية، وبقيت كتاباتهم مرجع الكنيسة الدائم."},{"i":"great-fire-rome","k":"w","e":"early-church","y":64,"t":"حريق روما الكبير ونيرون يتهم المسيحيين","l":"روما","x":"النار تلتهم عشرة من أحياء روما الأربعة عشر. ولكي يبعد الشبهة عن نفسه يجعل نيرون المسيحيين كبش فداء فيعذبهم ويحرقهم: أول اضطهاد إمبراطوري، سجله باشمئزاز حتى المؤرخ الوثني تاسيتوس.","s":64},{"i":"peter-paul-martyred","k":"b","e":"early-church","y":66,"t":"استشهاد بطرس وبولس","r":[["Joh",21,18,21,19]],"d":316,"l":"رومية","x":"بحسب شهادة الكنيسة الأولى يموت الرسولان في اضطهاد نيرون: بولس بقطع الرأس على الطريق الأوستي، وبطرس مصلوبًا (والتقليد يقول منكس الرأس) على تل الفاتيكان. «قد جاهدت الجهاد الحسن، أكملت السعي».","s":66,"pp":[["الله","god_1324"]]},{"i":"temple-destroyed","k":"b","e":"early-church","y":70,"t":"خراب أورشليم والهيكل","r":[["Luk",21,20,21,24]],"d":307,"l":"أورشليم","x":"روما تسحق الثورة اليهودية، وجيوش تيطس تحرق الهيكل فلا يُترك حجر على حجر، كما قال يسوع قبلها بنحو أربعين سنة. تتوقف الذبائح، ويفترق طريقا اليهودية والمسيحية.","s":70,"ll":["أورشليم","اليهودية"],"kx":"يحاصر الرومان بقيادة تيطس أورشليم ويخربونها ويهدمون الهيكل ويقتلون الآلاف. كان يسوع قد تنبأ بهذه الدينونة (متى ٢٤؛ لوقا ٢١)، وأوصى تلاميذه أن يهربوا حين يرون الجيوش محيطة بالمدينة. وبخراب الهيكل توقف نظام الذبائح نهائيًا، ويرى سفر العبرانيين أن ذبيحة المسيح الواحدة أغنت عنها، وأن العهد الأول «قريب من الاضمحلال» (عبرانيين ٨: ١٣). وكان هذا الحدث نقطة تحوّل كبيرة في تاريخ اليهود والكنيسة معًا."},{"i":"vesuvius","k":"w","e":"early-church","y":79,"t":"بركان فيزوف يدفن بومبي","l":"خليج نابولي، إيطاليا","x":"جبل فيزوف يثور فيدفن بومبي وهيركولانيوم تحت الرماد، ويحفظ مدينة رومانية بشوارعها وجدارياتها وأرغفة خبزها كما كانت في عصر الرسل.","s":79},{"i":"colosseum","k":"w","e":"early-church","y":80,"t":"اكتمال الكولوسيوم","l":"روما","x":"الإمبراطور تيطس يفتتح المدرج الفلافي بخمسين ألف مقعد، وقد مُوّل من غنائم خراب أورشليم وبُني جزئيًا بأيدي أسرى يهود، ويُحتفل بافتتاحه بمئة يوم من الألعاب.","s":80},{"i":"revelation","k":"b","e":"early-church","y":95,"t":"رؤيا يوحنا في بطمس","j":96,"r":[["Rev",1,null,22,null]],"d":361,"l":"جزيرة بطمس","x":"وهو منفي في أيام دوميتيان، يرى آخر الرسل الأحياء المسيح المقام في مجده، ويتسلم آخر أسفار الكتاب: رسائل إلى سبع كنائس، ودينونة ونصرة، وأورشليم الجديدة حيث يمسح الله كل دمعة.","s":96,"pp":[["الله","god_1324"],["يسوع","jesus_905"],["الروح القدس","holy_spirit_7400"],["الشيطان","satan_2476"],["يوحنا","john_1677"],["يعقوب","israel_682"]],"ll":["بابل","ساردس","ثياتيرا","أورشليم"]},{"i":"death-of-john","k":"b","e":"early-church","y":98,"t":"موت يوحنا ونهاية عصر الرسل","l":"أفسس","x":"بحسب التقليد القديم يموت يوحنا بسلام في أفسس قرب نهاية القرن، آخر شهود العيان ليسوع. ينتهي عصر الرسل، ويكتمل قانون الأسفار، وتمضي الكنيسة في التاريخ.","s":98},{"i":"trajan-emperor","k":"w","e":"early-church","y":98,"t":"تراجان إمبراطورًا","l":"روما","x":"في عهد تراجان تبلغ روما أقصى اتساعها. ومراسلته الشهيرة مع بليني الأصغر (نحو ١١٢ م) تقدم أقدم وصف من خارج الكنيسة لعبادة المسيحيين، إذ كانوا يرنمون «للمسيح كإله».","s":98}],"ar":{"Gen":"التكوين","Exo":"الخروج","Lev":"اللاويين","Num":"العدد","Deu":"التثنية","Jos":"يشوع","Jdg":"القضاة","Rut":"راعوث","1Sa":"صموئيل الأول","2Sa":"صموئيل الثاني","1Ki":"الملوك الأول","2Ki":"الملوك الثاني","1Ch":"أخبار الأيام الأول","2Ch":"أخبار الأيام الثاني","Ezr":"عزرا","Neh":"نحميا","Est":"أستير","Job":"أيوب","Psa":"المزامير","Pro":"الأمثال","Ecc":"الجامعة","Son":"نشيد الأنشاد","Isa":"إشعياء","Jer":"إرميا","Lam":"مراثي إرميا","Eze":"حزقيال","Dan":"دانيال","Hos":"هوشع","Joe":"يوئيل","Amo":"عاموس","Oba":"عوبديا","Jon":"يونان","Mic":"ميخا","Nah":"ناحوم","Hab":"حبقوق","Zep":"صفنيا","Hag":"حجي","Zec":"زكريا","Mal":"ملاخي","Mat":"متى","Mar":"مرقس","Luk":"لوقا","Joh":"يوحنا","Act":"أعمال الرسل","Rom":"رومية","1Co":"كورنثوس الأولى","2Co":"كورنثوس الثانية","Gal":"غلاطية","Eph":"أفسس","Phi":"فيلبي","Col":"كولوسي","1Th":"تسالونيكي الأولى","2Th":"تسالونيكي الثانية","1Ti":"تيموثاوس الأولى","2Ti":"تيموثاوس الثانية","Tit":"تيطس","Phm":"فليمون","Heb":"العبرانيين","Jam":"يعقوب","1Pe":"بطرس الأولى","2Pe":"بطرس الثانية","1Jo":"يوحنا الأولى","2Jo":"يوحنا الثانية","3Jo":"يوحنا الثالثة","Jud":"يهوذا","Rev":"الرؤيا"},"bio":{"adam_78":["أول إنسان خلقه الله، جبله من تراب الأرض ووضعه في جنة عدن. دعا أسماء الحيوانات، وأعطاه الله حواء معينًا نظيره. وبعد أن عصى وأكل من شجرة معرفة الخير والشر طُرد هو وحواء من الجنة. وهو أبو البشرية كلها. يمثّل آدم حالة الإنسان الأولى وسقوطه في الخطية، ومن هنا ظهرت الحاجة إلى الفداء الذي جاء بالمسيح، الذي يسميه بولس «آدم الأخير».",[["الله يجبله من تراب الأرض",["Gen",2,7,2,7]],["وضعه في جنة عدن",["Gen",2,15,2,15]],["خلق حواء",["Gen",2,21,2,22]],["ميلاد شيث",["Gen",5,3,5,3]],["موته",["Gen",5,5,5,5]]]],"noah_2210":["رجل بار في جيل فاسد، وجد نعمة في عيني الرب. ولما قرر الله أن يُغرق الأرض بسبب شر الإنسان، اختار نوحًا ليبني فلكًا يحفظ فيه عائلته وأنواع الحيوانات. وبعد الطوفان أقام الله عهدًا معه بألا يهلك الأرض بالماء مرة أخرى، وجعل قوس السحاب علامة له. تُظهر قصة نوح رحمة الله في وسط الدينونة وأمانته في حفظ بقية، ويرى العهد الجديد في الطوفان صورة للمعمودية والخلاص (بطرس الأولى ٣: ٢٠–٢١).",[["ميلاد سام وحام ويافث",["Gen",5,32,5,32]],["بداية الطوفان",["Gen",7,6,7,6]],["الخروج من الفلك",["Gen",8,13,8,19]],["موته",["Gen",9,29,9,29]]]],"abraham_58":["كان اسمه أولًا أبرام، ودعاه الله أن يترك أرضه ويذهب إلى كنعان، ووعده أن يجعله أمة عظيمة. ورغم شيخوخته هو وسارة أعطاهما الله إسحاق ابن الموعد. وأظهر إيمانًا عجيبًا حين أطاع أمر الله بتقديم إسحاق، فدبّر الله كبشًا عوضًا عنه. هو أبو الشعب العبراني و«أبو المؤمنين»، وعهد الله معه هو أساس قصة إسرائيل كلها وطريق مجيء المسيح.",[["الله يدعوه للخروج",["Gen",12,1,12,4]],["ميلاد إسماعيل من هاجر",["Gen",16,16,16,16]],["عهد الختان",["Gen",17,1,17,14]],["ميلاد إسحاق",["Gen",21,5,21,5]],["موت سارة",["Gen",23,1,23,1]],["موته",["Gen",25,7,25,7]]]],"moses_2108":["وُلد حين أمر فرعون بقتل أطفال العبرانيين الذكور، فخبأته أمه ثم تربى في بيت فرعون. وبعد أن قتل مصريًا وهرب إلى مديان، دعاه الله من العليقة ليخرج إسرائيل من عبودية مصر. وعلى يده أعطى الله الوصايا العشر والشريعة، وقاد الشعب أربعين سنة في البرية، لكنه لم يدخل أرض الموعد. هو المشرّع العظيم والنبي الوسيط في عهد الله مع إسرائيل، وهو رمز للمسيح النبي والمخلّص والوسيط.",[["ميلاده في مصر",["Exo",2,1,2,2]],["هروبه إلى مديان",["Act",7,23,7,29]],["دعوته عند العليقة",["Exo",3,1,3,10]],["الخروج من مصر",["Exo",12,31,12,42]],["استلام الوصايا العشر",["Exo",20,1,20,17]],["موته على جبل نبو",["Deu",34,5,34,7]]]],"david_994":["أصغر أبناء يسى، مُسح ملكًا وهو بعد راعٍ صغير. اشتهر بانتصاره على جليات الفلسطيني، وصار محاربًا وعازفًا في بلاط شاول. وبعد موت شاول وحّد إسرائيل وجعل أورشليم عاصمته. ورغم خطاياه، وأشهرها مع بثشبع، قيل عنه إنه «رجل حسب قلب الله»، ونال وعدًا بأن المسيا يأتي من نسله. أسس داود أورشليم والمُلك الذي يكتمل في المسيح «ابن داود»، ومزاميره صارت كتاب صلاة شعب الله عبر الأجيال.",[["صموئيل يمسحه ملكًا",["1Sa",16,13,16,13]],["انتصاره على جليات",["1Sa",17,49,17,51]],["ملكًا على يهوذا ثم على كل إسرائيل",["2Sa",5,4,5,5]],["أخذ أورشليم",["2Sa",5,6,5,9]],["خطيته مع بثشبع",["2Sa",11,null,11,null]],["موته",["1Ki",2,10,2,11]]]],"jesus_905":["وُلد من العذراء مريم في بيت لحم، وهو المسيح الموعود وابن الله. بدأ خدمته العلنية نحو سن الثلاثين، يعلّم عن ملكوت الله ويصنع المعجزات ويدعو التلاميذ. صُلب في أيام بيلاطس البنطي كفارة عن الخطية، وقام من الأموات في اليوم الثالث، وصعد إلى السماء بعد أربعين يومًا. هو الإله الكامل والإنسان الكامل، محور الكتاب المقدس كله وتاريخ البشر، ونسل المرأة الذي يسحق رأس الحية، وتتميم نبوات العهد القديم.",[["ميلاده في بيت لحم",["Luk",2,7,2,7]],["في الهيكل وهو صبي",["Luk",2,42,2,52]],["معموديته",["Luk",3,21,3,23]],["التجربة في البرية",["Mat",4,1,4,11]],["بداية خدمته في الجليل",["Luk",4,14,4,21]],["التجلي",["Mat",17,1,17,9]],["الصلب والقيامة",["Mat",27,null,28,null]],["الصعود",["Act",1,9,1,11]]]],"eve_1231":["أول امرأة، خلقها الله من ضلع آدم لتكون معينًا نظيره. أغوتها الحية فأكلت من الثمرة المنهي عنها وأعطت آدم أيضًا. ورغم دورها في السقوط فهي «أم كل حي»، وإليها جاء الوعد بأن نسلها يسحق رأس الحية. تمثل حواء ضعف الإنسان أمام التجربة، كما تحمل وعد الفداء الذي تم في المسيح.",[["خلقها من ضلع آدم",["Gen",2,21,2,22]],["التجربة من الحية",["Gen",3,1,3,6]],["الطرد من عدن",["Gen",3,23,3,24]],["ميلاد شيث",["Gen",4,25,4,25]]]],"ezra_1245":["كاهن وكاتب قاد الفوج الثاني من الراجعين من بابل إلى أورشليم نحو ٤٥٨ ق.م. كان مكرسًا لشريعة الله، وقاد إصلاحًا دينيًا في الجماعة بعد السبي. ولما وجد كثيرين قد تزوجوا من الشعوب الوثنية، قاد الشعب إلى التوبة وتجديد العهد. وقراءته للشريعة أمام الشعب كله أحدثت نهضة ورجوعًا إلى العبادة الصحيحة. أعاد عزرا كلمة الله إلى مركز حياة الشعب بعد السبي.",[["أرتحشستا يكلفه بالمهمة",["Ezr",7,11,7,26]],["قيادة الراجعين من بابل",["Ezr",7,6,7,10]],["اكتشاف الزيجات الغريبة",["Ezr",9,1,9,4]],["الاعتراف والتوبة",["Ezr",10,1,10,17]],["قراءة الشريعة أمام الشعب",["Neh",8,1,8,12]]]],"isaac_616":["ابن الموعد الذي وُلد لإبراهيم وسارة في شيخوختهما. كاد أن يُقدَّم ذبيحة في أعظم امتحان لإيمان أبيه، لكن الله دبّر كبشًا عوضًا عنه. تزوج رفقة وأنجب التوأمين عيسو ويعقوب. كان أهدأ من أبيه، لكنه حمل خط العهد بأمانة. إسحاق تتميم لوعد الله، وصورة للمسيح الابن المطيع المقدَّم ذبيحة.",[["ميلاده",["Gen",21,1,21,3]],["تقديمه على المذبح",["Gen",22,1,22,19]],["زواجه برفقة",["Gen",25,20,25,20]],["ميلاد عيسو ويعقوب",["Gen",25,26,25,26]],["موته",["Gen",35,28,35,29]]]],"israel_682":["الأصغر من توأمي إسحاق، أخذ بكورية عيسو ثم بركته بالحيلة. وهارب من غضب أخيه التقى الله في بيت إيل، وبعدها صارع الله ونال اسم إسرائيل. أنجب اثني عشر ابنًا صاروا أسباط إسرائيل. ورغم عيوب شخصيته اختاره الله ليحمل خط العهد. هو أبو الأسباط، وقصته تُظهر نعمة الله المختارة رغم عدم استحقاق الإنسان.",[["ميلاده ممسكًا بعقب عيسو",["Gen",25,24,25,26]],["أخذ البركة",["Gen",27,1,27,40]],["الرؤيا في بيت إيل",["Gen",28,10,28,22]],["زواجه بليئة وراحيل",["Gen",29,21,29,30]],["مصارعته وتغيير اسمه",["Gen",32,24,32,32]],["نزوله إلى مصر",["Gen",47,9,47,9]],["موته",["Gen",47,28,47,28]]]],"job_1639":["رجل بار غني من أرض عوص، سمح الله للشيطان أن يمتحن أمانته فخسر أولاده وأملاكه وصحته، واحتمل نصائح أصحابه الخاطئة، لكنه حافظ على كماله وإيمانه. وفي النهاية برّأه الله وردّ له ضعف ما كان له وأعطاه عائلة جديدة. يعالج سفر أيوب مسألة الألم، ويبيّن أن البر لا يُكافأ دائمًا بالنجاح في هذه الحياة، وأن الثقة في سلطان الله تبقى هي الأساس، ويشير إلى المسيح البار المتألم.",[["رجل كامل ومستقيم",["Job",1,1,1,1]],["خسارة أولاده وأملاكه",["Job",1,13,1,19]],["ضربه بقرح رديء",["Job",2,7,2,7]],["الحوار مع أصحابه",["Job",3,null,31,null]],["الرب يجيب من العاصفة",["Job",38,null,41,null]],["ردّ سبيه وبركته",["Job",42,10,42,17]]]],"joseph_1710":["الابن المحبوب ليعقوب، باعه إخوته الحاسدون عبدًا، لكنه بعناية الله صار الثاني في مملكة مصر. وتفسيره لحلمي فرعون أنقذ مصر وعائلته من المجاعة. ومسامحته لإخوته تُظهر نعمة عظيمة وثقة في خطة الله. حياة يوسف صورة للمسيح في آلامه ثم ارتفاعه وخلاصه لشعبه.",[["بيعه عبدًا",["Gen",37,28,37,28]],["سجنه في مصر",["Gen",39,20,39,20]],["صار على كل أرض مصر",["Gen",41,46,41,46]],["لقاؤه بإخوته",["Gen",45,1,45,15]],["موته",["Gen",50,26,50,26]]]],"solomon_2762":["ابن داود وبثشبع، صار ثالث ملوك إسرائيل، وأعطاه الله حكمة عظيمة. بنى الهيكل الفخم في أورشليم، وتُنسب إليه أجزاء كبيرة من الأمثال والجامعة ونشيد الأنشاد. لكن نساءه الغريبات الكثيرات أملن قلبه إلى عبادة الأوثان في آخر أيامه، فمهّد ذلك لانقسام المملكة. حكمته والهيكل الذي بناه يشيران إلى المسيح حكمة الله والهيكل الحقيقي.",[["جلوسه على العرش",["1Ki",2,12,2,12]],["طلب الحكمة",["1Ki",3,5,3,14]],["بدء بناء الهيكل",["1Ki",6,1,6,1]],["تدشين الهيكل",["1Ki",8,1,8,66]],["موته",["1Ki",11,42,11,43]]]],"cain_533":["بكر آدم وحواء، كان عاملًا في الأرض وقدّم من ثمارها قربانًا للرب. ولما لم ينظر الله إلى قربانه ونظر إلى قربان هابيل، اغتاظ وقتل أخاه في الحقل. واجهه الله ولعنه ليكون تائهًا في الأرض، وجعل له علامة لحمايته. وبنى أول مدينة وسماها باسم ابنه حنوك. تُظهر قصته كيف تصاعدت الخطية بعد السقوط، وعمق فساد الإنسان بعيدًا عن نعمة الله.",[["ميلاده",["Gen",4,1,4,1]],["قربانه المرفوض",["Gen",4,3,4,5]],["قتله هابيل",["Gen",4,8,4,8]],["اللعنة والعلامة",["Gen",4,11,4,15]],["بناء مدينة حنوك",["Gen",4,17,4,17]]]],"abel_13":["الابن الثاني لآدم وحواء، كان راعيًا للغنم وقدّم من أبكار غنمه قربانًا للرب، فنظر الرب إلى قربانه لأنه قُدّم بالإيمان. قتله أخوه قايين حسدًا، فصرخ دمه من الأرض، وصار أول شهيد. ويمدح العهد الجديد إيمانه (عبرانيين ١١: ٤)، وذبيحته المقبولة بالإيمان تشير إلى ذبيحة المسيح الكاملة.",[["ميلاده",["Gen",4,2,4,2]],["قربانه المقبول",["Gen",4,4,4,4]],["قتله",["Gen",4,8,4,8]],["صوت دمه يصرخ",["Gen",4,10,4,10]]]],"enoch_1192":["من نسل شيث، سار مع الله ثلاث مئة سنة بعد ميلاد ابنه متوشالح، ثم أخذه الله وهو ابن ٣٦٥ سنة دون أن يرى الموت. وتنبأ عن مجيء الرب في ربوات قديسيه ليصنع دينونة (يهوذا ١٤). هو واحد من اثنين فقط في الكتاب أُخذا إلى السماء دون موت، وحياته تبيّن أن الشركة مع الله طريق الحياة.",[["ميلاد متوشالح وبداية سيره مع الله",["Gen",5,21,5,22]],["الله أخذه",["Gen",5,24,5,24]]]],"methuselah_2042":["ابن أخنوخ وجد نوح، عاش أطول عمر مذكور في الكتاب: ٩٦٩ سنة. وبحسب حساب أعمار الآباء جاء الطوفان في سنة موته. يُرى في طول عمره صورة لصبر الله وطول أناته قبل الدينونة.",[["ميلاده لأخنوخ",["Gen",5,21,5,21]],["ميلاد لامك",["Gen",5,25,5,25]],["موته",["Gen",5,27,5,27]]]],"shem_2613":["أحد أبناء نوح الثلاثة، كان في الفلك ونال بركة أبيه. ومن نسله جاء إبراهيم والشعوب السامية. وبعد الطوفان ستر هو وأخوه عورة أبيهما باحترام. عاش ست مئة سنة. من خط سام اختار الله شعب العهد وجاء المسيح.",[["دخوله الفلك",["Gen",7,13,7,13]],["ستر عورة أبيه",["Gen",9,23,9,23]],["ميلاد أرفكشاد",["Gen",11,10,11,10]],["موته",["Gen",11,11,11,11]]]],"lot_1830":["ابن أخي إبراهيم، رافقه إلى كنعان، ثم اختار السكن في دائرة الأردن المسقية قرب سدوم رغم شرها. وحين أهلك الله سدوم وعمورة أنقذه الملاكان هو وعائلته، لكن امرأته نظرت إلى الوراء فصارت عمود ملح. ويسميه بطرس «لوطًا البار» الذي كان يعذّب نفسه من شر من حوله (بطرس الثانية ٢: ٧–٨). قصته تحذير من تفضيل الغنى الأرضي على الأمانة الروحية.",[["رحيله مع إبراهيم إلى كنعان",["Gen",12,4,12,5]],["اختياره السكن قرب سدوم",["Gen",13,10,13,12]],["أسره وإنقاذ إبراهيم له",["Gen",14,12,14,16]],["نجاته من خراب سدوم",["Gen",19,15,19,29]]]],"ishmael_631":["ابن إبراهيم من هاجر جارية سارة المصرية، وُلد وإبراهيم ابن ٨٦ سنة، ولم يكن هو ابن الموعد. وبعد ميلاد إسحاق طلبت سارة صرف هاجر وابنها، لكن الله وعد أن يجعل إسماعيل أمة عظيمة، فصار أبًا لاثني عشر رئيسًا، وعاش ١٣٧ سنة. ويستخدم بولس قصته مثالًا للفرق بين المولود حسب الجسد والمولود حسب الموعد (غلاطية ٤).",[["ميلاده",["Gen",16,15,16,16]],["ختانه مع إبراهيم",["Gen",17,25,17,25]],["صرفه مع هاجر",["Gen",21,14,21,21]],["موته",["Gen",25,17,25,17]]]],"isaiah_617":["من أعظم أنبياء العهد القديم، خدم في يهوذا في أيام أربعة ملوك. تناولت نبواته أزمات عصره السياسية والمستقبل المسياني البعيد معًا. ورؤياه لقداسة الله في الهيكل غيّرت حياته وخدمته. تنبأ كثيرًا عن المسيا الآتي والعبد المتألم ورد إسرائيل، وفي سفره بعض أجمل نصوص الكتاب عن الخلاص ومجد الله. يُسمى «النبي الإنجيلي»، ونبواته عن العذراء والعبد المتألم والرئاسة على كتفه من أكثر ما يقتبسه العهد الجديد.",[["رؤياه في الهيكل",["Isa",6,1,6,8]],["نبوة عمانوئيل لآحاز",["Isa",7,14,7,14]],["نبوته لحزقيا بالخلاص",["Isa",37,6,37,7]],["العبد المتألم",["Isa",53,null,53,null]],["السماوات الجديدة والأرض الجديدة",["Isa",65,17,65,17]]]],"esau_1216":["البكر من توأمي إسحاق ورفقة، كان صيادًا ماهرًا ومحبوب أبيه. في لحظة ضعف باع بكوريته ليعقوب بطبيخ عدس واحتقرها، ثم أخذ يعقوب البركة التي كانت له. توعّد أخاه، لكنهما تصالحا في النهاية. ومنه جاء الأدوميون. ويستخدمه العهد الجديد تحذيرًا من الاستهانة بالبركات الروحية من أجل شهوة وقتية (عبرانيين ١٢: ١٦).",[["ميلاده",["Gen",25,24,25,26]],["بيع البكورية",["Gen",25,29,25,34]],["زواجه بالحثيتين",["Gen",26,34,26,34]],["فقدانه البركة",["Gen",27,30,27,41]],["مصالحته مع يعقوب",["Gen",33,4,33,4]]]],"aaron_1":["أخو موسى الأكبر وأول رئيس كهنة لإسرائيل. كان متكلمًا عن موسى أمام فرعون وصنع الآيات بعصاه، ثم كُرّس رئيسًا للكهنة واستمر الكهنوت في نسله. لكنه صنع العجل الذهبي، وتذمر مع مريم على موسى. مات على جبل هور ابن ١٢٣ سنة. كهنوته اللاوي ظل للكهنوت الكامل الذي للمسيح رئيس الكهنة العظيم.",[["الله يدعوه ليلاقي موسى",["Exo",4,27,4,28]],["أمام فرعون مع موسى",["Exo",7,1,7,7]],["صنع العجل الذهبي",["Exo",32,1,32,6]],["تكريسه رئيسًا للكهنة",["Lev",8,1,8,36]],["موته على جبل هور",["Num",33,38,33,39]]]],"joshua_1727":["خادم موسى وخليفته، قاد إسرائيل إلى أرض الموعد بعد موت موسى. كان شابًا من الجواسيس الاثني عشر، وهو وكالب فقط وثقا أن الله سيعطيهم الأرض. قاد دخول كنعان ومنه سقوط أريحا العجيب، ودعا الشعب أن يختاروا من يعبدون معلنًا: «أما أنا وبيتي فنعبد الرب». اسمه معناه «الرب يخلّص»، وهو صورة ليسوع الذي يقود شعبه إلى الميراث والراحة.",[["حربه مع عماليق",["Exo",17,9,17,13]],["تجسس الأرض مع كالب",["Num",14,6,14,9]],["تعيينه خليفة لموسى",["Deu",31,23,31,23]],["عبور الأردن",["Jos",3,14,3,17]],["سقوط أريحا",["Jos",6,1,6,27]],["موته",["Jos",24,29,24,29]]]],"samson_2468":["قاضٍ نذير أعطاه الرب قوة خارقة، قضى لإسرائيل عشرين سنة في أيام تسلّط الفلسطينيين. ورغم قوته كان ضعيفًا أخلاقيًا خاصة في علاقاته بالنساء، وانتهت علاقته بدليلة بكشف سر قوته والقبض عليه. وفي موته قتل من الفلسطينيين أكثر مما قتل في حياته. تبيّن قصته أن دعوة الله ومواهبه لا تعتمد على كمال الإنسان، لكن للخطية عواقبها.",[["الملاك يبشر بميلاده",["Jdg",13,3,13,5]],["قتله الأسد",["Jdg",14,5,14,6]],["ألف رجل بلحي حمار",["Jdg",15,15,15,15]],["خيانة دليلة",["Jdg",16,18,16,21]],["موته وهدم بيت داجون",["Jdg",16,28,16,30]]]],"samuel_2469":["آخر القضاة ونبي مسح أول ملكين لإسرائيل. وُلد لحنة استجابة لصلاتها، وكُرّس لخدمة الله منذ طفولته، وخدم في خيمة الاجتماع مع عالي، وسمع كلام الرب وهو صبي. قضى لإسرائيل بأمانة، وأقام المملكة بمسحه شاول ثم داود. هو الجسر بين زمن القضاة وزمن الملوك، وحياته تُظهر أهمية سماع صوت الله وطاعته.",[["ميلاده استجابة لصلاة حنة",["1Sa",1,20,1,20]],["تكريسه في شيلوه",["1Sa",1,24,1,28]],["الرب يدعوه ليلًا",["1Sa",3,1,3,10]],["مسحه شاول",["1Sa",10,1,10,1]],["مسحه داود",["1Sa",16,13,16,13]]]],"saul_2478":["أول ملوك إسرائيل، اختير وهو طويل القامة مهيب المنظر. بدأ متواضعًا، لكنه عصى أوامر الله فقدّم المحرقة بنفسه، وأبقى على أجاج ملك عماليق. فرفضه الله واختار داود. وامتلأت سنواته الأخيرة بالغيرة من داود ومطاردته. ومات منتحرًا بعد هزيمته في المعركة. قصته تحذير من الطاعة الجزئية ومن خوف الناس أكثر من الله.",[["مسحه ملكًا",["1Sa",10,1,10,1]],["اختياره أمام الشعب",["1Sa",10,24,10,24]],["تقديم المحرقة بلا أمر",["1Sa",13,8,13,14]],["رفضه لأنه أبقى على أجاج",["1Sa",15,22,15,23]],["محاولته قتل داود",["1Sa",18,10,18,11]],["موته بعد الهزيمة",["1Sa",31,4,31,4]]]],"elijah_1131":["نبي قوي في أيام ارتداد إسرائيل تحت أخآب وإيزابل. واجه عبادة البعل، وأعلن انقطاع المطر، وعالته الغربان، وبارك دقيق الأرملة وزيتها، وأنزل نارًا من السماء على جبل الكرمل. وبعد انتصاره هرب من تهديد إيزابل، فقابله الله «بصوت منخفض خفيف». ولم يمت بل صعد في العاصفة إلى السماء. ظهر مع موسى في التجلي، وارتبطت نبوة مجيئه في ملاخي بيوحنا المعمدان.",[["إعلان انقطاع المطر",["1Ki",17,1,17,1]],["الغربان تعوله",["1Ki",17,4,17,6]],["دقيق الأرملة وزيتها",["1Ki",17,14,17,16]],["النصر على أنبياء البعل",["1Ki",18,38,18,40]],["الصوت المنخفض الخفيف",["1Ki",19,12,19,12]],["صعوده في العاصفة",["2Ki",2,11,2,11]]]],"elisha_1153":["النبي الذي خلف إيليا بعد أن نال نصيبين من روحه. صنع معجزات كثيرة: أبرأ الماء، وكثّر زيت الأرملة، وأقام ابن الشونمية، وشفى نعمان من البرص، وجعل الحديد يطفو. نصح الملوك وأظهر قوة الله بآيات كثيرة، وامتدت خدمته أكثر من خمسين سنة بين الأغنياء والفقراء. ومعجزات الرحمة في خدمته تشبه خدمة المسيح.",[["إيليا يدعوه",["1Ki",19,19,19,21]],["نصيبان من روح إيليا",["2Ki",2,9,2,14]],["إبراء الماء",["2Ki",2,21,2,22]],["زيت الأرملة",["2Ki",4,1,4,7]],["إقامة ابن الشونمية",["2Ki",4,32,4,37]],["شفاء نعمان",["2Ki",5,10,5,14]]]],"jonah_1689":["النبي الذي دُعي لينادي في نينوى فهرب إلى ترشيش. أرسل الله نوءًا عظيمًا، فطُرح في البحر وابتلعه حوت عظيم ثلاثة أيام. وبعد أن قذفه الحوت إلى البر أطاع ونادى في نينوى فتابت. وغضبه من رحمة الله كشف قساوة قلبه. وقد جعل يسوع بقاءه في جوف الحوت آية لموته وقيامته (متى ١٢: ٤٠)، وتُظهر قصته محبة الله لكل الأمم.",[["دعوته إلى نينوى",["Jon",1,1,1,2]],["هروبه إلى ترشيش",["Jon",1,3,1,3]],["طرحه في البحر",["Jon",1,15,1,15]],["الحوت يبتلعه",["Jon",1,17,1,17]],["قذفه إلى البر",["Jon",2,10,2,10]],["ندائه في نينوى وتوبتها",["Jon",3,4,3,10]]]],"john_1676":["السابق للمسيح، وُلد لزكريا وأليصابات في شيخوختهما. عاش في البرية ولبس وبر الإبل وأكل جرادًا وعسلًا بريًا. كرز بالتوبة وعمّد في نهر الأردن ليعد طريق المسيا، وعمّد يسوع وأعلن أنه «حمل الله». سجنه هيرودس ثم قطع رأسه لأنه وبّخه على زواجه غير الشرعي. هو «صوت صارخ في البرية» الذي تنبأ عنه إشعياء، وآخر أنبياء العهد القديم والجسر إلى العهد الجديد.",[["البشارة بميلاده",["Luk",1,13,1,13]],["بداية خدمته في البرية",["Luk",3,1,3,3]],["معمودية يسوع",["Mat",3,13,3,17]],["«هوذا حمل الله»",["Joh",1,29,1,29]],["سجنه",["Mat",14,3,14,4]],["قطع رأسه",["Mat",14,10,14,10]]]],"mary_1938":["العذراء التي اختارها الله لتكون أم يسوع المسيح. فتاة من الناصرة مخطوبة ليوسف، قبلت بشارة الملاك جبرائيل باتضاع وطاعة. ولدت يسوع في بيت لحم وربّته مع يوسف، وشهدت خدمته وصلبه، وكانت مع التلاميذ بعد صعوده. وقد قالت عنها أليصابات: «مباركة أنت في النساء». إيمانها المطيع مثال للتلمذة الحقيقية.",[["البشارة",["Luk",1,26,1,38]],["زيارتها لأليصابات",["Luk",1,39,1,45]],["ولادة يسوع",["Luk",2,7,2,7]],["تقديمه في الهيكل",["Luk",2,22,2,38]],["في عرس قانا",["Joh",2,1,2,5]],["عند الصليب",["Joh",19,25,19,27]]]],"peter_2745":["اسمه الأصلي سمعان، صياد سمك دعاه يسوع ليكون «صياد الناس». كان من التلاميذ الأقرب إلى يسوع، وكثيرًا ما تكلم باسمهم. اعترف بجرأة أن يسوع هو المسيح، لكنه أنكره ثلاث مرات وقت محاكمته. وبعد القيامة ردّه يسوع إلى الخدمة، فصار عمودًا في الكنيسة الأولى، وعظ يوم الخمسين وكتب رسالتين. قصته تجمع ضعف الإنسان وقوة النعمة التي تردّه.",[["دعوته",["Mat",4,18,4,20]],["مشيه على الماء",["Mat",14,28,14,31]],["«أنت هو المسيح»",["Mat",16,16,16,16]],["شاهد التجلي",["Mat",17,1,17,8]],["إنكاره ثلاث مرات",["Mat",26,69,26,75]],["يسوع يردّه",["Joh",21,15,21,19]],["عظته يوم الخمسين",["Act",2,14,2,41]]]],"paul_2479":["اسمه الأصلي شاول الطرسوسي، فريسي اضطهد المسيحيين، ثم تغيّر تغيّرًا عجيبًا على طريق دمشق حين ظهر له المسيح المقام. صار أعظم مرسلي الكنيسة الأولى، قام بثلاث رحلات تبشيرية وكتب جزءًا كبيرًا من العهد الجديد. احتمل السجن والضرب وانكسار السفينة، وبحسب التقليد استشهد في رومية. رسائله أسست الكنائس وشكّلت التعليم المسيحي في عالم الأمم.",[["إيمانه على طريق دمشق",["Act",9,3,9,6]],["بداية كرازته",["Act",9,20,9,20]],["الرحلة الأولى",["Act",13,2,13,3]],["مجمع أورشليم",["Act",15,2,15,2]],["الرحلة الثانية",["Act",15,36,15,36]],["الرحلة الثالثة",["Act",18,23,18,23]],["القبض عليه في أورشليم",["Act",21,33,21,33]],["«قد جاهدت الجهاد الحسن»",["2Ti",4,6,4,8]]]],"rebekah_2401":["زوجة إسحاق، اختارها عبد إبراهيم بعناية الله، فتركت أرضها لتتزوج رجلًا لم تره. ظلت عاقرًا عشرين سنة ثم ولدت التوأمين عيسو ويعقوب. فضّلت يعقوب وساعدته على خداع إسحاق ليأخذ البركة. تُظهر قصتها كيف يعمل الله بأناس غير كاملين ليتمم مقاصده.",[["لقاؤها عبد إبراهيم عند البئر",["Gen",24,15,24,27]],["قبولها الذهاب",["Gen",24,58,24,58]],["زواجها بإسحاق",["Gen",24,67,24,67]],["ولادة عيسو ويعقوب",["Gen",25,24,25,26]],["مساعدتها يعقوب في أخذ البركة",["Gen",27,5,27,17]]]],"rachel_2386":["زوجة يعقوب المحبوبة التي خدم لأجلها أربع عشرة سنة. ظلت عاقرًا سنين طويلة بينما ولدت أختها ليئة، فكان بينهما تنافس وحزن. ثم ذكرها الله فولدت يوسف، ثم بنيامين وماتت عند ولادته، وصار قبرها قرب بيت لحم علامة. ومن ابنيها جاء سبطان مهمان في إسرائيل.",[["لقاؤها يعقوب عند البئر",["Gen",29,9,29,11]],["سبع سنين كأيام قليلة",["Gen",29,20,29,20]],["خداع لابان بليئة",["Gen",29,23,29,25]],["زواجها بيعقوب",["Gen",29,28,29,28]],["ميلاد يوسف",["Gen",30,22,30,24]],["موتها عند ولادة بنيامين",["Gen",35,16,35,19]]]],"judah_1751":["الابن الرابع ليعقوب من ليئة، وصار قائدًا بين إخوته. اقترح بيع يوسف بدل قتله. وبعد إخفاقاته مع أبنائه ومع ثامار كنّته، ظهر تغيّره حين قدّم نفسه عبدًا عوضًا عن بنيامين. ومن نسله جاء داود الملك ثم المسيح «الأسد الذي من سبط يهوذا».",[["ميلاده",["Gen",29,35,29,35]],["اقتراحه بيع يوسف",["Gen",37,26,37,27]],["قصته مع ثامار",["Gen",38,13,38,26]],["يقدّم نفسه عوضًا عن بنيامين",["Gen",44,33,44,33]],["بركة يعقوب له",["Gen",49,8,49,10]]]],"caleb_537":["أحد الجواسيس الاثني عشر، وهو ويشوع فقط وثقا أن الله سيعطي إسرائيل النصرة، فوُعد بدخول أرض الموعد. وفي سن الخامسة والثمانين طلب جبل حبرون بمدنه الحصينة وبني عناق، قائلًا إنه ما زال قويًا كيوم أرسله موسى، فأخذها ميراثًا. هو مثال للقلب الكامل مع الله وللإيمان الذي لا يشيخ.",[["تجسسه أرض كنعان",["Num",13,6,13,6]],["تقريره الحسن مع يشوع",["Num",14,6,14,9]],["وعد الرب له",["Num",14,24,14,24]],["طلبه حبرون ميراثًا",["Jos",14,10,14,12]],["طرده بني عناق",["Jos",15,13,15,14]]]],"ruth_2450":["امرأة موآبية تزوجت في عائلة إسرائيلية. وبعد موت زوجها اختارت أن تبقى مع حماتها نعمي، ورجعت معها إلى بيت لحم قائلة: «شعبك شعبي وإلهك إلهي». وبعناية الله تزوجت بوعز الولي، وصارت جدة داود الملك. قصتها عن الوفاء، وتُظهر أن نعمة الله تشمل الأمم، فقد دخلت أممية في نسب المسيح.",[["زواجها في موآب",["Rut",1,4,1,4]],["موت زوجها",["Rut",1,5,1,5]],["التصاقها بنعمي وإلهها",["Rut",1,16,1,17]],["التقاطها في حقل بوعز",["Rut",2,2,2,3]],["زواجها ببوعز",["Rut",4,13,4,13]],["ميلاد عوبيد جد داود",["Rut",4,17,4,17]]]],"hannah_1400":["أم صموئيل، تألمت من العقم ومن مضايقة ضرتها فننة. وفي مرارة نفسها صلّت بحرارة في شيلوه، ونذرت إن أعطاها الرب ابنًا أن تعطيه للرب كل أيام حياته. استجاب الله، فوفت نذرها وأتت بصموئيل الصغير ليخدم مع عالي، ثم رزقها الله خمسة أولاد آخرين. صلاتها مثال للإيمان المثابر، ونشيدها يشبه تسبحة مريم.",[["مضايقة فننة لها",["1Sa",1,6,1,7]],["صلاتها ونذرها",["1Sa",1,10,1,11]],["بركة عالي",["1Sa",1,17,1,17]],["ميلاد صموئيل",["1Sa",1,20,1,20]],["تقديمه للرب",["1Sa",1,24,1,28]],["نشيد حنة",["1Sa",2,1,2,10]]]],"daniel_975":["شاب يهودي من النبلاء سُبي إلى بابل، وجعل في قلبه ألا يتنجس بأطايب الملك. أعطاه الله حكمة فاقت حكماء بابل، ففسّر أحلام الملوك ورأى رؤى عن الممالك الآتية. وظل أمينًا لله رغم التهديد وجب الأسود. تنبأ عن السبعين أسبوعًا ورأى رؤى الأيام الأخيرة. هو مثال للأمانة في أرض غريبة، ونبواته تكشف سلطان الله على التاريخ.",[["سبيه إلى بابل",["Dan",1,3,1,6]],["تفسير حلم نبوخذنصر",["Dan",2,31,2,45]],["قراءة الكتابة على الحائط",["Dan",5,25,5,28]],["إلقاؤه في جب الأسود",["Dan",6,16,6,16]],["نجاته من الأسود",["Dan",6,22,6,22]],["رؤيا السبعين أسبوعًا",["Dan",9,24,9,27]]]],"esther_1343":["يتيمة يهودية رباها ابن عمها مردخاي، وصارت ملكة على فارس بعناية الله. ولما دبّر هامان إهلاك كل اليهود، دعاها مردخاي أن تستخدم مكانتها لإنقاذ شعبها، فدخلت إلى الملك دون أن تُدعى قائلة: «إذا هلكت هلكت». شجاعتها أنقذت شعبها، وعيد الفوريم يحتفل بهذا الخلاص. قصتها تُظهر عناية الله الخفية التي تحفظ شعبه.",[["اختيارها ملكة",["Est",2,17,2,17]],["معرفتها بمؤامرة هامان",["Est",3,13,4,8]],["قرارها الدخول إلى الملك",["Est",4,15,4,16]],["كشفها مؤامرة هامان",["Est",7,3,7,6]],["خلاص اليهود وعيد الفوريم",["Est",9,20,9,22]]]],"jeremiah_853":["«النبي الباكي»، دعاه الله وهو صغير ليتنبأ بخراب يهوذا. أعلن كلمة الله بأمانة أكثر من أربعين سنة رغم المقاومة الشديدة والسجن والرفض. شهد سقوط أورشليم في يد بابل وأُخذ رغمًا عنه إلى مصر. ومن نبواته العهد الجديد المكتوب على القلوب، ووعد الرجوع بعد سبعين سنة من السبي.",[["دعوته وهو صبي",["Jer",1,4,1,10]],["نبوة السبعين سنة",["Jer",25,11,25,12]],["سجنه",["Jer",37,15,37,15]],["إلقاؤه في الجب",["Jer",38,6,38,6]],["نبوة العهد الجديد",["Jer",31,31,31,34]],["سقوط أورشليم",["Jer",39,1,39,10]]]],"ezekiel_1237":["كاهن سُبي إلى بابل، ورأى رؤى عظيمة عند نهر خابور. أقامه الله رقيبًا لبيت إسرائيل ينذرهم بالدينونة. ومن نبواته رؤيا العظام اليابسة التي تحيا، وخروج مجد الله من الهيكل ثم رجوعه، وتفاصيل هيكل آتٍ. أعلن الدينونة والرجاء معًا، وتُظهر خدمته أن الله حاضر مع شعبه حتى في السبي.",[["رؤيا مجد الله",["Eze",1,1,1,28]],["رقيب لبيت إسرائيل",["Eze",3,17,3,21]],["موت زوجته علامة",["Eze",24,15,24,18]],["رؤيا العظام اليابسة",["Eze",37,1,37,14]],["رؤيا الهيكل الجديد",["Eze",40,null,48,null]]]],"john_1677":["التلميذ الذي كان يسوع يحبه، ابن زبدي وأخو يعقوب، ومن التلاميذ الأقرب إلى يسوع، حضر التجلي واتكأ على صدره في العشاء الأخير، واستلم رعاية مريم عند الصليب. كتب الإنجيل الرابع وثلاث رسائل وسفر الرؤيا، وأكّد على المحبة والثبات في المسيح، وعاش بعد كل الرسل. تكشف كتاباته يسوع «الكلمة الذي صار جسدًا».",[["دعوته",["Mar",1,19,1,20]],["في التجلي",["Mar",9,2,9,2]],["متكئ على صدر يسوع",["Joh",13,23,13,23]],["عند الصليب واستلامه مريم",["Joh",19,26,19,27]],["رأى القبر الفارغ فآمن",["Joh",20,8,20,8]],["الرؤيا في بطمس",["Rev",1,9,1,9]]]],"stephen_2802":["أول شهيد مسيحي، واحد من السبعة الذين اختيروا لخدمة الموائد. كان مملوءًا إيمانًا والروح القدس، وصنع عجائب وآيات عظيمة. ولما اتُّهم أمام المجمع ألقى خطابًا قويًا عن تاريخ إسرائيل ورفضهم لرسل الله. وبينما كانوا يرجمونه رأى السماء مفتوحة ويسوع قائمًا عن يمين الله. بعد موته بدأ اضطهاد عظيم انتشر بسببه الإنجيل خارج أورشليم.",[["اختياره من السبعة",["Act",6,5,6,5]],["آيات وعجائب",["Act",6,8,6,8]],["اتهامه أمام المجمع",["Act",6,12,6,15]],["خطابه",["Act",7,2,7,53]],["رؤيته يسوع قائمًا",["Act",7,55,7,56]],["رجمه",["Act",7,58,7,60]]]],"timotheus_2863":["الابن الروحي المحبوب لبولس ورفيقه في الخدمة، أبوه يوناني وأمه يهودية مؤمنة اسمها أفنيكي، وعرف الكتب المقدسة منذ طفولته. رافق بولس في رحلاته، ثم رعى الكنيسة في أفسس رغم صغر سنه. وكتب له بولس رسالتين في الخدمة والتعليم. هو مثال للتلمذة الأمينة والإيمان الذي ينتقل من جيل إلى جيل.",[["مشهود له من الإخوة",["Act",16,1,16,2]],["انضمامه لبولس",["Act",16,3,16,3]],["إرساله لتثبيت أهل تسالونيكي",["1Th",3,1,3,2]],["بقاؤه في أفسس",["1Ti",1,3,1,3]],["رسالة بولس الأخيرة إليه",["2Ti",1,1,1,1]]]],"barnabas_1722":["لاوي قبرسي، اسمه معناه «ابن الوعظ (التشجيع)». باع حقله ليساعد الكنيسة، وشهد لشاول حين خاف منه الآخرون، وأتى به إلى أنطاكية ورافقه في الرحلة الأولى. وحين افترق عن بولس بسبب مرقس، أخذ مرقس معه، فعاد مرقس نافعًا للخدمة. هو مثال للتشجيع والكرم وإعطاء فرصة ثانية.",[["بيع حقله",["Act",4,36,4,37]],["شهادته لشاول",["Act",9,27,9,27]],["في أنطاكية مع شاول",["Act",11,22,11,26]],["الرحلة الأولى",["Act",13,2,13,3]],["افتراقه عن بولس",["Act",15,36,15,40]]]],"sarah_2473":["اسمها أولًا ساراي، زوجة إبراهيم التي رافقته إلى كنعان. ورغم عقمها وشيخوختها وعدها الله بابن، فولدت إسحاق ابن الموعد وهي ابنة تسعين سنة. يذكرها العهد الجديد مثالًا للإيمان (عبرانيين ١١: ١١)، وميلاد إسحاق منها يُظهر قدرة الله وأمانته لوعوده.",[["رحيلها مع إبراهيم",["Gen",12,4,12,5]],["الله يعدها بابن",["Gen",17,15,17,19]],["ميلاد إسحاق",["Gen",21,1,21,7]],["موتها",["Gen",23,1,23,2]]]],"boaz_519":["رجل غني من بيت لحم صار وليًّا لراعوث الموآبية. أحسن إليها حين التقطت في حقله وحماها، ثم تزوجها بحسب الشريعة. ومن ابنهما عوبيد صار جد داود الملك. يُرى فيه صورة للمسيح الولي الذي يفدي شعبه.",[["راعوث في حقله",["Rut",2,3,2,3]],["إحسانه إليها",["Rut",2,8,2,16]],["فكاكه لها",["Rut",4,9,4,10]],["زواجه بها",["Rut",4,13,4,13]],["ميلاد عوبيد",["Rut",4,17,4,17]]]],"bathsheba_416":["زوجة أوريا الحثي، رآها داود تستحم فزنى معها، ثم دبّر قتل زوجها وتزوجها. مات ابنهما الأول، أما الثاني فكان سليمان الذي ملك وبنى الهيكل. وهي مذكورة في نسب المسيح، علامة على نعمة الله التي تفدي.",[["خطية داود معها",["2Sa",11,4,11,4]],["قتل أوريا",["2Sa",11,17,11,17]],["زواجها بداود",["2Sa",11,27,11,27]],["موت الطفل",["2Sa",12,18,12,18]],["ميلاد سليمان",["2Sa",12,24,12,24]]]],"luke_1836":["طبيب ورفيق لبولس، مؤمن من الأمم، تتبع الأخبار بتدقيق وكتب الإنجيل الثالث وسفر أعمال الرسل. رافق بولس في رحلاته وكان معه في سجنه. يُبرز إنجيله حنان يسوع على الفقراء والمنبوذين، وكتاباته سجل تاريخي دقيق لحياة يسوع والكنيسة الأولى.",[["انضمامه لبولس («نحن»)",["Act",16,10,16,10]],["رحلته مع بولس إلى رومية",["Act",27,null,28,null]],["«لوقا وحده معي»",["2Ti",4,11,4,11]],["مقدمة إنجيله",["Luk",1,1,1,4]]]],"deborah_997":["نبية وقاضية لإسرائيل في زمن ضيق الكنعانيين. دعت باراق ليقود الجيش ضد سيسرا، وذهبت معه إلى المعركة. وبقيادتها انتصر إسرائيل واستراحت الأرض أربعين سنة. حكمتها وشجاعتها كانتا سبب خلاص لإسرائيل.",[["قضاؤها لإسرائيل",["Jdg",4,4,4,5]],["دعوتها باراق",["Jdg",4,6,4,7]],["خروجها معه",["Jdg",4,9,4,9]],["نشيد دبورة",["Jdg",5,1,5,1]],["استراحة الأرض",["Jdg",5,31,5,31]]]],"gideon_1314":["دعاه الله وهو يخبط الحنطة مختبئًا من مديان، فقاد إسرائيل رغم شكوكه وخوفه. قلّل الله جيشه من ٣٢ ألفًا إلى ثلاث مئة ليظهر أن النصرة من الله وحده، وبالأبواق والمصابيح هزموا جيش مديان. تُظهر قصته أن الله يستخدم الضعفاء ليكون المجد له، وأنه يصبر على المترددين.",[["الملاك يدعوه",["Jdg",6,11,6,12]],["علامة جزة الصوف",["Jdg",6,36,6,40]],["الجيش ثلاث مئة رجل",["Jdg",7,2,7,7]],["هزيمة مديان",["Jdg",7,19,7,23]],["رفضه أن يكون ملكًا",["Jdg",8,22,8,23]]]],"hezekiah_1512":["ملك صالح على يهوذا، أزال عبادة الأوثان وأعاد العبادة في الهيكل. ولما هددت أشور أورشليم صلّى، فضرب ملاك الرب جيش أشور. وأُعطي خمس عشرة سنة على عمره بعد مرض مميت. هو مثال للثقة في الله وقت الأزمة، وإصلاحه وفصحه جمعا الشعب في العبادة.",[["ملكه على يهوذا",["2Ki",18,1,18,2]],["ترميم الهيكل والعبادة",["2Ch",29,3,29,11]],["الاحتفال بالفصح",["2Ch",30,1,30,27]],["شفاؤه",["2Ki",20,1,20,6]],["الخلاص من أشور",["2Ki",19,35,19,35]]]],"josiah_1730":["ملك وهو ابن ثماني سنين، وقاد أعظم إصلاح في تاريخ يهوذا. أثناء ترميم الهيكل وُجد سفر الشريعة، فمزق ثيابه تائبًا وقاد الشعب في تجديد العهد، وأزال الأوثان والمرتفعات من الأرض. تُظهر قصته قوة كلمة الله في إحداث التوبة والإصلاح.",[["ملكه",["2Ki",22,1,22,1]],["بدأ يطلب الرب",["2Ch",34,3,34,3]],["تطهير الأرض",["2Ch",34,3,34,7]],["وجود سفر الشريعة",["2Ki",22,8,22,8]],["تجديد العهد",["2Ki",23,1,23,3]],["موته في المعركة",["2Ki",23,29,23,29]]]],"martha_1937":["أخت مريم ولعازر، استقبلت يسوع في بيتها في بيت عنيا. عُرفت بأنها كانت مرتبكة في خدمة كثيرة بينما جلست مريم عند قدمي يسوع. وعند موت لعازر اعترفت بأن يسوع هو المسيح ابن الله قبل أن يقيم أخاها. قصتها عن التوازن بين الخدمة والجلوس عند الرب.",[["استقبالها يسوع",["Luk",10,38,10,38]],["«مريم اختارت النصيب الصالح»",["Luk",10,40,10,42]],["اعترافها بالمسيح",["Joh",11,27,11,27]],["إقامة لعازر",["Joh",11,43,11,44]],["خدمتها في العشاء",["Joh",12,2,12,2]]]],"lazarus_1812":["أخو مريم ومرثا وصديق يسوع من بيت عنيا. مرض ومات، فانتظر يسوع يومين ثم جاء وأقامه بعد أربعة أيام في القبر. آمن بسبب ذلك كثيرون، لكن المؤامرة على يسوع اشتدت. كانت إقامته أعظم آية قبل قيامة يسوع نفسه، وإعلانًا لسلطانه على الموت.",[["مرضه",["Joh",11,1,11,3]],["موته ودفنه",["Joh",11,14,11,17]],["قيامته بعد أربعة أيام",["Joh",11,43,11,44]],["متكئ مع يسوع",["Joh",12,2,12,2]],["رؤساء الكهنة يتشاورون لقتله",["Joh",12,10,12,11]]]],"zacchaeus_2961":["رئيس للعشارين غني في أريحا، صعد إلى جميزة ليرى يسوع فوق الجمع. ناداه يسوع وقال إنه سيمكث في بيته، فتغيّر زكا وتاب ووعد أن يرد أربعة أضعاف ما أخذه بالظلم. قصته تبيّن أن الخلاص يُنتج توبة حقيقية، وأن ابن الإنسان جاء ليطلب ويخلّص ما قد هلك.",[["صعوده إلى الجميزة",["Luk",19,3,19,4]],["يسوع في بيته",["Luk",19,5,19,5]],["ردّه أربعة أضعاف",["Luk",19,8,19,8]],["«اليوم حصل خلاص لهذا البيت»",["Luk",19,9,19,10]]]],"nicodemus_2204":["فريسي ورئيس لليهود، جاء إلى يسوع ليلًا يطلب الحق، فعلّمه عن الولادة الجديدة. ثم دافع عن يسوع أمام المجمع، وشارك يوسف الرامي في دفنه وأتى بأطياب كثيرة. يمثل الذين ينمون في الإيمان تدريجيًا.",[["مجيئه ليلًا",["Joh",3,1,3,2]],["الولادة الجديدة",["Joh",3,3,3,7]],["دفاعه عن يسوع",["Joh",7,50,7,51]],["مشاركته في الدفن",["Joh",19,39,19,40]]]],"silas_2740":["نبي وقائد في كنيسة أورشليم، اختاره بولس رفيقًا في رحلته الثانية بعد افتراقه عن برنابا. ضُرب هو وبولس وسُجنا في فيلبي، لكنهما سبّحا الله في نصف الليل فآمن السجان. ويُذكر اسمه مع بولس في رسالتي تسالونيكي. هو مثال للشراكة الأمينة في الخدمة والفرح وسط الألم.",[["حمل رسالة مجمع أورشليم",["Act",15,22,15,22]],["انضمامه للرحلة الثانية",["Act",15,40,15,40]],["ضربه وسجنه في فيلبي",["Act",16,22,16,24]],["التسبيح في نصف الليل",["Act",16,25,16,25]],["إيمان السجان",["Act",16,29,16,34]]]],"nathan_2153":["نبي في أيام داود، واجه الملك بجرأة بخطيته مع بثشبع، وحمل إليه وعد الله ببيت ثابت إلى الأبد. وكان له دور في تثبيت سليمان على العرش. هو مثال للنبي الذي يقول الحق للملوك، وقصته تُظهر غفران الله للتائب.",[["وعد الله لداود",["2Sa",7,4,7,17]],["«أنت هو الرجل»",["2Sa",12,1,12,15]],["تسمية سليمان «يديديا»",["2Sa",12,25,12,25]],["تثبيت سليمان ملكًا",["1Ki",1,11,1,45]]]],"benjamin_463":["أصغر أبناء يعقوب من راحيل، وُلد وأمه تموت فسمّته «ابن أوني» أي ابن حزني، وسمّاه أبوه «بنيامين» أي ابن اليمين. هو الوحيد من أبناء يعقوب الذي وُلد في كنعان، وكان محبوبًا جدًا من أبيه. ومن سبطه جاء شاول أول ملك، وبولس الرسول.",[["ميلاده وموت راحيل",["Gen",35,16,35,18]],["نزوله إلى مصر",["Gen",43,15,43,15]],["الطاس في عدله",["Gen",44,12,44,12]],["لقاؤه بيوسف",["Gen",45,14,45,14]]]],"reuben_2429":["بكر يعقوب من ليئة، كان له أن ينال البكورية، لكنه فقدها حين اضطجع مع بلهة سرية أبيه. ومع ذلك حاول أن ينقذ يوسف من إخوته، وقدّم ابنيه رهنًا لسلامة بنيامين. قصته تبيّن أن اختيار الله لا يتبع ترتيب الميلاد وحده.",[["ميلاده",["Gen",29,32,29,32]],["اللفاح في الحقل",["Gen",30,14,30,14]],["خطيته مع بلهة",["Gen",35,22,35,22]],["محاولته إنقاذ يوسف",["Gen",37,21,37,22]],["ابناه رهن لبنيامين",["Gen",42,37,42,37]]]],"simeon_2741":["الابن الثاني ليعقوب من ليئة، اشترك مع أخيه لاوي في الانتقام الدموي من أهل شكيم بعد ما حدث لأختهما دينة، ولام يعقوب عملهما عند موته. واحتجزه يوسف رهينة في مصر حتى رجع إخوته ومعهم بنيامين. وسكن سبطه فيما بعد داخل نصيب يهوذا.",[["ميلاده",["Gen",29,33,29,33]],["الانتقام من شكيم",["Gen",34,25,34,26]],["حبسه في مصر",["Gen",42,24,42,24]]]],"dan_973":["أول ابن ليعقوب من بلهة جارية راحيل، واسمه معناه «قضى» أو «أنصف»، إذ قالت راحيل: «قد قضى لي الله». ومن سبطه جاء شمشون القاضي، لكن السبط ارتبط فيما بعد بعبادة الأوثان (القضاة ١٨).",[["ميلاده",["Gen",30,5,30,6]],["نزوله إلى مصر",["Gen",46,23,46,23]]]],"naphtali_2149":["الابن الثاني ليعقوب من بلهة جارية راحيل، واسمه معناه «مصارعتي»، إذ رأت راحيل في ميلاده نهاية صراعها مع أختها. سكن سبطه في شمال الجليل، وهي المنطقة التي خدم فيها يسوع كثيرًا تتميمًا لنبوة إشعياء عن النور المشرق في «أرض زبولون وأرض نفتاليم».",[["ميلاده",["Gen",30,7,30,8]],["نزوله إلى مصر",["Gen",46,24,46,24]]]],"gad_1262":["أول ابن ليعقوب من زلفة جارية ليئة، واسمه معناه «بسعد» أو «جاء جيش». صار نسله سبطًا من المحاربين سكن شرقي الأردن في أراضي مراعٍ خصبة.",[["ميلاده",["Gen",30,10,30,11]],["نزوله إلى مصر",["Gen",46,16,46,16]]]],"asher_337":["الابن الثاني ليعقوب من زلفة جارية ليئة، واسمه معناه «سعيد»، إذ قالت ليئة: «تغبطني البنات». ورث نسله أرضًا ساحلية غنية، ومن سبطه جاءت حنة النبية التي شهدت تقديم يسوع في الهيكل.",[["ميلاده",["Gen",30,12,30,13]],["نزوله إلى مصر",["Gen",46,17,46,17]]]],"issachar_645":["الابن التاسع ليعقوب والخامس من ليئة، واسمه مرتبط بمعنى «الأجرة». صار نسله سبطًا كبيرًا، ويُذكر عن رجاله أنهم «ذوو معرفة بالأوقات لمعرفة ما يعمل إسرائيل» (أخبار الأيام الأول ١٢: ٣٢).",[["ميلاده",["Gen",30,17,30,18]],["نزوله إلى مصر",["Gen",46,13,46,13]]]],"zebulun_3002":["الابن العاشر ليعقوب وآخر أبناء ليئة الستة، واسمه معناه «مسكن» أو «كرامة»، إذ رجت ليئة أن يكرمها زوجها. سكن نسله أرضًا تمر بها طرق التجارة، وفيها نشأ يسوع وبدأ خدمته.",[["ميلاده",["Gen",30,19,30,20]],["نزوله إلى مصر",["Gen",46,14,46,14]]]],"ephraim_1206":["الابن الثاني ليوسف من أسنات، وُلد في مصر، ونال البركة الأكبر من يعقوب رغم أنه أصغر من منسى. صار سبطه أقوى أسباط الشمال، حتى صار اسم «أفرايم» يُطلق على مملكة إسرائيل كلها. قصته تُظهر اختيار الله للأصغر، لكن السبط قاد إسرائيل فيما بعد إلى الأوثان.",[["ميلاده في مصر",["Gen",41,52,41,52]],["يعقوب يضع يمينه عليه",["Gen",48,17,48,20]],["نصيب سبطه",["Jos",16,5,16,5]]]],"adonijah_97":["الابن الرابع لداود من حجيث، حاول أن يستولي على العرش في شيخوخة داود رغم أن سليمان هو المختار. أقام وليمة تتويج، لكن ناثان وبثشبع أخبرا داود فأمر بتتويج سليمان فورًا. ثم طلب أبيشج زوجة لنفسه فأمر سليمان بقتله. قصته تحذير من الطموح المتعجرف.",[["ميلاده",["2Sa",3,4,3,4]],["محاولته أخذ العرش",["1Ki",1,5,1,9]],["سليمان يعفو عنه",["1Ki",1,52,1,53]],["قتله بعد طلبه أبيشج",["1Ki",2,13,2,25]]]],"joab_1617":["ابن صروية أخت داود ورئيس جيشه معظم سنوات ملكه. كان قائدًا عسكريًا بارعًا لكنه قاسٍ، فقتل أبنير وأبشالوم وعماسا خلافًا لرغبة داود. ورغم ولائه في حروب كثيرة، أدت أعماله العنيفة إلى أن أمر سليمان بقتله. هو مثال للقائد القدير الذي لا تبرر خدمته العصيان المتعمد.",[["أخذ أورشليم",["2Sa",5,8,5,8]],["قتل أبنير",["2Sa",3,27,3,27]],["قتل أبشالوم",["2Sa",18,14,18,14]],["قتل عماسا",["2Sa",20,10,20,10]],["موته على يد بناياهو",["1Ki",2,28,2,34]]]],"jehoshaphat_808":["رابع ملوك يهوذا وابن آسا، من الملوك الصالحين الذين طلبوا الرب وأزالوا المرتفعات والسواري. حصّن يهوذا وأرسل معلمين في كل المدن يعلّمون الشعب شريعة الرب، وانتصر انتصارًا عظيمًا حين قاد الشعب في التسبيح قبل المعركة. لكنه دخل في تحالفات غير حكيمة مع ملوك إسرائيل الأشرار.",[["ملكه على يهوذا",["1Ki",22,42,22,42]],["إرسال معلمي الشريعة",["2Ch",17,7,17,9]],["تحالفه مع أخآب",["1Ki",22,4,22,4]],["النصر بالتسبيح",["2Ch",20,20,20,23]],["موته",["1Ki",22,50,22,50]]]],"amaziah_214":["ابن يوآش، ملك على يهوذا وعمل المستقيم في عيني الرب لكن ليس بقلب كامل. قتل قاتلي أبيه لكنه لم يقتل أبناءهم طاعة للشريعة. وبعد انتصاره على أدوم أتى بآلهتهم وسجد لها، ثم تحدّى ملك إسرائيل فهُزم وأُسر، وقُتل في لخيش. قصته تحذير من التكريس الناقص والكبرياء.",[["ملكه على يهوذا",["2Ki",14,2,14,2]],["انتصاره على أدوم",["2Ki",14,7,14,7]],["سجوده لآلهة أدوم",["2Ch",25,14,25,14]],["هزيمته أمام يهوآش",["2Ki",14,11,14,14]],["قتله في لخيش",["2Ki",14,19,14,19]]]],"uzziah_375":["ويسمى أيضًا عزريا، ابن أمصيا، ملك على يهوذا وهو ابن ست عشرة سنة. طلب الله فنجح جدًا: قوّى الجيش وبنى الأبراج واهتم بالزراعة. لكنه في كبريائه دخل الهيكل ليوقد البخور، وهو عمل الكهنة وحدهم، فضربه الله بالبرص وبقي أبرص حتى موته بينما حكم ابنه يوثام. نجاحه قاده إلى الكبرياء.",[["ملكه",["2Ki",15,2,15,2]],["بناء أيلة",["2Ki",14,22,14,22]],["طلبه الله ونجاحه",["2Ch",26,4,26,5]],["دخوله الهيكل وضربه بالبرص",["2Ch",26,16,26,21]],["موته",["2Ki",15,7,15,7]]]],"jotham_1735":["ابن عزيا، ملك على يهوذا وعمل المستقيم مثل أبيه، لكنه لم يدخل الهيكل كما فعل أبوه. بنى كثيرًا، ومنه الباب الأعلى لبيت الرب، وانتصر على بني عمون. لكن الشعب استمر في الفساد في أيامه، فالقائد الصالح لا يستطيع أن يفرض البر على شعب قاسي القلب.",[["ملكه",["2Ki",15,33,15,33]],["بناء الباب الأعلى",["2Ki",15,35,15,35]],["انتصاره على بني عمون",["2Ch",27,5,27,5]],["موته",["2Ki",15,38,15,38]]]],"ahaz_118":["ابن يوثام، من أشر ملوك يهوذا. عبد الأوثان وأجاز ابنه في النار، ودنّس الهيكل. ولما هدده أرام وإسرائيل استنجد بملك أشور بدل الرب، فصار يهوذا تابعًا لأشور. بل صنع مذبحًا على مثال مذبح وثني ووضعه في بيت الرب. قصته مثال للاتكال على التحالفات السياسية بدل الله.",[["ملكه",["2Ki",16,2,16,2]],["إجازة ابنه في النار",["2Ki",16,3,16,3]],["الاستنجاد بأشور",["2Ki",16,7,16,9]],["المذبح الدمشقي",["2Ki",16,10,16,16]]]],"amon_236":["ابن منسى، ملك على يهوذا وهو ابن اثنتين وعشرين سنة، وعمل الشر مثل أبيه لكن دون توبته. عبد الأوثان وملك سنتين فقط ثم قتله عبيده، وملك بعده ابنه الصغير يوشيا الذي أزال شره. تُظهر قصته أن الله يقيم قادة أبرارًا حتى من آباء أشرار.",[["ملكه",["2Ki",21,19,21,19]],["عبادته الأوثان",["2Ki",21,21,21,21]],["قتله",["2Ki",21,23,21,23]]]],"jehoiakim_1085":["اسمه الأصلي ألياقيم، ابن يوشيا، أقامه فرعون نخو ملكًا وغيّر اسمه. كان ملكًا شريرًا ظلم الشعب وبنى قصورًا فخمة بالسخرة، وأحرق درج إرميا بالسكين والنار. تمرد على بابل فكان ذلك سبب السبي الأول. قصته مثال لرفض كلمة الله بتكبر.",[["فرعون نخو يملّكه",["2Ki",23,34,23,34]],["خضوعه لبابل",["2Ki",24,1,24,1]],["إحراقه درج إرميا",["Jer",36,23,36,23]],["موته",["2Ki",23,36,23,36]]]],"jehoiachin_791":["ويسمى أيضًا يهوياكين، ابن يهوياقيم، ملك على يهوذا ثلاثة أشهر فقط ثم حاصر نبوخذنصر أورشليم وأخذه أسيرًا إلى بابل. بقي في السجن سبعًا وثلاثين سنة حتى أطلقه أويل مرودخ وأكرمه. ويُذكر في نسب يسوع في متى، علامة على أن أمانة الله لنسل داود استمرت حتى وسط الدينونة.",[["ملكه",["2Ki",24,8,24,8]],["استسلامه لنبوخذنصر",["2Ki",24,12,24,12]],["سبيه إلى بابل",["2Ki",24,15,24,15]],["إطلاقه من السجن",["2Ki",25,27,25,30]]]],"zedekiah_1950":["اسمه الأصلي متنيا، ابن يوشيا، أقامه نبوخذنصر ملكًا وغيّر اسمه. ورغم تحذيرات إرميا المتكررة كان ملكًا ضعيفًا يتردد بين سماع النبي والخوف من رؤسائه. تمرده على بابل أدى إلى خراب أورشليم، فرأى قتل بنيه ثم أُعميت عيناه وأُخذ إلى بابل.",[["نبوخذنصر يملّكه",["2Ki",24,17,24,18]],["تمرده على بابل",["2Ki",24,20,24,20]],["حصار أورشليم",["2Ki",25,1,25,2]],["قتل بنيه وعماه وسبيه",["2Ki",25,6,25,7]]]],"asenath_335":["ابنة فوطي فارع كاهن أون، أعطاها فرعون زوجة ليوسف. ورغم أنها مصرية صارت أم منسى وأفرايم اللذين تبناهما يعقوب فصارا سبطين من أسباط إسرائيل، علامة على امتداد بركة العهد إلى من ينضمون إلى شعب الله.",[["زواجها بيوسف",["Gen",41,45,41,45]],["ميلاد منسى",["Gen",41,50,41,51]],["ميلاد أفرايم",["Gen",41,52,41,52]]]],"hagar_1348":["جارية سارة المصرية، أعطتها سارة لإبراهيم حين كانت عاقرًا، فولدت له إسماعيل ابنه الأول. ولما أذلتها سارة هربت، فوجدها ملاك الرب في البرية ووعدها أن يجعل إسماعيل أمة عظيمة. وبعد ميلاد إسحاق صُرفت هي وابنها، لكن الله أعطاها ماء وجدد الوعد. قصتها تُظهر عناية الله بالمنبوذ والمظلوم، ويستخدمها بولس رمزًا للفرق بين العبودية والحرية (غلاطية ٤).",[["سارة تعطيها لإبراهيم",["Gen",16,3,16,3]],["هروبها من سارة",["Gen",16,6,16,6]],["الملاك يجدها",["Gen",16,7,16,9]],["ميلاد إسماعيل",["Gen",16,15,16,15]],["صرفها مع إسماعيل",["Gen",21,14,21,14]],["الله يعطيها ماء ويجدد الوعد",["Gen",21,17,21,20]]]],"terah_2841":["أبو أبرام وناحور وهاران، عاش في أور الكلدانيين. وبعد موت هاران أخذ عائلته ومعهم أبرام وساراي ليذهبوا إلى كنعان، لكنه سكن في حاران ومات هناك ابن ٢٠٥ سنين، ثم أكمل أبرام الطريق بدعوة الله. ويذكر يشوع أن آباءهم عبدوا آلهة أخرى عبر النهر (يشوع ٢٤: ٢).",[["ميلاد أبرام وناحور وهاران",["Gen",11,26,11,26]],["خروجه من أور",["Gen",11,31,11,31]],["موته في حاران",["Gen",11,32,11,32]]]],"nahor_2143":["أخو إبراهيم وابن تارح، تزوج ملكة وبقي في ما بين النهرين حين رحل إبراهيم إلى كنعان. من نسله بتوئيل أبو رفقة، ولابان أبو راحيل، فمن عائلته جاءت زوجتا إسحاق ويعقوب.",[["زواجه بملكة",["Gen",11,29,11,29]],["أبو بتوئيل",["Gen",22,23,22,23]],["جد رفقة",["Gen",24,15,24,15]]]],"eber_1030":["من نسل سام ومن أجداد إبراهيم، عاش ٤٦٤ سنة. يُرجَّح أن اسم «العبرانيين» مشتق من اسمه. وهو أبو فالج الذي «في أيامه قُسمت الأرض». حلقة مهمة في النسب من نوح إلى إبراهيم.",[["ميلاد فالج",["Gen",11,16,11,16]],["موته",["Gen",11,17,11,17]]]],"ham_1359":["أحد أبناء نوح الثلاثة، نجا من الطوفان مع عائلته في الفلك. وبعد الطوفان أبصر عورة أبيه وأخبر أخويه بدل أن يسترها، فجاءت اللعنة على ابنه كنعان. ومن أبنائه كوش ومصرايم وفوط وكنعان.",[["ميلاده",["Gen",5,32,5,32]],["دخوله الفلك",["Gen",7,13,7,13]],["الخروج من الفلك",["Gen",8,18,8,18]],["عورة نوح ولعنة كنعان",["Gen",9,22,9,25]]]],"japheth_726":["أحد أبناء نوح الثلاثة، نجا من الطوفان في الفلك. ولما سكر أبوه وتعرّى، ستره هو وسام دون أن ينظرا. ومن أبنائه السبعة جاءت شعوب الجزائر والسواحل. وبركة نوح له «ليفتح الله ليافث فيسكن في مساكن سام» يرى فيها كثيرون إشارة إلى دخول الأمم في بركة العهد.",[["ميلاده",["Gen",5,32,5,32]],["دخوله الفلك",["Gen",7,13,7,13]],["الخروج من الفلك",["Gen",8,18,8,18]],["ستره أباه",["Gen",9,23,9,23]],["بركة نوح له",["Gen",9,27,9,27]]]],"rehoboam_2412":["ابن سليمان ونعمة، ملك بعد أبيه وهو ابن إحدى وأربعين سنة. ولما طلب الشعب أن يخفف عنهم النير الثقيل الذي وضعه سليمان، رفض مشورة الشيوخ وأخذ بمشورة الشبان وتوعدهم بقسوة أكبر، فانفصلت الأسباط العشرة وبقي له يهوذا وبنيامين. وفي أيامه غزا شيشق ملك مصر أورشليم واستمرت عبادة الأوثان.",[["ملكه",["1Ki",14,21,14,21]],["رفضه مشورة الشيوخ",["1Ki",12,8,12,8]],["انفصال الأسباط العشرة",["1Ki",12,16,12,17]],["غزو شيشق",["1Ki",14,25,14,25]]]],"asa_318":["ثالث ملوك يهوذا وابن أبيا، عمل المستقيم مثل داود: أزال المأبونين والأصنام، بل خلع جدته معكة من أن تكون ملكة لأنها عملت تمثالًا لسارية. انتصر على جيش الكوشيين بالاتكال على الله، واستراح يهوذا في معظم أيامه. لكنه في آخر ملكه اتكل على ملك أرام بدل الرب وسجن النبي الذي وبّخه. قصته عن أهمية الأمانة حتى النهاية.",[["ملكه",["1Ki",15,9,15,9]],["إزالة الأصنام",["1Ki",15,12,15,12]],["خلع معكة",["1Ki",15,13,15,13]],["الانتصار على الكوشيين",["2Ch",14,9,14,15]],["العهد لطلب الرب",["2Ch",15,12,15,12]],["اتكاله على أرام",["2Ch",16,2,16,7]],["سجنه حناني الرائي",["2Ch",16,10,16,10]]]]}};
